INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6437', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-12T21:00:53.808Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Turn off UAC''s privilege elevation for standard users [HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System] to automatically deny elevation requests, add: \"ConsentPromptBehaviorUser\"=dword:00000000 . Consider enabling installer detection for all users by adding: \"EnableInstallerDetection\"=dword:00000001 . This will prompt for a password for installation and also log the attempt. To disable installer detection, instead add: \"EnableInstallerDetection\"=dword:00000000 . This may prevent potential elevation of privileges through exploitation during the process of UAC detecting the installer, but will allow the installation process to continue without being logged.(Citation: Executable Installers are Vulnerable)", "external_references": [{"description": "Stefan Kanthak. (2015, December 8). Executable installers are vulnerable^WEVIL (case 7): 7z*.exe allows remote code execution with escalation of privilege. Retrieved December 4, 2014.", "source_name": "Executable Installers are Vulnerable", "url": "https://seclists.org/fulldisclosure/2015/Dec/34"}], "id": "relationship--df495b82-7bf4-4b1c-b72a-03dc1df07b7a", "modified": "2026-04-29T14:23:06.230Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2c2ad92a-d710-41ab-a996-1db143bb4808", "spec_version": "2.1", "target_ref": "attack-pattern--9e8b28c9-35fe-48ac-a14d-e6cc032dcbcd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6437', 0, 143, '09-mitre-attack', 'retrieved', 'D1CF71A457F6298B7A21F716768AEBB1426934F651BA897E368894B6C12CC87C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
