INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6441', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-11-27T13:52:46.031Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure settings for scheduled tasks to force tasks to run under the context of the authenticated account instead of allowing them to run as SYSTEM. The associated Registry key is located at HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\SubmitControl . The setting can be configured through GPO: Computer Configuration > [Policies] > Windows Settings > Security Settings > Local Policies > Security Options: Domain Controller: Allow server operators to schedule tasks, set to disabled. (Citation: TechNet Server Operator Scheduled Task) ", "external_references": [{"description": "Microsoft. (2012, November 15). Domain controller: Allow server operators to schedule tasks. Retrieved December 18, 2017.", "source_name": "TechNet Server Operator Scheduled Task", "url": "https://technet.microsoft.com/library/jj852168.aspx"}], "id": "relationship--1fdd8726-606a-482d-b371-044eea79be29", "modified": "2026-04-29T14:23:05.948Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--f3d95a1f-bba2-44ce-9af7-37866cd63fd0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6441', 0, 130, '09-mitre-attack', 'retrieved', 'E762172810433C0D81B156731F77D5FB8B32B2C598F83A4A72DD7B579B6B983D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
