INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6443', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T14:11:41.724Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Applications with known vulnerabilities or known shell escapes should not have the setuid or setgid bits set to reduce potential damage if an application is compromised. Additionally, the number of programs with setuid or setgid bits set should be minimized across a system.", "id": "relationship--3815ee11-af3f-48ae-b5b4-d0a0b2aa4d01", "modified": "2026-04-29T14:23:05.996Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--6831414d-bb70-42b7-8030-d4e06b2660c9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6443', 0, 72, '09-mitre-attack', 'retrieved', '09E26BC818426DE86A3D8034DD195F18871FCF5DFA310464625D8262EF19205C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
