VALUES ('doc-09-mitre-attack-p0-6447', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-25T18:30:50.111Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "There are multiple methods of preventing a user''s command history from being flushed to their .bash_history file, including use of the following commands:\n set +o history and set -o history to start logging again;\n unset HISTFILE being added to a user''s .bash_rc file; and\n ln -s /dev/null ~/.bash_history to write commands to /dev/null instead.", "id": "relationship--5401a61d-a795-4619-aa7e-fdf54cd4358e", "modified": "2026-04-29T14:23:06.040Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--435dfb86-2697-4867-85b5-2fef496c0517", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6447', 0, 83, '09-mitre-attack', 'retrieved', '25CD41863F4F6342AB4A458FD2D2A6ECEC474A83CE6073AE7561A7C1F2EE5E48', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
