VALUES ('doc-09-mitre-attack-p0-6449', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-13T16:47:55.972Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "\nConsider reducing the default BITS job lifetime in Group Policy or by editing the JobInactivityTimeout and MaxDownloadTime Registry values in HKEY_LOCAL_MACHINE\\Software\\Policies\\Microsoft\\Windows\\BITS .(Citation: Microsoft BITS)", "external_references": [{"description": "Microsoft. (n.d.). Background Intelligent Transfer Service. Retrieved January 12, 2018.", "source_name": "Microsoft BITS", "url": "https://msdn.microsoft.com/library/windows/desktop/bb968799.aspx"}], "id": "relationship--57d1a497-ef75-46de-b284-eefa90a99172", "modified": "2026-04-29T14:23:06.045Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--c8e87b83-edbb-48d4-9295-4974897525b7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6449', 0, 70, '09-mitre-attack', 'retrieved', 'A3CAAD750D315C89930DF4891921008A57A258B6B7D8AD3875692E379BA7C66E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
