VALUES ('doc-09-mitre-attack-p0-6450', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-25T19:19:09.960Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Change GPOs to define shorter timeouts sessions and maximum amount of time any single session can be active. Change GPOs to specify the maximum amount of time that a disconnected session stays active on the RD session host server.(Citation: Windows RDP Sessions)", "external_references": [{"description": "Microsoft. (n.d.). Configure Timeout and Reconnection Settings for Remote Desktop Services Sessions. Retrieved December 11, 2017.", "source_name": "Windows RDP Sessions", "url": "https://technet.microsoft.com/en-us/library/cc754272(v=ws.11).aspx"}], "id": "relationship--5d0c84c6-1f4b-4adf-924a-7b5489bd0933", "modified": "2026-04-29T14:23:06.052Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--e0033c16-a07e-48aa-8204-7c3ca669998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6450', 0, 95, '09-mitre-attack', 'retrieved', 'E000638BA77B2DF2D4C5DEE43FFF9FCF8951559052AC008E4D3445367FC5CD7F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
