VALUES ('doc-09-mitre-attack-p0-6451', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-19T03:09:48.191Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that Driver Signature Enforcement is enabled to restrict unsigned drivers from being installed. ", "id": "relationship--5eb23e3a-c1fb-4d96-99d1-65be2e0a76ca", "modified": "2026-04-29T14:23:06.054Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--106c0cf6-bf73-4601-9aa8-0945c2715ec5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6451', 0, 44, '09-mitre-attack', 'retrieved', '05F7655FF1299F2F51C57013EBF7A55E2B362DA1319A1F3EB1DFA8BFA0DCCD57', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
