VALUES ('doc-09-mitre-attack-p0-6455', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-17T20:22:08.552Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Prevent the creation of new network adapters where possible.(Citation: Microsoft GPO Bluetooth FEB 2009)(Citation: TechRepublic Wireless GPO FEB 2009)", "external_references": [{"description": "Microsoft. (2009, February 9). Disabling Bluetooth and Infrared Beaming. Retrieved July 26, 2018.", "source_name": "Microsoft GPO Bluetooth FEB 2009", "url": "https://technet.microsoft.com/library/dd252791.aspx"}, {"description": "Schauland, D. (2009, February 24). Configuring Wireless settings via Group Policy. Retrieved July 26, 2018.", "source_name": "TechRepublic Wireless GPO FEB 2009", "url": "https://www.techrepublic.com/blog/data-center/configuring-wireless-settings-via-group-policy/"}], "id": "relationship--818e5053-404d-4cc2-ba72-037767737e04", "modified": "2026-04-29T14:23:06.103Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--51ea26b1-ff1e-4faa-b1a0-1114cd298c87", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6455', 0, 95, '09-mitre-attack', 'retrieved', '62EA794F36B07C1AEEE32A89F2F37194298EE6C1CCDEC6AC4AD07A3B4B2DEC72', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
