VALUES ('doc-09-mitre-attack-p0-6456', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-16T15:12:49.247Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure only valid password filters are registered. Filter DLLs must be present in Windows installation directory (C:\\Windows\\System32\\ by default) of a domain controller and/or local computer with a corresponding entry in HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\Notification Packages.", "id": "relationship--9d439426-989c-4407-bbef-ac6af47896cc", "modified": "2026-04-29T14:23:06.139Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--3731fbcd-0e43-47ae-ae6c-d15e510f0d42", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6456', 0, 62, '09-mitre-attack', 'retrieved', '657D640895015E11244532BD61FF8018136F2CE5E5FA2B7E34020F04CF9F9C71', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
