VALUES ('doc-09-mitre-attack-p0-6458', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-21T15:58:20.433Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider limiting the number of cached credentials (HKLM\\SOFTWARE\\Microsoft\\Windows NT\\Current Version\\Winlogon\\cachedlogonscountvalue)(Citation: Tilbury Windows Credentials)", "external_references": [{"description": "Chad Tilbury. (2017, August 8). 1Windows Credentials: Attack, Mitigation, Defense. Retrieved February 21, 2020.", "source_name": "Tilbury Windows Credentials", "url": "https://www.first.org/resources/papers/conf2017/Windows-Credentials-Attacks-and-Mitigation-Techniques.pdf"}], "id": "relationship--a1ee7b5a-94cd-4b3a-aa53-55844968c28f", "modified": "2026-04-29T14:23:06.145Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--6add2ab5-2711-4e9d-87c8-7a0be8531530", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6458', 0, 64, '09-mitre-attack', 'retrieved', 'C31B7CFDE91F13B5A1E4728A66BA08338C7C77AE37E0DCF67BABDF37DBCC1852', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
