VALUES ('doc-09-mitre-attack-p0-6463', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-20T18:50:53.671Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider disabling or restricting NTLM.(Citation: Microsoft Disable NTLM Nov 2012)", "external_references": [{"description": "Microsoft. (2012, November 29). Using security policies to restrict NTLM traffic. Retrieved December 4, 2017.", "source_name": "Microsoft Disable NTLM Nov 2012", "url": "https://technet.microsoft.com/library/jj865668.aspx"}], "id": "relationship--afee7475-8e61-4bed-98f6-2cee6926e1c8", "modified": "2026-04-29T14:23:06.165Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--1644e709-12d2-41e5-a60f-3470991f5011", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6463', 0, 64, '09-mitre-attack', 'retrieved', 'C8AF9D7F7A46EAEEE4011C547AF201D58D1129FE11A80B14DF6A2D4FDB912A45', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
