VALUES ('doc-09-mitre-attack-p0-6464', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T14:34:45.390Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensuring that the tty_tickets setting is enabled will prevent this leakage across tty sessions.", "id": "relationship--b69490a4-3768-405e-856d-da11d95183e7", "modified": "2026-04-29T14:23:06.174Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--1365fe3b-0f50-455d-b4da-266ce31c23b0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6464', 0, 43, '09-mitre-attack', 'retrieved', 'B42D5E3971AE075DE1663B3C7AF2A90F2ACB921141982290DAFFC13B7743E1BA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
