VALUES ('doc-09-mitre-attack-p0-6466', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-16T20:53:20.687Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disallow or restrict removable media at an organizational policy level if they are not required for business operations.(Citation: TechNet Removable Media Control)", "external_references": [{"description": "Microsoft. (2007, August 31). https://technet.microsoft.com/en-us/library/cc771759(v=ws.10).aspx. Retrieved April 20, 2016.", "source_name": "TechNet Removable Media Control", "url": "https://technet.microsoft.com/en-us/library/cc772540(v=ws.10).aspx"}], "id": "relationship--c4b3287c-5e5a-4ec0-bc20-4e3b6a0c296f", "modified": "2026-04-29T14:23:06.194Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--64196062-5210-42c3-9a02-563a0d1797ef", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6466', 0, 69, '09-mitre-attack', 'retrieved', 'E3F01128284561857E7908486827F9CFDBE8CC2DD541060B60F3479DB3DDC695', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
