VALUES ('doc-09-mitre-attack-p0-6468', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-08-10T14:14:03.761Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disable the default to “hide file extensions for known file types” in Windows OS.(Citation: Seqrite DoubleExtension)(Citation: HowToGeek ShowExtension)", "external_references": [{"description": "Seqrite. (n.d.). How to avoid dual attack and vulnerable files with double extension?. Retrieved July 27, 2021.", "source_name": "Seqrite DoubleExtension", "url": "https://www.seqrite.com/blog/how-to-avoid-dual-attack-and-vulnerable-files-with-double-extension/"}, {"description": "Chris Hoffman. (2017, March 8). How to Make Windows Show File Extensions. Retrieved August 4, 2021.", "source_name": "HowToGeek ShowExtension", "url": "https://www.howtogeek.com/205086/beginner-how-to-make-windows-show-file-extensions/"}], "id": "relationship--cb0b7f7e-9ce2-4917-8eda-ae92080f6ff1", "modified": "2026-04-29T14:23:06.203Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--11f29a39-0942-4d62-92b6-fe236cf3066e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6468', 0, 93, '09-mitre-attack', 'retrieved', 'CF6F089637075DA47AE3A1E491930E87AFFF9EEB470C6B082FDED11434058782', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
