VALUES ('doc-09-mitre-attack-p0-6469', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T14:32:40.504Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "To use this technique remotely, an adversary must use it in conjunction with RDP. Ensure that Network Level Authentication is enabled to force the remote desktop session to authenticate before the session is created and the login screen displayed. It is enabled by default on Windows Vista and later.(Citation: TechNet RDP NLA)", "external_references": [{"description": "Microsoft. (n.d.). Configure Network Level Authentication for Remote Desktop Services Connections. Retrieved June 6, 2016.", "source_name": "TechNet RDP NLA", "url": "https://technet.microsoft.com/en-us/library/cc732713.aspx"}], "id": "relationship--cc458462-2c4e-443c-977a-805ea1d6e5a8", "modified": "2026-04-29T14:23:06.204Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--70e52b04-2a0c-4cea-9d18-7149f1df9dc5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6469', 0, 104, '09-mitre-attack', 'retrieved', '94988CFC18E8E50C3BC854E4AA2D6CFC51CFF199F791221768AB03159AA4B2D0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
