VALUES ('doc-09-mitre-attack-p0-6470', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-15T16:47:27.531Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Make sure that the HISTCONTROL environment variable is set to “ignoredups” instead of “ignoreboth” or “ignorespace”.", "id": "relationship--e0b2b128-aa44-478f-948f-ae53b67cfb6f", "modified": "2026-04-29T14:23:06.231Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--b831f51c-d22f-4724-bbab-60d056bd1150", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6470', 0, 45, '09-mitre-attack', 'retrieved', '65861E954EE974F8298DD1EF52240143B6816C724B6F7700C251706A957672F4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
