VALUES ('doc-09-mitre-attack-p0-6472', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-31T17:27:28.299Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Starting in Windows 11 22H2, the `EnableMPRNotifications` policy can be disabled through Group Policy or through a configuration service provider to prevent Winlogon from sending credentials to network providers.(Citation: EnableMPRNotifications)", "external_references": [{"description": "Microsoft. (2023, January 26). Policy CSP - WindowsLogon. Retrieved March 30, 2023.", "source_name": "EnableMPRNotifications", "url": "https://learn.microsoft.com/en-us/windows/client-management/mdm/policy-csp-windowslogon"}], "id": "relationship--f3ebb911-aab1-4aa8-aac8-0dcc2aec5343", "modified": "2026-04-29T14:23:06.256Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--90c4a591-d02d-490b-92aa-619d9701ac04", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6472', 0, 77, '09-mitre-attack', 'retrieved', 'CC48EC40EDB35A12BE6564911425FA0BC547ED36C98C1F5E3CF4AA7E8E35C8E3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
