VALUES ('doc-09-mitre-attack-p0-6474', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-03T18:21:39.015Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Protect domain controllers by ensuring proper security configuration for critical servers to limit access by potentially unnecessary protocols and services, such as SMB file sharing.", "id": "relationship--ff7f776f-001a-4c86-b359-08c89bd08b3e", "modified": "2026-04-29T14:23:06.272Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--2f316f6c-ae42-44fe-adf8-150989e0f6d3", "spec_version": "2.1", "target_ref": "attack-pattern--a10641f4-87b4-45a3-a906-92a149cb2c27", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6474', 0, 54, '09-mitre-attack', 'retrieved', '63409B0D83EC3D551068A182824A6D797770662AA373C897B4380124001D5B1E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
