VALUES ('doc-09-mitre-attack-p0-6482', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-20T14:34:08.725Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider implementing IT disaster recovery plans that contain procedures for taking regular data backups that can be used to restore organizational data.(Citation: Ready.gov IT DRP) Ensure backups are stored off system and is protected from common methods adversaries may use to gain access and destroy the backups to prevent recovery.", "external_references": [{"description": "Ready.gov. (n.d.). IT Disaster Recovery Plan. Retrieved March 15, 2019.", "source_name": "Ready.gov IT DRP", "url": "https://www.ready.gov/business/implementation/IT"}], "id": "relationship--f2fd105e-f481-486a-97b6-d5ef3324a787", "modified": "2026-04-29T14:23:06.255Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--3efe43d1-6f3f-4fcb-ab39-4a730971f70b", "spec_version": "2.1", "target_ref": "attack-pattern--0cfe31a7-81fc-472c-bc45-e2808d1066a3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6482', 0, 97, '09-mitre-attack', 'retrieved', '535172B45E3283465C69EF244036BFAC69E6B164DC2AA5047511444FBB8F70A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
