INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6484', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-19T14:37:37.517Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider implementing IT disaster recovery plans that contain procedures for taking regular data backups that can be used to restore organizational data.(Citation: Ready.gov IT DRP) Ensure backups are stored off system and is protected from common methods adversaries may use to gain access and destroy the backups to prevent recovery. In cloud environments, enable versioning on storage objects where possible, and copy backups to other accounts or regions to isolate them from the original copies.(Citation: Unit 42 Palo Alto Ransomware in Public Clouds 2022) On ESXi servers, ensure that disk images and snapshots of virtual machines are regularly taken, with copies stored off system.(Citation: Crowdstrike Hypervisor Jackpotting Pt 2 2021)", "external_references": [{"description": "Jay Chen. (2022, May 16). A Look Into Public Clouds From the Ransomware Actor''s Perspective. Retrieved March 21, 2023.", "source_name": "Unit 42 Palo Alto Ransomware in Public Clouds 2022", "url": "https://unit42.paloaltonetworks.com/ransomware-in-public-clouds/"}, {"description": "Michael Dawson. (2021, August 30). Hypervisor Jackpotting, Part 2: eCrime Actors Increase Targeting of ESXi Servers with Ransomware. Retrieved March 26, 2025.", "source_name": "Crowdstrike Hypervisor Jackpotting Pt 2 2021", "url": "https://www.crowdstrike.com/en-us/blog/hypervisor-jackpotting-ecrime-actors-increase-targeting-of-esxi-servers/"}, {"description": "Ready.gov. (n.d.). IT Disaster Recovery Plan. Retrieved March 15, 2019.", "source_name": "Ready.gov IT DRP", "url": "https://www.ready.gov/business/implementation/IT"}], "id": "relationship--f9e62f6d-a091-44a9-91e6-3660b89ba2b9", "modified": "2026-04-29T14:23:06.264Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--3efe43d1-6f3f-4fcb-ab39-4a730971f70b", "spec_version": "2.1", "target_ref": "attack-pattern--f5d8eed6-48a9-4cdf-a3d7-d1ffa99c3d2a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6484', 0, 221, '09-mitre-attack', 'retrieved', 'F9E117CF141F7BE07EA1EF19A55974A3AC60ECECAACF2398462D9517657E753F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
