VALUES ('doc-09-mitre-attack-p0-6487', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-05T19:34:05.079Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enable application control solutions such as AppLocker and/or Device Guard to block the loading of malicious SIP DLLs.", "id": "relationship--08dd36a7-dee0-4f25-b3dc-d030c32151f5", "modified": "2026-04-29T14:23:05.915Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--543fceb5-cb92-40cb-aacf-6913d4db58bc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6487', 0, 47, '09-mitre-attack', 'retrieved', 'D753879E178BBA0CA3E8E8A3980617C11B02F43E872DE9126888BDA811D70A44', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
