VALUES ('doc-09-mitre-attack-p0-6488', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-29T18:50:06.240Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use application control to prevent execution of `AutoIt3.exe`, `AutoHotkey.exe`, and other related features that may not be required for a given system or network to prevent potential misuse by adversaries.", "id": "relationship--09082234-c658-45c4-9cd0-d4984b6bdf85", "modified": "2026-04-29T14:23:05.916Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--3a32740a-11b0-4bcf-b0a9-3abd0f6d3cd5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6488', 0, 59, '09-mitre-attack', 'retrieved', '37AA374C338AE1FAFF039B52288F060FDADDE8E34B0ADA7433351B303BE9E057', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
