VALUES ('doc-09-mitre-attack-p0-6489', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-10T20:43:10.395Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use tools that restrict program execution via application control by attributes other than file name for common operating system utilities that are needed.", "id": "relationship--095e5f7b-288c-4995-8045-b691602d38c9", "modified": "2026-04-29T14:23:05.916Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6489', 0, 52, '09-mitre-attack', 'retrieved', '188165DE239E2166E4744484DDB28713E2479C6C2323FE829763DA5F4081C08E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
