VALUES ('doc-09-mitre-attack-p0-6491', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-26T18:45:03.794Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may use new payloads to execute this technique. Identify and block potentially malicious software executed through hijacking by using application control solutions also capable of blocking libraries loaded by legitimate software.", "id": "relationship--0fc95a6b-296f-41ab-8663-aea4a80afe0a", "modified": "2026-04-29T14:23:05.925Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--633a100c-b2c9-41bf-9be5-905c1b16c825", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6491', 0, 61, '09-mitre-attack', 'retrieved', '97F685FF23D44E27034B2B77495609DB7045F4770566B1452AF959594D4613DC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
