VALUES ('doc-09-mitre-attack-p0-6494', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-27T13:14:04.866Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "System settings can prevent applications from running that haven''t been downloaded through the Apple Store (or other legitimate repositories) which can help mitigate some of these issues. Also enable application control solutions such as AppLocker and/or Device Guard to block the loading of malicious content.", "id": "relationship--15b9b22e-7896-4219-8ec9-59b099644a6f", "modified": "2026-04-29T14:23:05.934Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--b83e166d-13d7-4b52-8677-dff90c548fd7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6494', 0, 74, '09-mitre-attack', 'retrieved', 'DDE7BDE332237EF19271CF04F435CD462AAC32B2FFF5F296EE19222D0183EB39', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
