VALUES ('doc-09-mitre-attack-p0-6495', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-30T22:24:59.021Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Set an IDE extension allow or deny list as appropriate for your security policy. ", "id": "relationship--16a6739b-93e9-49ea-ae74-624623d3c07a", "modified": "2026-04-29T14:23:05.935Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--66b34be7-6915-4b83-8d5a-b0f0592b5e41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6495', 0, 44, '09-mitre-attack', 'retrieved', '0BEB16F2B7A54D4586C22B176C9F3F673FCB131652EDDE4792603278679EC7BF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
