VALUES ('doc-09-mitre-attack-p0-6498', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-23T19:09:49.092Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use application control configured to block execution of InstallUtil.exe if it is not required for a given system or network to prevent potential misuse by adversaries.", "id": "relationship--21ce896b-e6b5-4075-8d97-6b59c269247c", "modified": "2026-04-29T14:23:05.951Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--2cd950a6-16c4-404a-aa01-044322395107", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6498', 0, 55, '09-mitre-attack', 'retrieved', 'E728F30F65A48D81F43AB25129B9161E42E2CCB7FFDF4C00BFA9A322C2F96D98', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
