VALUES ('doc-09-mitre-attack-p0-6499', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T16:28:45.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Application control may be able to prevent the running of executables masquerading as other files.", "id": "relationship--225ab1b4-f800-4a92-9949-a0f05fce6213", "modified": "2026-04-29T14:23:05.952Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--8c32eb4d-805f-4fc5-bf60-c4d476c131b5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6499', 0, 44, '09-mitre-attack', 'retrieved', 'A90B85317ABFC2BC6D8678713DE23B9A14292BC1EDCEB62DCD06393B8146C979', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
