VALUES ('doc-09-mitre-attack-p0-6501', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-04-14T16:49:17.897Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use application control where appropriate. PowerShell Constrained Language mode can be used to restrict access to sensitive or otherwise dangerous language elements such as those used to execute arbitrary Windows APIs or files (e.g., `Add-Type`).(Citation: Microsoft PowerShell CLM)", "external_references": [{"description": "PowerShell Team. (2017, November 2). PowerShell Constrained Language Mode. Retrieved March 27, 2023.", "source_name": "Microsoft PowerShell CLM", "url": "https://devblogs.microsoft.com/powershell/powershell-constrained-language-mode/"}], "id": "relationship--26d910c5-b1e9-4318-a715-dd1059fead3b", "modified": "2026-04-29T14:23:05.958Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--e261a979-f354-41a8-963e-6cadac27c4bf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6501', 0, 88, '09-mitre-attack', 'retrieved', 'C90D9EAD4604FC8991FF65C3919762921660A0AA842843003A02BC5C3F97145C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
