VALUES ('doc-09-mitre-attack-p0-6502', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-17T20:12:19.105Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identify and block potentially malicious software executed through this technique by using application control tools capable of preventing unknown modules from being loaded.", "id": "relationship--2c89cab1-efbb-405c-930d-197ae1910e5b", "modified": "2026-04-29T14:23:05.965Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--0a5231ec-41af-4a35-83d0-6bdf11f28c65", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6502', 0, 52, '09-mitre-attack', 'retrieved', '15EBF4537506805D132322416CEB95D9440BBAA9FA0DCD8A030C33C70C4DC8D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
