VALUES ('doc-09-mitre-attack-p0-6503', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-23T19:42:16.784Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Block execution of Regsvcs.exe and Regasm.exe if they are not required for a given system or network to prevent potential misuse by adversaries.", "id": "relationship--2d712b2d-a9a6-4efd-b37e-1219768bdde7", "modified": "2026-04-29T14:23:05.966Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--c48a67ee-b657-45c1-91bf-6cdbe27205f8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6503', 0, 52, '09-mitre-attack', 'retrieved', '93D9903E9D0C211DF33E0B32884BA4F496E8A0529AE2338AB025D0B41870B73E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
