VALUES ('doc-09-mitre-attack-p0-6504', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-27T12:10:23.761Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "System settings can prevent applications from running that haven''t been downloaded from legitimate repositories which may help mitigate some of these issues. Not allowing unsigned applications from being run may also mitigate some risk.", "id": "relationship--35428082-1010-4e0e-ac4c-9f1426de7796", "modified": "2026-04-29T14:23:05.991Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--67720091-eee3-4d2d-ae16-8264567f6f5b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6504', 0, 63, '09-mitre-attack', 'retrieved', '044CFC7519401196301A207A7A5A154AE85266BD46B78A25846E76CE40731E54', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
