VALUES ('doc-09-mitre-attack-p0-6505', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T14:40:20.608Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "System settings can prevent applications from running that haven''t been downloaded through the Apple Store which may help mitigate some of these issues. Not allowing unsigned applications from being run may also mitigate some risk.", "id": "relationship--362b2f10-f599-4663-9cff-27932e11935a", "modified": "2026-04-29T14:23:05.993Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--b84903f0-c7d5-435d-a69e-de47cc3578c0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6505', 0, 64, '09-mitre-attack', 'retrieved', 'F92A93B5CCBAD70709D00746C729661CA49472D7B345247BB82196D2E14A2449', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
