VALUES ('doc-09-mitre-attack-p0-6506', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-30T17:38:34.719Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use read-only containers, read-only file systems, and minimal images when possible to prevent the running of commands.(Citation: Kubernetes Hardening Guide) Where possible, also consider using application control and software restriction tools (such as those provided by SELinux) to restrict access to files, processes, and system calls in containers.(Citation: Kubernetes Security Context)", "external_references": [{"description": "Kubernetes. (n.d.). Configure a Security Context for a Pod or Container. Retrieved March 8, 2023.", "source_name": "Kubernetes Security Context", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/security-context/"}, {"description": "National Security Agency, Cybersecurity and Infrastructure Security Agency. (2022, March). Kubernetes Hardening Guide. Retrieved April 1, 2022.", "source_name": "Kubernetes Hardening Guide", "url": "https://media.defense.gov/2022/Aug/29/2003066362/-1/-1/0/CTR_KUBERNETES_HARDENING_GUIDANCE_1.2_20220829.PDF"}], "id": "relationship--365897c8-a97b-42e0-8fb8-cc08c23545df", "modified": "2026-04-29T14:23:05.994Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--4a5b7ade-8bb5-4853-84ed-23f262002665", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6506', 0, 127, '09-mitre-attack', 'retrieved', 'DC30977063B12F810D01D8186D45ECF5194668FC60954C8BA6AD0113CA13D984', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": 