VALUES ('doc-09-mitre-attack-p0-6507', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-03T16:49:58.298Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Certain signed scripts that can be used to execute other programs may not be necessary within a given environment. Use application control configured to block execution of these scripts if they are not required for a given system or network to prevent potential misuse by adversaries.", "id": "relationship--387cdc83-fc81-499e-8875-e3d4789af9c3", "modified": "2026-04-29T14:23:05.997Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--09cd431f-eaf4-4d2a-acaf-2a7acfe7ed58", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6507', 0, 75, '09-mitre-attack', 'retrieved', 'DC3EE0CFDFAA410319F43CAE1BFF363EB9E5DEF77C8FF7EC8855148775546E9C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
