VALUES ('doc-09-mitre-attack-p0-6508', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-10-07T21:34:07.314Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Prevents malicious shortcuts or LNK files from executing unwanted code by ensuring only authorized applications and scripts are allowed to run.", "id": "relationship--3c0938ab-9272-492b-96f6-df6caea210e5", "modified": "2026-04-29T14:23:06.004Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--4ab929c6-ee2d-4fb5-aab4-b14be2ed7179", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6508', 0, 50, '09-mitre-attack', 'retrieved', '499382B603AB2EF2004EED61FEDBAA85168B44AA4055BF0321856A0F792CA9CC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
