VALUES ('doc-09-mitre-attack-p0-6509', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-10T13:59:38.605Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use application control configured to block execution of verclsid.exe if it is not required for a given system or network to prevent potential misuse by adversaries.", "id": "relationship--423ba5d2-6400-4e35-ba8e-dfbedd0b5303", "modified": "2026-04-29T14:23:06.015Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--808e6329-ca91-4b87-ac2d-8eadc5f8f327", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6509', 0, 55, '09-mitre-attack', 'retrieved', 'E6439FA0BB3567C42A396B0567BF9880D464EC1FF5F4B50B3D1C2E66B6160420', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
