INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6515', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-28T00:48:40.969Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use application control configured to block execution of wmic.exe if it is not required for a given system or network to prevent potential misuse by adversaries. For example, in Windows 10 and Windows Server 2016 and above, Windows Defender Application Control (WDAC) policy rules may be applied to block the wmic.exe application and to prevent abuse.(Citation: Microsoft WDAC)", "external_references": [{"description": "Coulter, D. et al.. (2019, April 9). Microsoft recommended block rules. Retrieved August 12, 2021.", "source_name": "Microsoft WDAC", "url": "https://docs.microsoft.com/windows/security/threat-protection/windows-defender-application-control/microsoft-recommended-block-rules"}], "id": "relationship--55670baa-97b1-44fe-abb8-0162b5a9663b", "modified": "2026-04-29T14:23:06.042Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--01a5a209-b94c-450b-b7f9-946497d91055", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6515', 0, 109, '09-mitre-attack', 'retrieved', 'ADB779A9F537351FCBA785B0C38E3C509423148A540812BB9E8BC4F0203407A7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
