VALUES ('doc-09-mitre-attack-p0-6517', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-23T19:12:25.113Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Denylist scripting where appropriate.", "id": "relationship--5853af0d-4716-4290-b3d9-63fadfd5f554", "modified": "2026-04-29T14:23:06.046Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--0f4a0c76-ab2d-4cb0-85d3-3f0efb8cba0d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6517', 0, 33, '09-mitre-attack', 'retrieved', 'AC8B7ECF8FADBB38F5913A1FA67D11F1ED148C740E1B31B214F49BCBDD64FA75', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
