VALUES ('doc-09-mitre-attack-p0-6518', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-11T14:49:37.065Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Application control may be able to prevent the running of executables masquerading as other files.", "id": "relationship--60e4698b-a16d-4a40-8473-4d88e2e70881", "modified": "2026-04-29T14:23:06.057Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--232b7f21-adf9-4b42-b936-b9d6f7df856e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6518', 0, 44, '09-mitre-attack', 'retrieved', '59276025A393DBCCACF4BAAE69A167E1834B17D94E17A4A471FE3210A4D75F5E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
