VALUES ('doc-09-mitre-attack-p0-6522', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-03T19:09:07.312Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Restrict unallowed ISAPI extensions and filters from running by specifying a list of ISAPI extensions and filters that can run on IIS.(Citation: Microsoft ISAPICGIRestriction 2016)", "external_references": [{"description": "Microsoft. (2016, September 26). ISAPI/CGI Restrictions . Retrieved June 3, 2021.", "source_name": "Microsoft ISAPICGIRestriction 2016", "url": "https://docs.microsoft.com/en-us/iis/configuration/system.webserver/security/isapicgirestriction/"}], "id": "relationship--7742d5c6-6987-4a87-92e9-c213880d911a", "modified": "2026-04-29T14:23:06.088Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--b46a801b-fd98-491c-a25a-bca25d6e3001", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6522', 0, 73, '09-mitre-attack', 'retrieved', 'BE4D23EE05D71226392EF4723BC05FE03DA12748017403D7D2496116B145506B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
