VALUES ('doc-09-mitre-attack-p0-6524', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-09T14:07:54.876Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use application control where appropriate.", "id": "relationship--809f6537-c7f8-4d96-ba16-5bffa897b52f", "modified": "2026-04-29T14:23:06.101Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--37b11151-1776-4f8f-b328-30939fbf2ceb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6524', 0, 34, '09-mitre-attack', 'retrieved', 'E2F669F5AE2FDF1BE08434572D46E2311916374AC1EF5AD8BAF21CAF3AD57BF2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
