INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6525', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-05T16:16:08.599Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "System settings can prevent applications from running that haven''t been downloaded through the Apple Store which can help mitigate some of these issues. ", "id": "relationship--819bc603-b0fe-4681-a235-3c6e9a36e3b5", "modified": "2026-04-29T14:23:06.103Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--31a0a2ac-c67c-4a7e-b9ed-6a96477d4e8e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6525', 0, 53, '09-mitre-attack', 'retrieved', 'CD787B39EEA158703BBD2356D0A9AC449DC4E65B9600925DFC9D1040B0915E14', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
