INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6526', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-08T23:02:44.481Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that input sanitization is performed and that files are validated properly before execution; furthermore, implement a strict allow list to ensure that only authorized file types are processed.(Citation: file_upload_attacks_pt2) Restrict and/or block execution of files where headers and extensions do not match. \n\n", "external_references": [{"description": "YesWeRHackers. (2021, June 16). File Upload Attacks (Part 2). Retrieved August 23, 2022.", "source_name": "file_upload_attacks_pt2", "url": "https://blog.yeswehack.com/yeswerhackers/file-upload-attacks-part-2/"}], "id": "relationship--84185ab0-a7f3-4629-b553-dc6e24b0ed14", "modified": "2026-04-29T14:23:06.106Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--208884f1-7b83-4473-ac22-4e1cf6c41471", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6526', 0, 92, '09-mitre-attack', 'retrieved', '89293CE852053174FBB8F36613DF4E87F789A01D9547F5F33240C30A4603A8E9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
