VALUES ('doc-09-mitre-attack-p0-6527', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T15:01:33.187Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use application control configured to block execution of Odbcconf.exe if it is not required for a given system or network to prevent potential misuse by adversaries.", "id": "relationship--8541e1a0-0cd5-44fc-bc88-c96b474bcaeb", "modified": "2026-04-29T14:23:06.107Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--6e3bd510-6b33-41a4-af80-2d80f3ee0071", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6527', 0, 55, '09-mitre-attack', 'retrieved', 'E9750109730AC60B0E84310FB135C038C5CABA59B0E91457881BD4EC3B48ADDF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
