VALUES ('doc-09-mitre-attack-p0-6531', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T16:52:53.737Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Certain developer utilities should be blocked or restricted if not required.", "id": "relationship--8c0286e0-036d-4282-9e54-6938c958b7e9", "modified": "2026-04-29T14:23:06.116Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--ff25900d-76d5-449b-a351-8824e62fc81b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6531', 0, 40, '09-mitre-attack', 'retrieved', 'B9A2F4BCFB35C2C7013124ABAE82F435B65A7228C965B202BDAE35624A34FAFD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
