VALUES ('doc-09-mitre-attack-p0-6534', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-29T17:17:31.597Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider using application control to prevent execution of binaries that are susceptible to abuse and not required for a given system or network.", "id": "relationship--95e4e360-b867-48b4-a494-d9d148232b70", "modified": "2026-04-29T14:23:06.129Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--457c7820-d331-465a-915e-42f85500ccc4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6534', 0, 52, '09-mitre-attack', 'retrieved', 'BAB4B2057B01769E35939DEDE8E29515F33BD343AC309BD55EA5C9D8C3668D3B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
