VALUES ('doc-09-mitre-attack-p0-6540', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-13T17:55:25.713Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use application control where appropriate to block use of PowerShell CmdLets or other host based resources to access cloud API resources.", "id": "relationship--b42d990f-4fa7-40be-9018-73c75130fcfe", "modified": "2026-04-29T14:23:06.171Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--55bb4471-ff1f-43b4-88c1-c9384ec47abf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6540', 0, 50, '09-mitre-attack', 'retrieved', '18583F18DA79A33CCCD83738DE748D4D061D31522BBE29DDA59E6EE750D657A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
