VALUES ('doc-09-mitre-attack-p0-6541', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T17:42:23.786Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Application control and software restriction tools, such as SELinux, KSPP, grsecurity MODHARDEN, and Linux kernel tuning can aid in restricting kernel module loading.(Citation: Kernel.org Restrict Kernel Module)(Citation: Wikibooks Grsecurity)(Citation: Kernel Self Protection Project)(Citation: Increasing Linux kernel integrity)(Citation: LKM loading kernel restrictions)", "external_references": [{"description": "Boelen, M. (2015, October 7). Increase kernel integrity with disabled Linux kernel modules loading. Retrieved June 4, 2020.", "source_name": "Increasing Linux kernel integrity", "url": "https://linux-audit.com/increase-kernel-integrity-with-disabled-linux-kernel-modules-loading/"}, {"description": "Kernel.org. (2020, February 6). Kernel Self-Protection. Retrieved June 4, 2020.", "source_name": "Kernel Self Protection Project", "url": "https://www.kernel.org/doc/html/latest/security/self-protection.html"}, {"description": "Pingios, A.. (2018, February 7). LKM loading kernel restrictions. Retrieved June 4, 2020.", "source_name": "LKM loading kernel restrictions", "url": "https://xorl.wordpress.com/2018/02/17/lkm-loading-kernel-restrictions/"}, {"description": "Vander Stoep, J. (2016, April 5). [v3] selinux: restrict kernel module loadinglogin register. Retrieved April 9, 2018.", "source_name": "Kernel.org Restrict Kernel Module", "url": "https://patchwork.kernel.org/patch/8754821/"}, {"description": "Wikibooks. (2018, August 19). Grsecurity/The RBAC System. Retrieved June 4, 2020.", "source_name": "Wikibooks Grsecurity", "url": "https://en.wikibooks.org/wiki/Grsecurity/The_RBAC_System"}], "id": "relationship--b783f90e-bd7c-4513-b15a-731637d7078d", "modified": "2026-04-29T14:23:06.176Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-