VALUES ('doc-09-mitre-attack-p0-6544', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-15T21:42:37.421Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Deny scripting where appropriate. Tools such as Python or Go can utilize Kubernetes and Docker within a client library and execute commands within their application.", "id": "relationship--be741f5c-f01f-4004-abb4-432882277636", "modified": "2026-04-29T14:23:06.186Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--c283d88f-8c23-4318-9da5-3d50cecad756", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6544', 0, 54, '09-mitre-attack', 'retrieved', '54EA5D8C542B49432F33A52AD76789D56D5359177309BC386A7E471E37024773', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
