VALUES ('doc-09-mitre-attack-p0-6546', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-28T00:45:50.820Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use application control configured to block execution of msbuild.exe if it is not required for a given system or network to prevent potential misuse by adversaries. For example, in Windows 10 and Windows Server 2016 and above, Windows Defender Application Control (WDAC) policy rules may be applied to block the msbuild.exe application and to prevent abuse.(Citation: Microsoft WDAC)", "external_references": [{"description": "Coulter, D. et al.. (2019, April 9). Microsoft recommended block rules. Retrieved August 12, 2021.", "source_name": "Microsoft WDAC", "url": "https://docs.microsoft.com/windows/security/threat-protection/windows-defender-application-control/microsoft-recommended-block-rules"}], "id": "relationship--c755a235-d278-41ed-835c-48e831b6d1a5", "modified": "2026-04-29T14:23:06.198Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--c92e3d68-2349-49e4-a341-7edca2deff96", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6546', 0, 109, '09-mitre-attack', 'retrieved', '83B191A3EA21400BDED04CDFFE57E7215E6059DB7CE37C479B67B1E7530A57ED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
