VALUES ('doc-09-mitre-attack-p0-6551', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-16T22:47:15.398Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider blocking the execution of known vulnerable drivers that adversaries may exploit to execute code in kernel mode. Validate driver block rules in audit mode to ensure stability prior to production deployment.(Citation: Microsoft Driver Block Rules)", "external_references": [{"description": "Microsoft. (2020, October 15). Microsoft recommended driver block rules. Retrieved March 16, 2021.", "source_name": "Microsoft Driver Block Rules", "url": "https://docs.microsoft.com/en-us/windows/security/threat-protection/windows-defender-application-control/microsoft-recommended-driver-block-rules"}], "id": "relationship--dd9a12ee-30b1-4764-860d-111c73411ebe", "modified": "2026-04-29T14:23:06.228Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--b21c3b2d-02e6-45b1-980b-e69051040839", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6551', 0, 87, '09-mitre-attack', 'retrieved', '4E82C40D7EE740635F9F8F42499337173A5FF7D7BCF6B415C548C510D308FD1E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
