VALUES ('doc-09-mitre-attack-p0-6561', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-29T16:39:26.339Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use read-only containers, read-only file systems, and minimal images when possible to prevent the execution of commands.(Citation: Kubernetes Hardening Guide) Where possible, also consider using application control and software restriction tools (such as those provided by SELinux) to restrict access to files, processes, and system calls in containers.(Citation: Kubernetes Security Context)", "external_references": [{"description": "Kubernetes. (n.d.). Configure a Security Context for a Pod or Container. Retrieved March 8, 2023.", "source_name": "Kubernetes Security Context", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/security-context/"}, {"description": "National Security Agency, Cybersecurity and Infrastructure Security Agency. (2022, March). Kubernetes Hardening Guide. Retrieved April 1, 2022.", "source_name": "Kubernetes Hardening Guide", "url": "https://media.defense.gov/2022/Aug/29/2003066362/-1/-1/0/CTR_KUBERNETES_HARDENING_GUIDANCE_1.2_20220829.PDF"}], "id": "relationship--fd9cf3cc-51cd-4f13-b90e-2b8e274a4cc1", "modified": "2026-04-29T14:23:06.269Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--7b50a1d3-4ca7-45d1-989d-a6503f04bfe1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6561', 0, 127, '09-mitre-attack', 'retrieved', '1E0B07D27692000763A4625D3E3F2E49B2A27D388617DFB52DF1F0E3609DE61B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version"