VALUES ('doc-09-mitre-attack-p0-6563', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-05-28T14:56:24.055Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use application control where appropriate. PowerShell Constrained Language mode can be used to restrict access to sensitive or otherwise dangerous language elements such as those used to execute arbitrary Windows APIs or files (e.g., `Add-Type`).(Citation: Microsoft PowerShell CLM)", "external_references": [{"description": "PowerShell Team. (2017, November 2). PowerShell Constrained Language Mode. Retrieved March 27, 2023.", "source_name": "Microsoft PowerShell CLM", "url": "https://devblogs.microsoft.com/powershell/powershell-constrained-language-mode/"}], "id": "relationship--fe42b5e6-06dd-4b08-8ef8-31323f8190d2", "modified": "2026-04-29T14:23:06.270Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--47e0e9fe-96ce-4f65-8bb1-8be1feacb5db", "spec_version": "2.1", "target_ref": "attack-pattern--970a3432-3237-47ad-bcca-7d8cbb217736", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6563', 0, 88, '09-mitre-attack', 'retrieved', 'EF7E3B52841D40BAB7C0418F46B7204435C0898FABF071C9C3F866FAE86E0267', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
