VALUES ('doc-09-mitre-attack-p0-6564', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T16:48:08.525Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Some embedded network devices are capable of storing passwords for local accounts in either plain-text or encrypted formats. Ensure that, where available, local passwords are always encrypted, per vendor recommendations. (Citation: Cisco IOS Software Integrity Assurance - AAA)", "external_references": [{"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - AAA. Retrieved October 19, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - AAA", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#38"}], "id": "relationship--56499082-a21f-4d6d-9bdd-8ee6b2dfcad4", "modified": "2026-04-29T14:23:06.043Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--49c06d54-9002-491d-9147-8efb537fbd26", "spec_version": "2.1", "target_ref": "attack-pattern--4ffc1794-ec3b-45be-9e52-42dbcb2af2de", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6564', 0, 92, '09-mitre-attack', 'retrieved', 'EE3A951450B49EDD99566BD205145FB8D725BD93F7D1F5651FEDBEE88FC899A5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
