VALUES ('doc-09-mitre-attack-p0-6565', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T18:38:56.162Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "On Windows 10 and Server 2016, enable Windows Defender Credential Guard (Citation: Microsoft Enable Cred Guard April 2017) to run lsass.exe in an isolated virtualized environment without any device drivers. (Citation: Microsoft Credential Guard April 2017)", "external_references": [{"description": "Lich, B., Tobin, J., Hall, J. (2017, April 5). Manage Windows Defender Credential Guard. Retrieved November 27, 2017.", "source_name": "Microsoft Enable Cred Guard April 2017", "url": "https://docs.microsoft.com/windows/access-protection/credential-guard/credential-guard-manage"}, {"description": "Lich, B., Tobin, J. (2017, April 5). How Windows Defender Credential Guard works. Retrieved November 27, 2017.", "source_name": "Microsoft Credential Guard April 2017", "url": "https://docs.microsoft.com/windows/access-protection/credential-guard/credential-guard-how-it-works"}], "id": "relationship--6ca7aa45-86c5-4ba7-bd43-8d9446fb05d2", "modified": "2026-04-29T14:23:06.073Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--49c06d54-9002-491d-9147-8efb537fbd26", "spec_version": "2.1", "target_ref": "attack-pattern--f0589bc3-a6ae-425a-a3d5-5659bfee07f4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6565', 0, 120, '09-mitre-attack', 'retrieved', 'A333A420D5CF1307C64397A0972E05A635577464609681FC61FEB36331B5AD36', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
