VALUES ('doc-09-mitre-attack-p0-6573', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-16T20:44:09.399Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Several cloud service providers support content trust models that require container images be signed by trusted sources.(Citation: Content trust in Azure Container Registry)(Citation: Content trust in Docker)", "external_references": [{"description": "Microsoft. (2019, September 5). Content trust in Azure Container Registry. Retrieved October 16, 2019.", "source_name": "Content trust in Azure Container Registry", "url": "https://docs.microsoft.com/en-us/azure/container-registry/container-registry-content-trust"}, {"description": "Docker. (2019, October 10). Content trust in Docker. Retrieved October 16, 2019.", "source_name": "Content trust in Docker", "url": "https://docs.docker.com/engine/security/trust/content_trust/"}], "id": "relationship--24e20a3c-5f74-40bc-a5b0-108bc0233305", "modified": "2026-04-29T14:23:05.956Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--590777b3-b475-4c7c-aaf8-f4a73b140312", "spec_version": "2.1", "target_ref": "attack-pattern--4fd8a28b-4b3a-4cd6-a8cf-85ba5f824a7f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6573', 0, 101, '09-mitre-attack', 'retrieved', '09F3AD97F3C286605DE5C5EAF18F9E95BAA47DDC5A067A4C0B5C6C66022146D0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
