VALUES ('doc-09-mitre-attack-p0-6574', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-09T14:07:54.886Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Require that all AppleScript be signed by a trusted developer ID before being executed - this will prevent random AppleScript code from executing.(Citation: applescript signing) This subjects AppleScript code to the same scrutiny as other .app files passing through Gatekeeper.", "external_references": [{"description": "Steven Sande. (2013, December 23). AppleScript and Automator gain new features in OS X Mavericks. Retrieved September 21, 2018.", "source_name": "applescript signing", "url": "https://www.engadget.com/2013/10/23/applescript-and-automator-gain-new-features-in-os-x-mavericks/"}], "id": "relationship--256ce066-f81e-4cc4-bd5e-d83f7881f109", "modified": "2026-04-29T14:23:05.956Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--590777b3-b475-4c7c-aaf8-f4a73b140312", "spec_version": "2.1", "target_ref": "attack-pattern--37b11151-1776-4f8f-b328-30939fbf2ceb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6574', 0, 95, '09-mitre-attack', 'retrieved', '1399B9041173CD387DD78DAA3D3E49E8614A9E6A17540A1BC6DC8F963B769828', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
