VALUES ('doc-09-mitre-attack-p0-6581', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T19:49:24.464Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Many vendors provide digitally signed operating system images to validate the integrity of the software used on their platform. Make use of this feature where possible in order to prevent and/or detect attempts by adversaries to compromise the system image. (Citation: Cisco IOS Software Integrity Assurance - Deploy Signed IOS)", "external_references": [{"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - Deploy Signed IOS. Retrieved October 21, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - Deploy Signed IOS", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#34"}], "id": "relationship--731ba292-7016-4ccf-a296-58ced0421a37", "modified": "2026-04-29T14:23:06.083Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--590777b3-b475-4c7c-aaf8-f4a73b140312", "spec_version": "2.1", "target_ref": "attack-pattern--d245808a-7086-4310-984a-a84aaaa43f8f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6581', 0, 108, '09-mitre-attack', 'retrieved', '2EB0CA1A9FEA610CE0FA216E7E22E1FD1D3ED7B7C612B3015AF7EEBA3BBAC471', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
