VALUES ('doc-09-mitre-attack-p0-6587', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T19:42:19.956Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Many vendors provide digitally signed operating system images to validate the integrity of the software used on their platform. Make use of this feature where possible in order to prevent and/or detect attempts by adversaries to compromise the system image. (Citation: Cisco IOS Software Integrity Assurance - Deploy Signed IOS)", "external_references": [{"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - Deploy Signed IOS. Retrieved October 21, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - Deploy Signed IOS", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#34"}], "id": "relationship--ae16d5d7-9a6f-4865-863a-2ce336b45795", "modified": "2026-04-29T14:23:06.162Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--590777b3-b475-4c7c-aaf8-f4a73b140312", "spec_version": "2.1", "target_ref": "attack-pattern--ae7f3575-0a5e-427e-991b-fe03ad44c754", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6587', 0, 108, '09-mitre-attack', 'retrieved', 'AFF553EC6973514BA532E5AB4628BEB64258339BEF7EB7AE8A45E8528BA54A4F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
