VALUES ('doc-09-mitre-attack-p0-6606', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-10-07T22:34:17.327Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Implement Data Loss Prevention (DLP) solutions to monitor, detect, and control the flow of sensitive information. DLP tools can be configured to block unauthorized attempts to exfiltrate data, such as preventing emails from being forwarded to external recipients or monitoring for suspicious data transfers. By creating email flow rules and applying policies to detect anomalies, DLP solutions help mitigate the risk of data exfiltration over alternative protocols.", "id": "relationship--fdabe7d2-71e9-4f3e-9a29-9d45ca273cdd", "modified": "2026-04-29T14:23:06.270Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--65401701-019d-44ff-b223-08d520bb0e7b", "spec_version": "2.1", "target_ref": "attack-pattern--7c46b364-8496-4234-8a56-f7e6727e21e1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6606', 0, 96, '09-mitre-attack', 'retrieved', '5D8705CF142D10DDE2A7E4FF0AFC21D96DF9A13729DDE2E4C722F922DEF00510', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
