INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6607', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-20T13:13:48.991Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "On Windows 8.1 and Server 2012 R2, enable LSA Protection by setting the Registry key HKEY_LOCAL_MACHINE\\\\SYSTEM\\\\CurrentControlSet\\\\Control\\\\Lsa\\\\RunAsPPL to dword:00000001 . (Citation: Microsoft LSA Protection Mar 2014) LSA Protection ensures that LSA plug-ins and drivers are only loaded if they are digitally signed with a Microsoft signature and adhere to the Microsoft Security Development Lifecycle (SDL) process guidance. ", "external_references": [{"description": "Microsoft. (2014, March 12). Configuring Additional LSA Protection. Retrieved November 27, 2017.", "source_name": "Microsoft LSA Protection Mar 2014", "url": "https://technet.microsoft.com/library/dn408187.aspx"}], "id": "relationship--26bc4aac-e7db-426f-af9f-b85fa60df277", "modified": "2026-04-29T14:23:05.958Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--72dade3e-1cba-4182-b3b3-a77ca52f02a1", "spec_version": "2.1", "target_ref": "attack-pattern--f0589bc3-a6ae-425a-a3d5-5659bfee07f4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6607', 0, 108, '09-mitre-attack', 'retrieved', '4C2B08C23DCEE98720880BFD480535DAA25D6F305F34743AEDA483F227645AB7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
