VALUES ('doc-09-mitre-attack-p0-6615', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-23T22:35:10.751Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Environmental Keying](https://attack.mitre.org/techniques/T1480/001) likely should not be mitigated with preventative controls because it may protect unintended targets from being compromised via confusion of keys by the adversary. Mitigation of this technique is also unlikely to be feasible within most contexts because there are no standard attributes from which an adversary may derive keys. If targeted, efforts should be focused on preventing adversary tools from running earlier in the chain of activity and on identifying subsequent malicious behavior if compromised.", "id": "relationship--9a513f75-f09b-4840-8654-521fa4ff59fa", "modified": "2026-04-29T14:23:06.135Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--787fb64d-c87b-4ee5-a341-0ef17ec4c15c", "spec_version": "2.1", "target_ref": "attack-pattern--f244b8dd-af6c-4391-a497-fc03627ce995", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6615', 0, 107, '09-mitre-attack', 'retrieved', '3DEFB65CFC0BE2D49166C08F5FDD5C03F09B2F3AE7B6C46169AFD0F01C485D03', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
