VALUES ('doc-09-mitre-attack-p0-6616', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-20T03:11:14.529Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "This technique cannot be easily mitigated with preventive controls since it is based on behaviors performed outside of the scope of enterprise defenses and controls. Efforts should focus on minimizing the amount and sensitivity of data available to external parties.", "id": "relationship--004fbe29-2537-418e-9951-a2750a5fa901", "modified": "2026-04-29T14:23:05.903Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--78bb71be-92b4-46de-acd6-5f998fedf1cc", "spec_version": "2.1", "target_ref": "attack-pattern--67073dde-d720-45ae-83da-b12d5e73ca3b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6616', 0, 69, '09-mitre-attack', 'retrieved', '3E2D86D4F2AE87BBEC973ACAE41D91F4A28584F0A93F730A31093EA8375C06AE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
