VALUES ('doc-09-mitre-attack-p0-6707', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-26T14:23:36.958Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use secure methods to boot a system and verify the integrity of the operating system and loading mechanisms.", "id": "relationship--08911cc4-20be-4499-8b19-f4c6151a7172", "modified": "2026-04-29T14:23:05.915Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--7da0387c-ba92-4553-b291-b636ee42b2eb", "spec_version": "2.1", "target_ref": "attack-pattern--3f18edba-28f4-4bb9-82c3-8aa60dcac5f7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6707', 0, 47, '09-mitre-attack', 'retrieved', 'E51B433C8A00A6918672554C7A3E40E16DB95AF478EC002446EC0AA0B3C41BF2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
