VALUES ('doc-09-mitre-attack-p0-6709', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-12-19T21:05:38.409Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use Trusted Platform Module technology and a secure or trusted boot process to prevent system integrity from being compromised.(Citation: TCG Trusted Platform Module)(Citation: TechNet Secure Boot Process)", "external_references": [{"description": "Microsoft. (n.d.). Secure the Windows 10 boot process. Retrieved April 23, 2020.", "source_name": "TechNet Secure Boot Process", "url": "https://docs.microsoft.com/en-us/windows/security/information-protection/secure-the-windows-10-boot-process"}, {"description": "Trusted Computing Group. (2008, April 29). Trusted Platform Module (TPM) Summary. Retrieved June 8, 2016.", "source_name": "TCG Trusted Platform Module", "url": "http://www.trustedcomputinggroup.org/wp-content/uploads/Trusted-Platform-Module-Summary_04292008.pdf"}], "id": "relationship--25a6e5a0-28a7-40a4-baa8-7a9c688f3eb4", "modified": "2026-04-29T14:23:05.956Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--7da0387c-ba92-4553-b291-b636ee42b2eb", "spec_version": "2.1", "target_ref": "attack-pattern--1b7b1806-7746-41a1-a35d-e48dae25ddba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6709', 0, 100, '09-mitre-attack', 'retrieved', '5967D668CB99EC69D46AC0FC9E6E33A2CC2B75E1AB157DC00916A18AF8BED6E7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
