VALUES ('doc-09-mitre-attack-p0-6710', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T19:49:24.436Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Some vendors of embedded network devices provide cryptographic signing to ensure the integrity of operating system images at boot time. Implement where available, following vendor guidelines. (Citation: Cisco IOS Software Integrity Assurance - Secure Boot)", "external_references": [{"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - Secure Boot. Retrieved October 19, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - Secure Boot", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#35"}], "id": "relationship--42703ec8-4dd6-42a3-b2bb-f2a135f89863", "modified": "2026-04-29T14:23:06.016Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--7da0387c-ba92-4553-b291-b636ee42b2eb", "spec_version": "2.1", "target_ref": "attack-pattern--d245808a-7086-4310-984a-a84aaaa43f8f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6710', 0, 91, '09-mitre-attack', 'retrieved', 'F55A7C0ECDE8BBA3D4EB4CC52D8122B632225BB07DCCDBBC1A86571D3F235C12', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
