VALUES ('doc-09-mitre-attack-p0-6711', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-20T19:09:23.924Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enable secure boot features to validate the digital signature of the boot environment and system image using a special purpose hardware device. If the validation check fails, the device will fail to boot preventing loading of unauthorized software. (Citation: Cisco IOS Software Integrity Assurance - Secure Boot) ", "external_references": [{"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - Secure Boot. Retrieved October 19, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - Secure Boot", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#35"}], "id": "relationship--6b6b9464-4d0c-4e7e-9631-e2a3cdac6260", "modified": "2026-04-29T14:23:06.071Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--7da0387c-ba92-4553-b291-b636ee42b2eb", "spec_version": "2.1", "target_ref": "attack-pattern--a6557c75-798f-42e4-be70-ab4502e0a3bc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6711', 0, 104, '09-mitre-attack', 'retrieved', '20BEE529CA486C0C9782B0134FA1518B1BAA53022ED18083A693114CF4BF6734', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
