VALUES ('doc-09-mitre-attack-p0-6712', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-04-04T17:09:45.903Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enabling secure boot allows validation of software and drivers during initial system boot.", "id": "relationship--9ef8bd47-8955-4e56-b801-8626fe696fe8", "modified": "2026-04-29T14:23:06.142Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--7da0387c-ba92-4553-b291-b636ee42b2eb", "spec_version": "2.1", "target_ref": "attack-pattern--d456de47-a16f-4e46-8980-e67478a12dcb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6712', 0, 42, '09-mitre-attack', 'retrieved', '0B48297CFFE719D3ED24C29068CBC9BCA5DBE7532A087B7107C88832E2DB5039', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
