VALUES ('doc-09-mitre-attack-p0-6720', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-11T14:28:40.154Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use Trusted Platform Module technology and a secure or trusted boot process to prevent system integrity from being compromised. Check the integrity of the existing BIOS or EFI to determine if it is vulnerable to modification.(Citation: TCG Trusted Platform Module)(Citation: TechNet Secure Boot Process)", "external_references": [{"description": "Microsoft. (n.d.). Secure the Windows 10 boot process. Retrieved April 23, 2020.", "source_name": "TechNet Secure Boot Process", "url": "https://docs.microsoft.com/en-us/windows/security/information-protection/secure-the-windows-10-boot-process"}, {"description": "Trusted Computing Group. (2008, April 29). Trusted Platform Module (TPM) Summary. Retrieved June 8, 2016.", "source_name": "TCG Trusted Platform Module", "url": "http://www.trustedcomputinggroup.org/wp-content/uploads/Trusted-Platform-Module-Summary_04292008.pdf"}], "id": "relationship--6800b404-bdfe-46bf-8ce3-54819f990e1f", "modified": "2026-06-08T19:34:13.888Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--7da0387c-ba92-4553-b291-b636ee42b2eb", "spec_version": "2.1", "target_ref": "attack-pattern--39131305-9282-45e4-ac3b-591d2d4fc3ef", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6720', 0, 117, '09-mitre-attack', 'retrieved', 'ED3B49A1C1CB24FC30AE2D9C97F96AAB8C1D919B4BB97602E95A9C9222B988DB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
