INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6721', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-04T13:21:31.526Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Implement secure out-of-band alerts to notify security teams of unusual local email activities, such as mass forwarding or large attachments being sent, indicating potential data exfiltration attempts.(Citation: TrustedSec OOB Communications)", "external_references": [{"description": "Tyler Hudak. (2022, December 29). To OOB, or Not to OOB?: Why Out-of-Band Communications are Essential for Incident Response. Retrieved August 30, 2024.", "source_name": "TrustedSec OOB Communications", "url": "https://trustedsec.com/blog/to-oob-or-not-to-oob-why-out-of-band-communications-are-essential-for-incident-response"}], "id": "relationship--21ad0084-2f19-4559-9de1-dc06d1809ef0", "modified": "2026-04-29T14:23:05.951Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--80a0e940-f683-4fbd-ac00-e9f935f2f808", "spec_version": "2.1", "target_ref": "attack-pattern--1e9eb839-294b-48cc-b0d3-c45555a2a004", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6721', 0, 90, '09-mitre-attack', 'retrieved', '20B13C8FB1F665AAC9BFF308EAF51BC3F21CCF1C6021691EFB2330CBDEFAE006', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
