VALUES ('doc-09-mitre-attack-p0-6724', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-30T13:54:25.094Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Implement secure out-of-band communication channels to use as an alternative to in-network chat applications during a security incident. This ensures that critical communications remain secure even if primary messaging channels are compromised by adversaries.(Citation: TrustedSec OOB Communications)", "external_references": [{"description": "Tyler Hudak. (2022, December 29). To OOB, or Not to OOB?: Why Out-of-Band Communications are Essential for Incident Response. Retrieved August 30, 2024.", "source_name": "TrustedSec OOB Communications", "url": "https://trustedsec.com/blog/to-oob-or-not-to-oob-why-out-of-band-communications-are-essential-for-incident-response"}], "id": "relationship--b1e43f0e-e68e-427c-9b94-09080ef6634a", "modified": "2026-04-29T14:23:06.168Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--80a0e940-f683-4fbd-ac00-e9f935f2f808", "spec_version": "2.1", "target_ref": "attack-pattern--fb75213f-cfb0-40bf-a02f-3bad93d6601e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6724', 0, 97, '09-mitre-attack', 'retrieved', '7D7B051DA526BDB6F58454368F1F51B08F1BE19C048D8A4AB19A3654B020C7FD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
