VALUES ('doc-09-mitre-attack-p0-6725', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-30T14:03:31.446Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Develop and enforce security policies that include the use of out-of-band communication channels for critical communications during a security incident.(Citation: TrustedSec OOB Communications)", "external_references": [{"description": "Tyler Hudak. (2022, December 29). To OOB, or Not to OOB?: Why Out-of-Band Communications are Essential for Incident Response. Retrieved August 30, 2024.", "source_name": "TrustedSec OOB Communications", "url": "https://trustedsec.com/blog/to-oob-or-not-to-oob-why-out-of-band-communications-are-essential-for-incident-response"}], "id": "relationship--b774aa5d-7731-46b4-b285-dc1c67a0d01c", "modified": "2026-04-29T14:23:06.176Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--80a0e940-f683-4fbd-ac00-e9f935f2f808", "spec_version": "2.1", "target_ref": "attack-pattern--20fb2507-d71c-455d-9b6d-6104461cf26b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6725', 0, 83, '09-mitre-attack', 'retrieved', 'C81CFBE3A37DD547BED587DE0E78D7BCBA3CD354A52446154B2CEEE66D75F14F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
