VALUES ('doc-09-mitre-attack-p0-6729', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-31T14:26:00.977Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Deny direct remote access to internal systems through the use of network proxies, gateways, and firewalls.", "id": "relationship--1d362b9d-300d-4081-bd42-ca57c892a331", "modified": "2026-04-29T14:23:05.944Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--86598de0-b347-4928-9eb0-0acbfc21908c", "spec_version": "2.1", "target_ref": "attack-pattern--0470e792-32f8-46b0-a351-652bc35e9336", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6729', 0, 45, '09-mitre-attack', 'retrieved', '7CDA248652A472EA04592ABE96F75A950F8A316E89FCEBA9D7773D6BFC9498B3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
