VALUES ('doc-09-mitre-attack-p0-6730', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-13T16:04:04.168Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure access controls and firewalls to limit access to critical systems and domain controllers. Most cloud environments support separate virtual private cloud (VPC) instances that enable further segmentation of cloud systems.", "id": "relationship--21ea4371-e692-4731-9f8c-c3f4dff3c775", "modified": "2026-04-29T14:23:05.951Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--86598de0-b347-4928-9eb0-0acbfc21908c", "spec_version": "2.1", "target_ref": "attack-pattern--a10641f4-87b4-45a3-a906-92a149cb2c27", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6730', 0, 60, '09-mitre-attack', 'retrieved', '1B50EBE31B44099A95C2A02CE130F2AE1F92DC03EED2F16F365B67AD1EDC9D0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
