VALUES ('doc-09-mitre-attack-p0-6731', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-14T17:17:06.995Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure access controls and firewalls to limit access to domain controllers and systems used to create and manage accounts.", "id": "relationship--26099ea8-5af8-4173-b70d-b32bbcbe0732", "modified": "2026-04-29T14:23:05.957Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--86598de0-b347-4928-9eb0-0acbfc21908c", "spec_version": "2.1", "target_ref": "attack-pattern--e01be9c5-e763-4caf-aeb7-000b416aef67", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6731', 0, 48, '09-mitre-attack', 'retrieved', '6D729BD556EAE7ADBDE5D3B13A693618E96449D338BAB26227B02C93B577AD51', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
