VALUES ('doc-09-mitre-attack-p0-6732', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-12T14:37:27.502Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Do not leave RDP accessible from the internet. Enable firewall rules to block RDP traffic between network security zones within a network.", "id": "relationship--3951503f-c8e9-4331-834e-df4e4afda5fb", "modified": "2026-04-29T14:23:05.998Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--86598de0-b347-4928-9eb0-0acbfc21908c", "spec_version": "2.1", "target_ref": "attack-pattern--eb062747-2193-45de-8fa2-e62549c37ddf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6732', 0, 51, '09-mitre-attack', 'retrieved', 'DE4870CD20217F652AD594AEB742B659783301F8960195EE8AA72B9601227213', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
