VALUES ('doc-09-mitre-attack-p0-6733', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-24T13:44:34.852Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Segment externally facing servers and services from the rest of the network with a DMZ or on separate hosting infrastructure.", "id": "relationship--3b726298-74dc-4f8a-b58d-f623bc645124", "modified": "2026-04-29T14:23:06.003Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--86598de0-b347-4928-9eb0-0acbfc21908c", "spec_version": "2.1", "target_ref": "attack-pattern--3f886f2a-874f-4333-b794-aa6075009b1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6733', 0, 49, '09-mitre-attack', 'retrieved', 'E8CEE8F10304DFC16533710DD75436D9FF6EE5805772570AFA8760D495451217', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
