VALUES ('doc-09-mitre-attack-p0-6774', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-27T18:00:08.521Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure strong password length (ideally 25+ characters) and complexity for service accounts and that these passwords periodically expire.(Citation: AdSecurity Cracking Kerberos Dec 2015) Also consider using Group Managed Service Accounts or another third party product such as password vaulting.(Citation: AdSecurity Cracking Kerberos Dec 2015)", "external_references": [{"description": "Metcalf, S. (2015, December 31). Cracking Kerberos TGS Tickets Using Kerberoast – Exploiting Kerberos to Compromise the Active Directory Domain. Retrieved March 22, 2018.", "source_name": "AdSecurity Cracking Kerberos Dec 2015", "url": "https://adsecurity.org/?p=2293"}], "id": "relationship--365e1449-7ef2-4370-9f42-7d288f883d99", "modified": "2026-04-29T14:23:05.994Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90c218c3-fbf8-4830-98a7-e8cfb7eaa485", "spec_version": "2.1", "target_ref": "attack-pattern--d273434a-448e-4598-8e14-607f4a0d5e27", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6774', 0, 107, '09-mitre-attack', 'retrieved', '75177B4600D8E3FFC0AAC599DAFE06B13B5E9B5038B09F786384BFA229CDF78F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
