INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6777', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T16:21:55.304Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Applications and appliances that utilize default username and password should be changed immediately after the installation, and before deployment to a production environment.(Citation: US-CERT Alert TA13-175A Risks of Default Passwords on the Internet) When possible, applications that use SSH keys should be updated periodically and properly secured.\n\nPolicies should minimize (if not eliminate) reuse of passwords between different user accounts, especially employees using the same credentials for personal accounts that may not be defended by enterprise security resources.", "external_references": [{"description": "US-CERT. (n.d.). Risks of Default Passwords on the Internet. Retrieved April 12, 2019.", "source_name": "US-CERT Alert TA13-175A Risks of Default Passwords on the Internet", "url": "https://www.us-cert.gov/ncas/alerts/TA13-175A"}], "id": "relationship--4f24d075-4d6c-49d2-a213-306e4af2083d", "modified": "2026-04-29T14:23:06.033Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90c218c3-fbf8-4830-98a7-e8cfb7eaa485", "spec_version": "2.1", "target_ref": "attack-pattern--b17a1a56-e99c-403c-8948-561df0cffe81", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6777', 0, 134, '09-mitre-attack', 'retrieved', '3BD47F1BA5D1EDE5FB0B8360FFD48C9E411DA3A214AC6121260CC5EF69227844', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
