VALUES ('doc-09-mitre-attack-p0-6778', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-25T18:30:50.113Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use strong passphrases for private keys to make cracking difficult. Do not store credentials within the Registry. Establish an organizational policy that prohibits password storage in files.", "id": "relationship--529b0951-548c-4316-93d1-baf97d89f10a", "modified": "2026-04-29T14:23:06.038Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90c218c3-fbf8-4830-98a7-e8cfb7eaa485", "spec_version": "2.1", "target_ref": "attack-pattern--435dfb86-2697-4867-85b5-2fef496c0517", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6778', 0, 56, '09-mitre-attack', 'retrieved', 'A9293548112FC9DAB83AD849C6D5D9F839BCD86AE6A515B83FC46D7A65618968', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
