VALUES ('doc-09-mitre-attack-p0-6780', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-24T19:53:23.756Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use strong passwords to increase the difficulty of credential hashes from being cracked if they are obtained.", "id": "relationship--6537d47a-80c0-442b-a1ec-3451d078a2a9", "modified": "2026-04-29T14:23:06.063Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90c218c3-fbf8-4830-98a7-e8cfb7eaa485", "spec_version": "2.1", "target_ref": "attack-pattern--b77cf5f3-6060-475d-bd60-40ccbf28fdc2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6780', 0, 46, '09-mitre-attack', 'retrieved', 'D9CDE5ECA697DB56ACFD930FA306E69E41C0A9596BAA783EC7FCCAE51D090075', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
