VALUES ('doc-09-mitre-attack-p0-6783', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-24T13:43:00.171Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure strong password length (ideally 25+ characters) and complexity for service accounts and that these passwords periodically expire. Also consider using Group Managed Service Accounts or another third party product such as password vaulting. (Citation: AdSecurity Cracking Kerberos Dec 2015)", "external_references": [{"description": "Metcalf, S. (2015, December 31). Cracking Kerberos TGS Tickets Using Kerberoast – Exploiting Kerberos to Compromise the Active Directory Domain. Retrieved March 22, 2018.", "source_name": "AdSecurity Cracking Kerberos Dec 2015", "url": "https://adsecurity.org/?p=2293"}], "id": "relationship--6e751301-3697-4851-b55c-259976891406", "modified": "2026-04-29T14:23:06.075Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90c218c3-fbf8-4830-98a7-e8cfb7eaa485", "spec_version": "2.1", "target_ref": "attack-pattern--3986e7fd-a8e9-4ecb-bfc6-55920855912b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6783', 0, 103, '09-mitre-attack', 'retrieved', 'FC9D6F6BF804506A59D6DC6820D22DD79C3C9AB85895061285EFA9F2856FB42F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
