VALUES ('doc-09-mitre-attack-p0-6790', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-13T20:44:06.873Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Applications and appliances that utilize default username and password should be changed immediately after the installation, and before deployment to a production environment. (Citation: US-CERT Alert TA13-175A Risks of Default Passwords on the Internet)", "external_references": [{"description": "US-CERT. (n.d.). Risks of Default Passwords on the Internet. Retrieved April 12, 2019.", "source_name": "US-CERT Alert TA13-175A Risks of Default Passwords on the Internet", "url": "https://www.us-cert.gov/ncas/alerts/TA13-175A"}], "id": "relationship--884964fd-ae2b-4a3f-a023-98e79b967943", "modified": "2026-04-29T14:23:06.111Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90c218c3-fbf8-4830-98a7-e8cfb7eaa485", "spec_version": "2.1", "target_ref": "attack-pattern--6151cbea-819b-455a-9fa6-99a1cc58797d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6790', 0, 91, '09-mitre-attack', 'retrieved', '07B1FF752331ADC22D86F4F509085188177733B54906A8509C549EEA423C9FBA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
