VALUES ('doc-09-mitre-attack-p0-6791', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-17T13:14:31.437Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The password for the user''s login keychain can be changed from the user''s login password. This increases the complexity for an adversary because they need to know an additional password.", "id": "relationship--8e620d3d-6766-4f26-a6ae-d7fd1276916f", "modified": "2026-04-29T14:23:06.119Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90c218c3-fbf8-4830-98a7-e8cfb7eaa485", "spec_version": "2.1", "target_ref": "attack-pattern--1eaebf46-e361-4437-bc23-d5d65a3b92e3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6791', 0, 59, '09-mitre-attack', 'retrieved', '2CF403DE3FE024CA9683681498AD3BDB69130E238FD9A712B31EA67325BCB4B1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
