VALUES ('doc-09-mitre-attack-p0-6792', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-25T18:49:52.381Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure SSH key pairs have strong passwords and refrain from using key-store technologies such as ssh-agent unless they are properly protected.", "id": "relationship--a58b2f24-9fa1-4dd6-9977-7c201fbfe5ed", "modified": "2026-04-29T14:23:06.150Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90c218c3-fbf8-4830-98a7-e8cfb7eaa485", "spec_version": "2.1", "target_ref": "attack-pattern--4d2a5b3e-340d-4600-9123-309dd63c9bf8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6792', 0, 50, '09-mitre-attack', 'retrieved', '9A0C03AFB3772BB5B55E3E23384DC6564C4C5E7AC1B25D1064EACAB5EADDC8E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
