VALUES ('doc-09-mitre-attack-p0-6795', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-17T13:03:42.660Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The password for the user''s login keychain can be changed from the user''s login password. This increases the complexity for an adversary because they need to know an additional password.\n\nOrganizations may consider weighing the risk of storing credentials in password stores and web browsers. If system, software, or web browser credential disclosure is a significant concern, technical controls, policy, and user training may be used to prevent storage of credentials in improper locations.", "id": "relationship--c19fcf1c-8c2c-4a71-a1fb-43934cc6ba23", "modified": "2026-04-29T14:23:06.190Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90c218c3-fbf8-4830-98a7-e8cfb7eaa485", "spec_version": "2.1", "target_ref": "attack-pattern--3fc9b85a-2862-4363-a64d-d692e3ffbee0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6795', 0, 102, '09-mitre-attack', 'retrieved', '763E94E86BA8DEB0545EEDF0D596106A6A18A426DC751059A46B24F81AE16763', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
