VALUES ('doc-09-mitre-attack-p0-6797', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-24T16:27:16.770Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure only valid password filters are registered. Filter DLLs must be present in Windows installation directory ( C:\\Windows\\System32\\ by default) of a domain controller and/or local computer with a corresponding entry in HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\Notification Packages . (Citation: Microsoft Install Password Filter n.d)", "external_references": [{"description": "Microsoft. (n.d.). Installing and Registering a Password Filter DLL. Retrieved November 21, 2017.", "source_name": "Microsoft Install Password Filter n.d", "url": "https://msdn.microsoft.com/library/windows/desktop/ms721766.aspx"}], "id": "relationship--e2748683-077b-4e91-9225-6b29245fdafc", "modified": "2026-04-29T14:23:06.234Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90c218c3-fbf8-4830-98a7-e8cfb7eaa485", "spec_version": "2.1", "target_ref": "attack-pattern--b6075259-dba3-44e9-87c7-e954f37ec0d5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6797', 0, 93, '09-mitre-attack', 'retrieved', '942F8F052E46DB354189686364BD3F2D312AAC255C8FDF46F597F2104D3FAC57', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
