VALUES ('doc-09-mitre-attack-p0-6798', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-01T15:46:42.487Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Do not reuse local administrator account passwords across systems. Ensure password complexity and uniqueness such that the passwords cannot be cracked or guessed.", "id": "relationship--ed9cb2bb-5c45-45f1-a0d5-4458609a5ab5", "modified": "2026-04-29T14:23:06.248Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90c218c3-fbf8-4830-98a7-e8cfb7eaa485", "spec_version": "2.1", "target_ref": "attack-pattern--54a649ff-439a-41a4-9856-8d144a2551ba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6798', 0, 52, '09-mitre-attack', 'retrieved', '2FB5172F2228BDE55627DAB01CBF916949A671E8A8962EC53BFD96478285638E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
