VALUES ('doc-09-mitre-attack-p0-6813', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-08T22:58:38.802Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Implement security controls on the endpoint, such as a Host Intrusion Prevention System (HIPS), to identify and prevent execution of files with mismatching file signatures.", "id": "relationship--096287e3-0985-4678-95d1-0f6e5a22b7e6", "modified": "2026-04-29T14:23:05.916Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90f39ee1-d5a3-4aaa-9f28-3b42815b0d46", "spec_version": "2.1", "target_ref": "attack-pattern--208884f1-7b83-4473-ac22-4e1cf6c41471", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6813', 0, 54, '09-mitre-attack', 'retrieved', '880A7A5AD55AF0875E8A81156754569FBA77366BD1D73D29FCB808B890C6A1EF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
