VALUES ('doc-09-mitre-attack-p0-6822', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-07T00:45:11.458Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "On Windows 10, enable Attack Surface Reduction (ASR) rules to block processes created by WMI commands from running. Note: many legitimate tools and applications utilize WMI for command execution. (Citation: win10_asr)", "external_references": [{"description": "Microsoft. (2021, July 2). Use attack surface reduction rules to prevent malware infection. Retrieved June 24, 2021.", "source_name": "win10_asr", "url": "https://docs.microsoft.com/microsoft-365/security/defender-endpoint/attack-surface-reduction"}], "id": "relationship--2869490f-0728-4a73-a9c2-3a5de5f9f5e7", "modified": "2026-04-29T14:23:05.960Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90f39ee1-d5a3-4aaa-9f28-3b42815b0d46", "spec_version": "2.1", "target_ref": "attack-pattern--01a5a209-b94c-450b-b7f9-946497d91055", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6822', 0, 83, '09-mitre-attack', 'retrieved', '533996164D1A8E4CC272AB8A09A52B002CD299BE3D3DDE699C6655B472A73942', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
