VALUES ('doc-09-mitre-attack-p0-6824', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-06T21:52:00.353Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "On Windows 10, enable Attack Surface Reduction (ASR) rules to prevent executable files from running unless they meet a prevalence, age, or trusted list criteria and to prevent Office applications from creating potentially malicious executable content by blocking malicious code from being written to disk. Note: cloud-delivered protection must be enabled to use certain rules. (Citation: win10_asr)", "external_references": [{"description": "Microsoft. (2021, July 2). Use attack surface reduction rules to prevent malware infection. Retrieved June 24, 2021.", "source_name": "win10_asr", "url": "https://docs.microsoft.com/microsoft-365/security/defender-endpoint/attack-surface-reduction"}], "id": "relationship--3551c43c-b1b9-432b-8c3a-cf0265ca74ff", "modified": "2026-04-29T14:23:05.991Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90f39ee1-d5a3-4aaa-9f28-3b42815b0d46", "spec_version": "2.1", "target_ref": "attack-pattern--8c32eb4d-805f-4fc5-bf60-c4d476c131b5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6824', 0, 109, '09-mitre-attack', 'retrieved', '9D5CDE570BD841380B6AE95A7D1328AAE54857E6684FDE9E30400819F54952B2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
