VALUES ('doc-09-mitre-attack-p0-6843', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-29T15:29:41.152Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "On Windows 10, enable Attack Surface Reduction (ASR) rules to prevent execution of potentially obfuscated scripts or payloads.", "id": "relationship--9c3ee91e-c64e-47c5-8aeb-300bc8aa6b6e", "modified": "2026-04-29T14:23:06.138Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90f39ee1-d5a3-4aaa-9f28-3b42815b0d46", "spec_version": "2.1", "target_ref": "attack-pattern--887274fc-2d63-4bdc-82f3-fae56d1d5fdc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6843', 0, 47, '09-mitre-attack', 'retrieved', 'E0E888C0C98B12E5608B8F5CAE836E1590DA644ADC0FBFFE298C6273B596A960', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
