VALUES ('doc-09-mitre-attack-p0-6844', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-06T22:40:13.545Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "On Windows 10, enable cloud-delivered protection and Attack Surface Reduction (ASR) rules to block the execution of files that resemble ransomware.(Citation: win10_asr) In AWS environments, create an IAM policy to restrict or block the use of SSE-C on S3 buckets.(Citation: Halcyon AWS Ransomware 2025)", "external_references": [{"description": "Halcyon RISE Team. (2025, January 13). Abusing AWS Native Services: Ransomware Encrypting S3 Buckets with SSE-C. Retrieved March 18, 2025.", "source_name": "Halcyon AWS Ransomware 2025", "url": "https://www.halcyon.ai/blog/abusing-aws-native-services-ransomware-encrypting-s3-buckets-with-sse-c"}, {"description": "Microsoft. (2021, July 2). Use attack surface reduction rules to prevent malware infection. Retrieved June 24, 2021.", "source_name": "win10_asr", "url": "https://docs.microsoft.com/microsoft-365/security/defender-endpoint/attack-surface-reduction"}], "id": "relationship--9c8dee77-e751-40b6-ab99-ccfe6a832e0a", "modified": "2026-04-29T14:23:06.138Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90f39ee1-d5a3-4aaa-9f28-3b42815b0d46", "spec_version": "2.1", "target_ref": "attack-pattern--b80d107d-fa0d-4b60-9684-b0433e8bdba0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6844', 0, 124, '09-mitre-attack', 'retrieved', '4B09A156F3BA0296D97DE2DB34A8972D787561B5A2B7F85660F32B59C6664FCC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
