VALUES ('doc-09-mitre-attack-p0-6845', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-07T02:22:10.622Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "On Windows 10, enable Attack Surface Reduction (ASR) rules to prevent Office applications from creating child processes and from writing potentially malicious executable content to disk. (Citation: win10_asr)", "external_references": [{"description": "Microsoft. (2021, July 2). Use attack surface reduction rules to prevent malware infection. Retrieved June 24, 2021.", "source_name": "win10_asr", "url": "https://docs.microsoft.com/microsoft-365/security/defender-endpoint/attack-surface-reduction"}], "id": "relationship--a584d785-0c26-43e3-93c3-3e4caf397768", "modified": "2026-04-29T14:23:06.150Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90f39ee1-d5a3-4aaa-9f28-3b42815b0d46", "spec_version": "2.1", "target_ref": "attack-pattern--3d1b9d7e-3921-4d25-845a-7d9f15c0da44", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6845', 0, 80, '09-mitre-attack', 'retrieved', 'E93C97628FCA21DDE6B881E5B86D7A05D7BA0C4B750D41337038742FA10262F8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
