VALUES ('doc-09-mitre-attack-p0-6846', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-06T22:45:36.570Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "On Windows 10, various Attack Surface Reduction (ASR) rules can be enabled to prevent the execution of potentially malicious executable files (such as those that have been downloaded and executed by Office applications/scripting interpreters/email clients or that do not meet specific prevalence, age, or trusted list criteria). Note: cloud-delivered protection must be enabled for certain rules. (Citation: win10_asr)", "external_references": [{"description": "Microsoft. (2021, July 2). Use attack surface reduction rules to prevent malware infection. Retrieved June 24, 2021.", "source_name": "win10_asr", "url": "https://docs.microsoft.com/microsoft-365/security/defender-endpoint/attack-surface-reduction"}], "id": "relationship--a8ec5ebc-8505-471c-ae81-877229b53a65", "modified": "2026-04-29T14:23:06.155Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--90f39ee1-d5a3-4aaa-9f28-3b42815b0d46", "spec_version": "2.1", "target_ref": "attack-pattern--232b7f21-adf9-4b42-b936-b9d6f7df856e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6846', 0, 110, '09-mitre-attack', 'retrieved', '090FE901F590E546AA69983182728430B5C08163AB5680B27B9FB599D6BF3B68', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
