VALUES ('doc-09-mitre-attack-p0-6864', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-05-22T20:01:38.066Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that CI/CD pipelines only have permissions they require to complete their operations. Additionally, limit the number of users who have write access to internal repositories to only those necessary.", "id": "relationship--02c9e4fd-a17d-4661-8597-77526adc776c", "modified": "2026-04-29T14:23:05.907Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--7655ac3b-dfde-49c5-a967-242856174434", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6864', 0, 59, '09-mitre-attack', 'retrieved', '23D89B92935637AD4F3D4A69567D96FA3DCEF47D27A481821A24DC7E2A9108E0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
