VALUES ('doc-09-mitre-attack-p0-6866', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-25T22:32:16.712Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit privileges of user accounts and groups so that only authorized administrators can interact with system-level process changes and service configurations.", "id": "relationship--06ef2810-b641-4142-83af-bbb00a598c11", "modified": "2026-04-29T14:23:05.913Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--106c0cf6-bf73-4601-9aa8-0945c2715ec5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6866', 0, 50, '09-mitre-attack', 'retrieved', '5A71DC0B68364B926001BD9A77E57A1626A892C25EFFD84042ECD736C2ECADC0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
