VALUES ('doc-09-mitre-attack-p0-6868', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-08T17:06:00.709Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit permissions for creating, deleting, and otherwise altering compute components in accordance with least privilege. Organizations should limit the number of users within the organization with an IAM role that has administrative privileges, strive to reduce all permanent privileged role assignments, and conduct periodic entitlement reviews on IAM users, roles and policies.(Citation: Mandiant M-Trends 2020)", "external_references": [{"description": "Mandiant. (2020, February). M-Trends 2020. Retrieved November 17, 2024.", "source_name": "Mandiant M-Trends 2020", "url": "https://www.mandiant.com/sites/default/files/2021-09/mtrends-2020.pdf"}], "id": "relationship--0b74039a-c985-4587-bed7-0876f2ef1e6c", "modified": "2026-04-29T14:23:05.919Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--144e007b-e638-431d-a894-45d90c54ab90", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6868', 0, 101, '09-mitre-attack', 'retrieved', '75BF79BCCAFEEA2445357410E60F993182BF60CE2C54ADAD343F7C5B87DFB5BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
