VALUES ('doc-09-mitre-attack-p0-6880', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-05T02:15:29.999Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure user permissions groups and roles for access to cloud storage.(Citation: Microsoft Azure Storage Security, 2019) Implement strict Identity and Access Management (IAM) controls to prevent access to storage solutions except for the applications, users, and services that require access.(Citation: Amazon S3 Security, 2019) Ensure that temporary access tokens are issued rather than permanent credentials, especially when access is being granted to entities outside of the internal security boundary.(Citation: Amazon AWS Temporary Security Credentials)", "external_references": [{"description": "Amlekar, M., Brooks, C., Claman, L., et. al.. (2019, March 20). Azure Storage security guide. Retrieved October 4, 2019.", "source_name": "Microsoft Azure Storage Security, 2019", "url": "https://docs.microsoft.com/en-us/azure/storage/common/storage-security-guide"}, {"description": "Amazon. (2019, May 17). How can I secure the files in my Amazon S3 bucket?. Retrieved October 4, 2019.", "source_name": "Amazon S3 Security, 2019", "url": "https://aws.amazon.com/premiumsupport/knowledge-center/secure-s3-resources/"}, {"description": "Amazon. (n.d.). Temporary Security Credentials. Retrieved October 18, 2019.", "source_name": "Amazon AWS Temporary Security Credentials", "url": "https://docs.aws.amazon.com/IAM/latest/UserGuide/id_credentials_temp.html"}], "id": "relationship--22dfe85e-3eeb-4b0a-ac61-b80f70a1f092", "modified": "2026-04-29T14:23:05.952Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--3298ce88-1628-43b1-87d9-0b5336b193d7", "type": "relationship", "