VALUES ('doc-09-mitre-attack-p0-6885', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-10-07T22:01:29.807Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce strict user account management policies on third-party service accounts to control access and limit privileges. Configure accounts with the minimum permissions necessary to perform their roles and regularly review access levels. This minimizes the risk of adversaries exploiting service accounts to execute spearphishing attacks or gain unauthorized access to sensitive resources.", "id": "relationship--311f8c01-21ac-48db-a036-581e9e49f07c", "modified": "2026-04-29T14:23:05.979Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--f6ad61ee-65f3-4bd0-a3f5-2f0accb36317", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6885', 0, 81, '09-mitre-attack', 'retrieved', '4507ADE5D24C64F4239F4305D4FBD65AC719B36A8F1ECE58485FA2CB6358A5A7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
