VALUES ('doc-09-mitre-attack-p0-6886', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T14:07:56.461Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "By default, only administrators are allowed to connect remotely using WMI; restrict other users that are allowed to connect, or disallow all users from connecting remotely to WMI.", "id": "relationship--38a350e5-634c-4dcb-8f6c-0615cdb37864", "modified": "2026-04-29T14:23:05.997Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--910906dd-8c0a-475a-9cc1-5e029e2fad58", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6886', 0, 57, '09-mitre-attack', 'retrieved', '89EE130E64D3351D69E3D7BD4582A7920C29E3AB680A4752E8596C797218BDA7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
