INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6888', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-16T18:32:29.507Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit permissions for deleting new instances in accordance with least privilege. Organizations should limit the number of users within the organization with an IAM role that has administrative privileges, strive to reduce all permanent privileged role assignments, and conduct periodic entitlement reviews on IAM users, roles and policies.(Citation: Mandiant M-Trends 2020)", "external_references": [{"description": "Mandiant. (2020, February). M-Trends 2020. Retrieved November 17, 2024.", "source_name": "Mandiant M-Trends 2020", "url": "https://www.mandiant.com/sites/default/files/2021-09/mtrends-2020.pdf"}], "id": "relationship--393a7e7b-0fe7-4b93-920f-fc1b62652c5a", "modified": "2026-04-29T14:23:05.998Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--70857657-bd0b-4695-ad3e-b13f92cac1b4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6888', 0, 97, '09-mitre-attack', 'retrieved', '1D8E1C471C85B68CFC993D27ED238C93CF48D51F5D3DE8C9728249B4B999BB1B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
