VALUES ('doc-09-mitre-attack-p0-6889', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-16T17:24:49.784Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An adversary must already have administrator level access on the local system to make full use of this technique; be sure to restrict users and accounts to the least privileges they require. ", "id": "relationship--3c5f6c2a-7940-4cdc-8b25-811e33d9b96a", "modified": "2026-04-29T14:23:06.006Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--dcaa092b-7de9-4a21-977f-7fcb77e89c48", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6889', 0, 62, '09-mitre-attack', 'retrieved', 'E20835D9564F9B3760950DE172A9EA275EC1B0BF72A8D5E5AC097CFD3239A212', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
