VALUES ('doc-09-mitre-attack-p0-6890', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-22T18:35:41.384Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure proper user permissions are in place to prevent adversaries from disabling or modifying firewall settings.", "id": "relationship--455d3c85-713f-44e4-816b-3825be78df8b", "modified": "2026-04-29T14:23:06.020Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--a29aa77c-a88d-4f19-bab9-7751941b2e2d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6890', 0, 45, '09-mitre-attack', 'retrieved', '10FAE8DFFDABCB890AEBD59981DD78A8BDE7CB6459F1D0CC65F0C6FC0E631B3D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
