VALUES ('doc-09-mitre-attack-p0-6891', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-17T19:23:15.412Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit privileges of user accounts and remediate Privilege Escalation vectors so only authorized administrators can create new Launch Daemons.", "id": "relationship--48c4d56e-e282-4810-b974-6a325b7d130d", "modified": "2026-04-29T14:23:06.024Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--573ad264-1371-4ae0-8482-d2673b719dba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6891', 0, 48, '09-mitre-attack', 'retrieved', 'DBB2B260C96E76B4976EBECC85776095EB8DBCA59382DFD460BCE326BB4E6F2E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
