INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6895', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-01T13:08:55.890Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce authentication and role-based access control on the container service to restrict users to the least privileges required.(Citation: Kubernetes Hardening Guide) When using Kubernetes, avoid giving users wildcard permissions or adding users to the `system:masters` group, and use `RoleBindings` rather than `ClusterRoleBindings` to limit user privileges to specific namespaces.(Citation: Kubernetes RBAC)", "external_references": [{"description": "Kubernetes. (n.d.). Role Based Access Control Good Practices. Retrieved March 8, 2023.", "source_name": "Kubernetes RBAC", "url": "https://kubernetes.io/docs/concepts/security/rbac-good-practices/"}, {"description": "National Security Agency, Cybersecurity and Infrastructure Security Agency. (2022, March). Kubernetes Hardening Guide. Retrieved April 1, 2022.", "source_name": "Kubernetes Hardening Guide", "url": "https://media.defense.gov/2022/Aug/29/2003066362/-1/-1/0/CTR_KUBERNETES_HARDENING_GUIDANCE_1.2_20220829.PDF"}], "id": "relationship--4d98988c-bac6-48da-9bc8-6e4375317fd4", "modified": "2026-04-29T14:23:06.031Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--7b50a1d3-4ca7-45d1-989d-a6503f04bfe1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6895', 0, 123, '09-mitre-attack', 'retrieved', '7AC4C2D09A4ED88CD4EFF32632B6A2930D70E0B166D4DAED10DDFB7601903CCA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
