VALUES ('doc-09-mitre-attack-p0-6897', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-07-10T16:58:39.360Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit the ability to access and export sensitive logs to privileged accounts where possible.", "id": "relationship--510fefe4-1f76-4c33-a447-2f85e3dc87e2", "modified": "2026-04-29T14:23:06.036Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--866d0d6d-02c6-42bd-aa2f-02907fdc0969", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6897', 0, 43, '09-mitre-attack', 'retrieved', '23F686391EA37C4C529DFFF0264D27F139825E4E9049D45C54F673C00E37040E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
