VALUES ('doc-09-mitre-attack-p0-6899', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-17T12:38:03.677Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Regularly audit user accounts for activity and deactivate or remove any that are no longer needed.", "id": "relationship--555abf76-531f-4d35-9783-ed7c2a3f213b", "modified": "2026-04-29T14:23:06.042Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--b17a1a56-e99c-403c-8948-561df0cffe81", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6899', 0, 45, '09-mitre-attack', 'retrieved', 'CAF630602B50F0161044E69AE212E87BBB65F27D9FDC167F8EAF91C7B8F259C2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
