VALUES ('doc-09-mitre-attack-p0-6900', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-05-27T13:54:57.722Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that low-privileged user accounts do not have permission to add access keys to accounts. In AWS environments, prohibit users from calling the `sts:GetFederationToken` API unless explicitly required.(Citation: Crowdstrike AWS User Federation Persistence)", "external_references": [{"description": " Vaishnav Murthy and Joel Eng. (2023, January 30). How Adversaries Can Persist with AWS User Federation. Retrieved March 10, 2023.", "source_name": "Crowdstrike AWS User Federation Persistence", "url": "https://www.crowdstrike.com/blog/how-adversaries-persist-with-aws-user-federation/"}], "id": "relationship--561ccbcd-578f-4af2-81aa-8594796b6909", "modified": "2026-04-29T14:23:06.043Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--8a2f40cf-8325-47f9-96e4-b1ca4c7389bd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6900', 0, 93, '09-mitre-attack', 'retrieved', '8325B3D5540EFE8C72B355B40D9F1130F5F25F8E281184CF06B96F9487FBE6D1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
