VALUES ('doc-09-mitre-attack-p0-6901', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-29T17:06:22.361Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit privileges of user accounts and remediate privilege escalation vectors so only authorized administrators can create container orchestration jobs.", "id": "relationship--56efe93d-938a-4cad-ab2a-ff43a1f6e266", "modified": "2026-04-29T14:23:06.044Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--1126cab1-c700-412f-a510-61f4937bb096", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6901', 0, 48, '09-mitre-attack', 'retrieved', '2DF56C0F0168A1BAE915B28B37C5413280C453AA64A03FC38472F5DECD343075', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
