VALUES ('doc-09-mitre-attack-p0-6902', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-28T21:51:00.014Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider implementing WMI and security filtering to further tailor which users and computers a GPO will apply to.(Citation: Wald0 Guide to GPOs)(Citation: Microsoft WMI Filters)(Citation: Microsoft GPO Security Filtering)", "external_references": [{"description": "Robbins, A. (2018, April 2). A Red Teamer’s Guide to GPOs and OUs. Retrieved March 5, 2019.", "source_name": "Wald0 Guide to GPOs", "url": "https://wald0.com/?p=179"}, {"description": "Microsoft. (2008, September 11). Fun with WMI Filters in Group Policy. Retrieved March 13, 2019.", "source_name": "Microsoft WMI Filters", "url": "https://blogs.technet.microsoft.com/askds/2008/09/11/fun-with-wmi-filters-in-group-policy/"}, {"description": "Microsoft. (2018, May 30). Filtering the Scope of a GPO. Retrieved March 13, 2019.", "source_name": "Microsoft GPO Security Filtering", "url": "https://docs.microsoft.com/en-us/previous-versions/windows/desktop/Policy/filtering-the-scope-of-a-gpo"}], "id": "relationship--57563748-1634-4625-baa4-73a4b1d7dbfb", "modified": "2026-04-29T14:23:06.044Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--5d2be8b9-d24c-4e98-83bf-2f5f79477163", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6902', 0, 128, '09-mitre-attack', 'retrieved', '2967D032DB286336D50452BF73DBB37E7FB54654A4D09687628EC3EBA684FAC5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STR