VALUES ('doc-09-mitre-attack-p0-6903', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-18T20:03:19.978Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use MDM to disable user''s ability to install or approve kernel extensions, and ensure all approved kernel extensions are in alignment with policies specified in com.apple.syspolicy.kernel-extension-policy .(Citation: Apple TN2459 Kernel Extensions)(Citation: MDMProfileConfigMacOS)\n", "external_references": [{"description": "Apple. (2018, April 19). Technical Note TN2459: User-Approved Kernel Extension Loading. Retrieved June 30, 2020.", "source_name": "Apple TN2459 Kernel Extensions", "url": "https://developer.apple.com/library/archive/technotes/tn2459/_index.html"}, {"description": "Apple. (2019, May 3). Configuration Profile Reference, Developer. Retrieved April 15, 2022.", "source_name": "MDMProfileConfigMacOS", "url": "https://developer.apple.com/business/documentation/Configuration-Profile-Reference.pdf"}], "id": "relationship--58e37620-7000-4ec2-95e0-e1c651fa215d", "modified": "2026-04-29T14:23:06.046Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--a1b52199-c8c5-438a-9ded-656f1d0888c6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6903', 0, 102, '09-mitre-attack', 'retrieved', '3C942E20428C7BF5D2ACBCC8561516AEA3E5BA89749571B7159646DDE716CE6F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
