VALUES ('doc-09-mitre-attack-p0-6908', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-25T14:18:31.497Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit permissions to add, delete, or modify resource groups to only those required. ", "id": "relationship--6d6884e7-7594-43c2-847a-7e8cc7ef4ada", "modified": "2026-04-29T14:23:06.074Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--0ce73446-8722-4086-9d43-514f1d0f669e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6908', 0, 43, '09-mitre-attack', 'retrieved', '1A4BFF233B6B3C05EC9640DE2F93A893926EA6EFF423995FFF35FDFC0EEDD4FE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
