VALUES ('doc-09-mitre-attack-p0-6909', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-24T15:04:44.199Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce the principle of least-privilege. Consider implementing access control mechanisms that include both authentication and authorization.", "id": "relationship--714ba6ae-8c53-4ce1-81f4-4ca81bbdb9b7", "modified": "2026-04-29T14:23:06.080Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--0c4b4fda-9062-47da-98b9-ceae2dcf052a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6909', 0, 45, '09-mitre-attack', 'retrieved', 'FB70C6C46C05663B2F488242FAD75D812AC4B2C109D2F3D7632053E1D4C767D3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
