VALUES ('doc-09-mitre-attack-p0-6910', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-17T16:49:36.576Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit user access to system utilities such as `systemctl` to only users who have a legitimate need.", "id": "relationship--751d1faf-0685-4a1b-8a72-de34bfd6da7e", "modified": "2026-04-29T14:23:06.085Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--dfefe2ed-4389-4318-8762-f0272b350a1b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6910', 0, 46, '09-mitre-attack', 'retrieved', '45CB13747A56BECD2CFAAE6DF1B62CBE8E69B51C65E09F198A37216A819E7042', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
