VALUES ('doc-09-mitre-attack-p0-6912', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-18T17:50:43.801Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit the accounts that may use remote services. Limit the permissions for accounts that are at higher risk of compromise; for example, configure SSH so users can only run specific programs.", "id": "relationship--795ca238-c8cf-4735-98cc-593f1cc59b16", "modified": "2026-04-29T14:23:06.091Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--54a649ff-439a-41a4-9856-8d144a2551ba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6912', 0, 60, '09-mitre-attack', 'retrieved', '017A553C58B25560A84331E436B56B93C5396B60794C9EF45BD6E38CAA2E3B23', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
