VALUES ('doc-09-mitre-attack-p0-6913', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-30T03:19:10.208Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An adversary must already have root level access on the local system to make full use of this technique; be sure to restrict users and accounts to the least privileges they require.", "id": "relationship--7c080252-2bd3-4fb3-98aa-e822a3703455", "modified": "2026-04-29T14:23:06.095Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--23d69d00-80c4-42ff-9dac-dbd0459dad75", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6913', 0, 61, '09-mitre-attack', 'retrieved', '1A2B6920F1391FBF2C8B410072B352FB8646128BC3C3CF7C7B6D52F8666F2FFA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
