VALUES ('doc-09-mitre-attack-p0-6914', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T16:36:51.559Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Do not allow a domain user to be in the local administrator group on multiple systems.", "id": "relationship--7e5e2fd3-cab4-4853-81ad-9bf50e1390bd", "modified": "2026-04-29T14:23:06.098Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--e624264c-033a-424d-9fd7-fc9c3bbdb03e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6914', 0, 45, '09-mitre-attack', 'retrieved', 'D905E58371F7B38FD15E4CF42559BC83CE3F6EC8A2C7EA2282E5D9964262CC67', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
