VALUES ('doc-09-mitre-attack-p0-6915', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-10-08T14:45:09.611Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Implement strict user account management policies to prevent unnecessary accounts from accessing sensitive systems. Regularly audit user accounts to identify and disable inactive accounts that may be targeted by attackers to extract credentials or gain unauthorized access.", "id": "relationship--7ed11b3a-c4c1-4c31-8614-d34a37d8a779", "modified": "2026-04-29T14:23:06.099Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--315f51f0-6b03-4c1e-bfb2-84740afb8e21", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6915', 0, 66, '09-mitre-attack', 'retrieved', 'CA865219F2B4FE628248F3AD01D11FD510EE13C9A99CA5E96A39838DDEE0CB34', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
