VALUES ('doc-09-mitre-attack-p0-6916', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-17T21:33:42.484Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider implementing WMI and security filtering to further tailor which users and computers a GPO will apply to.(Citation: Wald0 Guide to GPOs)(Citation: Microsoft WMI Filters)(Citation: Microsoft GPO Security Filtering)", "external_references": [{"description": "Robbins, A. (2018, April 2). A Red Teamer’s Guide to GPOs and OUs. Retrieved March 5, 2019.", "source_name": "Wald0 Guide to GPOs", "url": "https://wald0.com/?p=179"}, {"description": "Microsoft. (2008, September 11). Fun with WMI Filters in Group Policy. Retrieved March 13, 2019.", "source_name": "Microsoft WMI Filters", "url": "https://blogs.technet.microsoft.com/askds/2008/09/11/fun-with-wmi-filters-in-group-policy/"}, {"description": "Microsoft. (2018, May 30). Filtering the Scope of a GPO. Retrieved March 13, 2019.", "source_name": "Microsoft GPO Security Filtering", "url": "https://docs.microsoft.com/en-us/previous-versions/windows/desktop/Policy/filtering-the-scope-of-a-gpo"}], "id": "relationship--7eeaeee6-9ac5-440f-9c31-2e4a915b637e", "modified": "2026-04-29T14:23:06.099Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--ebb42bbe-62d7-47d7-a55f-3b08b61d792d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6916', 0, 128, '09-mitre-attack', 'retrieved', '294E3BA85A01551630FB68211F10C62A1D6D3D6CC99720E3FF6FC7D9210C5B79', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
