VALUES ('doc-09-mitre-attack-p0-6917', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-10-02T00:45:28.153Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit the privileges of cloud accounts to assume, create, or impersonate additional roles, policies, and permissions to only those required. Where just-in-time access is enabled, consider requiring manual approval for temporary elevation of privileges.", "id": "relationship--8052b9cf-2e89-49c4-a294-4ee42c6c6e03", "modified": "2026-04-29T14:23:06.101Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--67720091-eee3-4d2d-ae16-8264567f6f5b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6917', 0, 63, '09-mitre-attack', 'retrieved', '7E35876304D38B1555056B60F695F509A34612B4D54DD2E0AA3A3DCC689BDF49', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
