VALUES ('doc-09-mitre-attack-p0-6918', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-10-07T22:14:15.172Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce user account management practices for local accounts to limit access and remove inactive or unused accounts. By doing so, you reduce the attack surface available to adversaries and prevent unauthorized access to local systems.", "id": "relationship--8543032a-2f76-4837-90d3-ffd54f6e8708", "modified": "2026-04-29T14:23:06.107Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--fdc47f44-dd32-4b99-af5f-209f556f63c2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6918', 0, 64, '09-mitre-attack', 'retrieved', '9748FC0B52FBE5DA56AE9C88548BBF82658C0ACA95561FC6B28B2F567EEBAE7E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
