VALUES ('doc-09-mitre-attack-p0-6920', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-24T16:55:46.379Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure least privilege principles are applied to Identity and Access Management (IAM) security policies.(Citation: Expel IO Evil in AWS)", "external_references": [{"description": "A. Randazzo, B. Manahan and S. Lipton. (2020, April 28). Finding Evil in AWS. Retrieved June 25, 2020.", "source_name": "Expel IO Evil in AWS", "url": "https://expel.io/blog/finding-evil-in-aws/"}], "id": "relationship--8a4dd18f-d427-4f3f-b92d-e75e3af39a2b", "modified": "2026-04-29T14:23:06.114Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--ee474564-64be-4b83-a958-53f238f49b01", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6920', 0, 76, '09-mitre-attack', 'retrieved', '3B1D24893D40DCC06EE0F301536CB65D1073BAF3E1887BCBE80B5713E9002E09', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
