VALUES ('doc-09-mitre-attack-p0-6921', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-17T18:51:33.926Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce the principle of least-privilege. Consider implementing access control mechanisms that include both authentication and authorization.", "id": "relationship--8b3f2915-ca04-4770-88bb-e6f1314da34d", "modified": "2026-04-29T14:23:06.115Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--d28ef391-8ed4-45dc-bc4a-2f43abf54416", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6921', 0, 45, '09-mitre-attack', 'retrieved', 'BBDA02F27FB4EE066BB37C08B156A416639181926531396098642C00DF9A4E1B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
