VALUES ('doc-09-mitre-attack-p0-6922', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-28T14:03:02.477Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "If not required, restrict the permissions of users to perform Guest Operations on ESXi-hosted VMs.(Citation: Broadcom Virtual Machine Guest Operations Privileges)", "external_references": [{"description": "Broadcom. (n.d.). Virtual Machine Guest Operations Privileges. Retrieved March 28, 2025.", "source_name": "Broadcom Virtual Machine Guest Operations Privileges", "url": "https://techdocs.broadcom.com/us/en/vmware-cis/vsphere/vsphere/7-0/vsphere-security-7-0/defined-privileges/virtual-machine-guest-operations-privileges.html"}], "id": "relationship--8c85cc49-731e-44ae-b8a0-2162444e9ee7", "modified": "2026-04-29T14:23:06.117Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--31e5011f-090e-45be-9bb6-17a1c5e8219b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6922', 0, 72, '09-mitre-attack', 'retrieved', '682155CD916FE99A7735F092BEE5C75BD204A377681A8401E914A44EC6E802D6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
