VALUES ('doc-09-mitre-attack-p0-6923', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-12T14:37:27.473Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit remote user permissions if remote access is necessary.", "id": "relationship--8fae4ace-c3b5-4c4b-8c1a-98a32c692849", "modified": "2026-04-29T14:23:06.121Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--eb062747-2193-45de-8fa2-e62549c37ddf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6923', 0, 38, '09-mitre-attack', 'retrieved', '0CE7F7555F30826302C2AAE7C224DE4CEE50F8DDF028408E00801A0A5F5389FC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
