VALUES ('doc-09-mitre-attack-p0-6924', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-25T13:28:46.302Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "In cloud environments, limit permissions to create new identity providers to only those accounts that require them. In AWS environments, consider using Service Control policies to limit the use of API calls such as `CreateSAMLProvider` or `CreateOpenIDConnectProvider`. ", "id": "relationship--9336c4ae-22c1-4f45-bbba-5cf3f51553aa", "modified": "2026-04-29T14:23:06.126Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--24769ab5-14bd-4f4e-a752-cfb185da53ee", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6924', 0, 67, '09-mitre-attack', 'retrieved', '2622F9D1FFAD978E0D8C4FA220E7FA74A23294425512B096B1D424AFF9B2525F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
