INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6925', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-09T15:33:13.725Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit permissions for creating snapshots or backups in accordance with least privilege. Organizations should limit the number of users within the organization with an IAM role that has administrative privileges, strive to reduce all permanent privileged role assignments, and conduct periodic entitlement reviews on IAM users, roles and policies.(Citation: Mandiant M-Trends 2020)", "external_references": [{"description": "Mandiant. (2020, February). M-Trends 2020. Retrieved November 17, 2024.", "source_name": "Mandiant M-Trends 2020", "url": "https://www.mandiant.com/sites/default/files/2021-09/mtrends-2020.pdf"}], "id": "relationship--9ce9ab1f-b4fa-41e7-8302-11c30f918001", "modified": "2026-04-29T14:23:06.139Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--ed2e45f9-d338-4eb2-8ce5-3a2e03323bc1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6925', 0, 98, '09-mitre-attack', 'retrieved', '0E5B571CC22FD3B961B9A5AFB5CA7A26CC4C748175038D8076BA82EA56A55650', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
