VALUES ('doc-09-mitre-attack-p0-6927', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-18T16:48:56.795Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An adversary must already have administrator level access on the local system to make full use of this technique; be sure to restrict users and accounts to the least privileges they require.", "id": "relationship--9da590e3-3447-4401-8ac7-f6c7482e4aed", "modified": "2026-04-29T14:23:06.140Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--677569f9-a8b0-459e-ab24-7f18091fa7bf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6927', 0, 61, '09-mitre-attack', 'retrieved', '0F5753B1F8C0252428D7E00E73AA87142C45600EDFBE11AA1503B9BB968385BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
