VALUES ('doc-09-mitre-attack-p0-6928', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-11-27T14:58:00.672Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit privileges of user accounts and remediate Privilege Escalation vectors so only authorized administrators can create scheduled tasks on remote systems. ", "id": "relationship--9fad01af-77b7-44b2-a3fc-0a7b338b9ace", "modified": "2026-04-29T14:23:06.143Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--005a06c6-14bf-4118-afa0-ebcd8aebb0c9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6928', 0, 51, '09-mitre-attack', 'retrieved', '2FF190C17F59A2D326240CD1A54022949F37C0FC164AD20E73A1B8D87D114A06', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
