VALUES ('doc-09-mitre-attack-p0-6929', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-12-13T23:21:46.498Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Azure AD Administrators apply limitations upon the ability for users to grant consent to unfamiliar or unverified third-party applications. ", "id": "relationship--a3a8c9e7-ed71-46c9-aa1f-c609406652b0", "modified": "2026-04-29T14:23:06.148Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--2b742742-28c3-4e1b-bab7-8350d6300fa7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6929', 0, 49, '09-mitre-attack', 'retrieved', '8DEF6AE796429608914FF168D6A28254FE03332B259F3CBC134BD2B0E070FB77', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
