VALUES ('doc-09-mitre-attack-p0-6931', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T16:45:15.046Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Properly manage accounts and permissions used by parties in trusted relationships to minimize potential abuse by the party and if the party is compromised by an adversary. In Office 365 environments, partner relationships and roles can be viewed under the “Partner Relationships” page.(Citation: Office 365 Partner Relationships)\n", "external_references": [{"description": "Microsoft. (2022, March 4). Manage partner relationships. Retrieved May 27, 2022.", "source_name": "Office 365 Partner Relationships", "url": "https://docs.microsoft.com/en-us/microsoft-365/commerce/manage-partners?view=o365-worldwide"}], "id": "relationship--a42398e2-3daa-452a-80f8-f06660328f18", "modified": "2026-04-29T14:23:06.148Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--9fa07bef-9c81-421e-a8e5-ad4366c5a925", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6931', 0, 96, '09-mitre-attack', 'retrieved', '45A86289645227B81663BE608AAE6BE6DA58E6CE2F71EE58138531CF5B0540FA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
