VALUES ('doc-09-mitre-attack-p0-6932', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-29T20:35:36.808Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Proactively reset accounts that are known to be part of breached credentials either immediately, or after detecting bruteforce attempts.", "id": "relationship--a69c1383-0afc-40d5-879c-fda561aff983", "modified": "2026-04-29T14:23:06.152Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--b2d03cea-aec1-45ca-9744-9ee583c1e1cc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6932', 0, 48, '09-mitre-attack', 'retrieved', 'F04C8AE26DBDEA4114D4E92573EB3D517BBF13098EE6E115A1E020E013400FA4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
