VALUES ('doc-09-mitre-attack-p0-6933', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-18T15:36:27.535Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Since browser pivoting requires a high integrity process to launch from, restricting user permissions and addressing Privilege Escalation and [Bypass User Account Control](https://attack.mitre.org/techniques/T1548/002) opportunities can limit the exposure to this technique.", "id": "relationship--a9f79f14-d160-4be5-8bbe-ad0b52770b9f", "modified": "2026-04-29T14:23:06.156Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--544b0346-29ad-41e1-a808-501bb4193f47", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6933', 0, 60, '09-mitre-attack', 'retrieved', '5D35FFC66999026A0A95BE129FABF0038F4387E409AD1F16077866B19A789BEA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
