VALUES ('doc-09-mitre-attack-p0-6935', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-12T15:05:04.382Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit which user accounts are allowed to login via SSH.", "id": "relationship--b16c27b4-f94b-43e4-832d-986c03b96ffd", "modified": "2026-04-29T14:23:06.167Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--2db31dcd-54da-405d-acef-b9129b816ed6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6935', 0, 39, '09-mitre-attack', 'retrieved', '56BCCED1783A6079B7871142F735BCB85BA05556BC8D7B9DCCCB5F30435C6FE5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
