VALUES ('doc-09-mitre-attack-p0-6936', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-12T13:52:32.913Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure default account policy to enable logging. Manage policies to ensure only necessary users have permissions to make changes to logging policies.", "id": "relationship--b2d8b329-5812-4b81-b05a-825da8635db2", "modified": "2026-04-29T14:23:06.169Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--34ff60a3-a3f8-42e4-bed0-af9a2cb563d7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6936', 0, 51, '09-mitre-attack', 'retrieved', 'F42DE75FE071EDC153C7FF0B24FAB841C520714158630C5F445A790E392B90EF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
