VALUES ('doc-09-mitre-attack-p0-6937', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-18T18:03:37.711Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An adversary must already have administrator level access on the local system to make full use of this technique; be sure to restrict users and accounts to the least privileges they require. ", "id": "relationship--b32af0e2-1bdc-4b62-a95d-cd1d73919dba", "modified": "2026-04-29T14:23:06.170Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--8cdeb020-e31e-4f88-a582-f53dcfbda819", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6937', 0, 62, '09-mitre-attack', 'retrieved', '5B5AC3A0AC5DE1B58CF22870AA4267215FB8BC5F1E905FA9D0F258698FCD067B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
