VALUES ('doc-09-mitre-attack-p0-6938', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-18T19:18:32.950Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit privileges of user accounts and groups so that only authorized administrators can interact with service changes and service configurations.", "id": "relationship--b5023b20-4243-4686-8b51-429ae7ac73cb", "modified": "2026-04-29T14:23:06.172Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--20fb2507-d71c-455d-9b6d-6104461cf26b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6938', 0, 49, '09-mitre-attack', 'retrieved', '42DCD902C36B8EE0C8030D27109399E98A1CF226A29F41AF1CD882EF26DB9B86', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
