VALUES ('doc-09-mitre-attack-p0-6941', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-25T13:22:29.930Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "In cloud environments, limit permissions to modify cloud bucket lifecycle policies (e.g., `PutLifecycleConfiguration` in AWS) to only those accounts that require it. In AWS environments, consider using Service Control policies to limit the use of the `PutBucketLifecycle` API call. ", "id": "relationship--b6baac4e-00ab-41e6-a035-d2f7d511e476", "modified": "2026-04-29T14:23:06.175Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--d45a3d09-b3cf-48f4-9f0f-f521ee5cb05c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6941', 0, 69, '09-mitre-attack', 'retrieved', '28B02F1DEC31ABE659A435FCD29F9E28FCDF841A1B74AA576C34D81EEA90D4D5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
