VALUES ('doc-09-mitre-attack-p0-6942', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-07-10T16:38:48.984Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit the privileges of cloud accounts to assume, create, or impersonate additional roles, policies, and permissions to only those required. Where just-in-time access is enabled, consider requiring manual approval for temporary elevation of privileges.", "id": "relationship--b811da67-8da1-4f2e-aae0-8666093cf95d", "modified": "2026-04-29T14:23:06.176Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--6fa224c7-5091-4595-bf15-3fc9fe2f2c7c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6942', 0, 63, '09-mitre-attack', 'retrieved', 'C05251B1058D4074699CDE8989DB33251BBB49CFE0EEE823FB15E901239C3AC6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
