VALUES ('doc-09-mitre-attack-p0-6943', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-11T20:39:32.568Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce the principle of least-privilege by limiting dashboard visibility to only the resources required. This may limit the discovery value of the dashboard in the event of a compromised account.", "id": "relationship--ba2b1689-b46c-4451-9618-1c1669a0da0c", "modified": "2026-04-29T14:23:06.179Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--e49920b0-6c54-40c1-9571-73723653205f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6943', 0, 59, '09-mitre-attack', 'retrieved', 'E32343ACD2A5CC27BD157EDE56A0C4D3CFDFEAA3C2464C1FA986CFA95EF9AD6E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
