VALUES ('doc-09-mitre-attack-p0-6944', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-28T16:17:34.654Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Manage the creation, modification, use, and permissions associated to user accounts.", "id": "relationship--bb59d6b5-a6a8-4071-b0a7-297593fc078b", "modified": "2026-04-29T14:23:06.181Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--72b74d71-8169-42aa-92e0-e7b04b9f5a08", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6944', 0, 40, '09-mitre-attack', 'retrieved', 'D63F77446B3AA0BE3A61685B52105B34776F0773A637A12D98294542183EF150', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
