VALUES ('doc-09-mitre-attack-p0-6945', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T16:18:37.236Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce the principle of least-privilege. Do not allow a domain user to be in the local administrator group on multiple systems.", "id": "relationship--bdf60e66-264d-45ec-bb67-b74fa04fe28e", "modified": "2026-04-29T14:23:06.185Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--51a14c76-dd3b-440b-9c20-2bf91d25a814", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6945', 0, 50, '09-mitre-attack', 'retrieved', '4489FB796D600CB97E97673D74104630F0ECF049E9DFC003330D99C1ADCDB8E0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
