VALUES ('doc-09-mitre-attack-p0-6947', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-12-03T14:25:00.662Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": " cron permissions are controlled by /etc/cron.allow and /etc/cron.deny . If there is a cron.allow file, then the user or users that need to use cron will need to be listed in the file. cron.deny is used to explicitly disallow users from using cron. If neither files exist, then only the super user is allowed to run cron.", "id": "relationship--be61d80d-2291-4572-960c-dd741534f855", "modified": "2026-04-29T14:23:06.185Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--2acf44aa-542f-4366-b4eb-55ef5747759c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6947', 0, 87, '09-mitre-attack', 'retrieved', '1F5C8E62834DCEC05337084E51B502E7A7BDEF3E34669F0ED62C806AD06C8179', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
