VALUES ('doc-09-mitre-attack-p0-6948', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T17:00:00.072Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit the privileges of user accounts so that only authorized administrators can perform Winlogon helper changes.", "id": "relationship--bfce35b9-7ae9-4194-83a7-5e5ff1481551", "modified": "2026-04-29T14:23:06.187Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--6836813e-8ec8-4375-b459-abb388cb1a35", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6948', 0, 45, '09-mitre-attack', 'retrieved', '2A0055D0D4ACB91C4DD12983438EA12F08E2D6FD89C6C78687F10D52DB015A64', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
