VALUES ('doc-09-mitre-attack-p0-6951', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-28T03:37:50.005Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure only accounts required to configure and manage backups have the privileges to do so. Monitor these accounts for unauthorized backup activity.", "id": "relationship--c4ef8c6f-2fbd-48aa-aff3-0830a01b5ebd", "modified": "2026-04-29T14:23:06.194Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--0c8ab3eb-df48-4b9c-ace7-beacaac81cc5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6951', 0, 51, '09-mitre-attack', 'retrieved', '4DBC40DEBA3C686BE961AE2D47EEC55131F61C17E14448A9DD2751EEC9E96CB8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
