VALUES ('doc-09-mitre-attack-p0-6952', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-01T13:11:11.048Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce authentication and role-based access control on the container API to restrict users to the least privileges required.(Citation: Kubernetes Hardening Guide) When using Kubernetes, avoid giving users wildcard permissions or adding users to the `system:masters` group, and use `RoleBindings` rather than `ClusterRoleBindings` to limit user privileges to specific namespaces.(Citation: Kubernetes RBAC)", "external_references": [{"description": "Kubernetes. (n.d.). Role Based Access Control Good Practices. Retrieved March 8, 2023.", "source_name": "Kubernetes RBAC", "url": "https://kubernetes.io/docs/concepts/security/rbac-good-practices/"}, {"description": "National Security Agency, Cybersecurity and Infrastructure Security Agency. (2022, March). Kubernetes Hardening Guide. Retrieved April 1, 2022.", "source_name": "Kubernetes Hardening Guide", "url": "https://media.defense.gov/2022/Aug/29/2003066362/-1/-1/0/CTR_KUBERNETES_HARDENING_GUIDANCE_1.2_20220829.PDF"}], "id": "relationship--c55b71bd-89ee-411f-9bd9-d266e5c842a9", "modified": "2026-04-29T14:23:06.195Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--f8ef3a62-3f44-40a4-abca-761ab235c436", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6952', 0, 123, '09-mitre-attack', 'retrieved', '96749BF532EE71BA80606FE55634C763236ADC64B81B1161205F5D847D4B6225', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
