VALUES ('doc-09-mitre-attack-p0-6953', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-15T13:42:07.750Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit access to utilities such as docker to only users who have a legitimate need, especially if using docker in rootful mode. In Kubernetes environments, only grant privileges to deploy pods to users that require it. ", "id": "relationship--c92e754c-48bf-4c8c-9504-47bd7f248baf", "modified": "2026-04-29T14:23:06.200Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--b0e54bf7-835e-4f44-bd8e-62f431b9b76a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6953', 0, 66, '09-mitre-attack', 'retrieved', '22248857DEE6CA419E3C331A41E4DC1B8ADE0E57C3F6D3C33D7566D2B10F8516', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
