VALUES ('doc-09-mitre-attack-p0-6954', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-05-27T13:20:41.269Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Remove permissions to create, modify, or run serverless resources from users that do not explicitly require them.", "id": "relationship--cb2630a2-95a0-4ae8-a715-76899023d1b7", "modified": "2026-04-29T14:23:06.203Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--e848506b-8484-4410-8017-3d235a52f5b3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6954', 0, 46, '09-mitre-attack', 'retrieved', 'E0C9284F0EC5B56466831C4ACE93E1A6E18DF629B7023299765D5829477B9732', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
