VALUES ('doc-09-mitre-attack-p0-6955', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-05-11T18:51:16.432Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce the principle of least-privilege. Consider implementing access control mechanisms that include both authentication and authorization for code repositories.", "id": "relationship--cb8572e5-de4e-4160-ba8c-d994ebd01e51", "modified": "2026-04-29T14:23:06.203Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--cff94884-3b1c-4987-a70b-6d5643c621c3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6955', 0, 48, '09-mitre-attack', 'retrieved', '157044C4AA76C56D9BE295C37B080D07AC8FFEFAA21427716EE2BF28490C6D85', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
