VALUES ('doc-09-mitre-attack-p0-6956', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-31T14:26:00.974Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce the principle of least privilege by limiting dashboard visibility to only the required users. When using Kubernetes, avoid giving users wildcard permissions or adding users to the `system:masters` group, and use `RoleBindings` rather than `ClusterRoleBindings` to limit user privileges to specific namespaces.(Citation: Kubernetes RBAC)", "external_references": [{"description": "Kubernetes. (n.d.). Role Based Access Control Good Practices. Retrieved March 8, 2023.", "source_name": "Kubernetes RBAC", "url": "https://kubernetes.io/docs/concepts/security/rbac-good-practices/"}], "id": "relationship--cbb40150-0414-4b36-a28b-f7d2088f535a", "modified": "2026-04-29T14:23:06.204Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--0470e792-32f8-46b0-a351-652bc35e9336", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6956', 0, 93, '09-mitre-attack', 'retrieved', '3311AA96DF67A4D693B54A236AF2CF52836926135FD77D53DA538D1AADA1521D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
