VALUES ('doc-09-mitre-attack-p0-6960', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-17T22:00:27.710Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that proper policies are implemented to dictate the the secure enrollment and deactivation of authentication mechanisms, such as MFA, for user accounts.", "id": "relationship--d3851a98-39b3-4105-ba93-c0cd91eb01eb", "modified": "2026-04-29T14:23:06.214Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--f4c1826f-a322-41cd-9557-562100848c84", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6960', 0, 52, '09-mitre-attack', 'retrieved', 'C1048911B5A7420F07E82342A25EA18CA57FB565D7893215E4A11BB5BBC2FE5F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
