VALUES ('doc-09-mitre-attack-p0-6962', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-21T16:42:47.700Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit the user accounts that have access to backups to only those required. In AWS environments, consider using Service Control Policies to restrict API calls to delete backups, snapshots, and images. ", "id": "relationship--d62f97e9-2b94-44d9-88db-99f849a804ec", "modified": "2026-04-29T14:23:06.218Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--f5d8eed6-48a9-4cdf-a3d7-d1ffa99c3d2a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6962', 0, 61, '09-mitre-attack', 'retrieved', '64F278CEA829C8E9430B72A5BDCAB187B51FE6B815267F1FED9A3F574E75CB83', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
