VALUES ('doc-09-mitre-attack-p0-6963', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-05T21:39:44.365Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider defining and enforcing a naming convention for user accounts to more easily spot generic account names that do not fit the typical schema. ", "id": "relationship--d870c87f-897d-44f3-a75a-0fa0211849f3", "modified": "2026-04-29T14:23:06.221Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--d349c66e-18e1-4d8b-a2d7-65af7cbd2ba0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6963', 0, 54, '09-mitre-attack', 'retrieved', '4D1D0A6C2BAC2561C7A54F30911E6E407EF920109FB182ECDF8C1AE65BD0A140', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
