VALUES ('doc-09-mitre-attack-p0-6967', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-10T18:26:56.467Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Prevent users from installing their own launch agents or launch daemons.", "id": "relationship--e2bf1135-6715-446a-aff7-96d5a0a20477", "modified": "2026-04-29T14:23:06.234Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--810aa4ad-61c9-49cb-993f-daa06199421d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6967', 0, 40, '09-mitre-attack', 'retrieved', 'D3668BF6D1FD21CCDD6D29C37DD9880755B2A2F5226734A671E2278BAA54D9E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
