VALUES ('doc-09-mitre-attack-p0-6968', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-14T13:09:51.253Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce the principle of least-privilege. Consider implementing access control mechanisms that include both authentication and authorization.", "id": "relationship--e3d0073d-4507-4966-9cb0-787c02987186", "modified": "2026-04-29T14:23:06.235Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--7ad38ef1-381a-406d-872a-38b136eb5ecc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6968', 0, 45, '09-mitre-attack', 'retrieved', '24D419E05BD5F937E501BC87836AF7C578088C1298FC74978190FFDE0DF0465F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
