VALUES ('doc-09-mitre-attack-p0-6970', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-11T13:13:12.311Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit permissions to discover cloud accounts in accordance with least privilege. Organizations should limit the number of users within the organization with an IAM role that has administrative privileges, strive to reduce all permanent privileged role assignments, and conduct periodic entitlement reviews on IAM users, roles and policies.", "id": "relationship--e73bf2f8-b009-4555-8fda-3407fa87c812", "modified": "2026-04-29T14:23:06.240Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--8f104855-e5b7-4077-b1f5-bc3103b41abe", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6970', 0, 77, '09-mitre-attack', 'retrieved', '98670ECA682FDDB8445073EF4E9C2FF047D47ACBFB58518925F1CFD5DA0B213D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
