VALUES ('doc-09-mitre-attack-p0-6971', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-22T22:46:31.173Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enforce the principle of least privilege by limiting privileges of user accounts so only authorized accounts can modify and/or add server software components.(Citation: NSA and ASD Detect and Prevent Web Shells 2020)", "external_references": [{"description": "NSA and ASD. (2020, April 3). Detect and Prevent Web Shell Malware. Retrieved July 23, 2021.", "source_name": "NSA and ASD Detect and Prevent Web Shells 2020", "url": "https://media.defense.gov/2020/Jun/09/2002313081/-1/-1/0/CSI-DETECT-AND-PREVENT-WEB-SHELL-MALWARE-20200422.PDF"}], "id": "relationship--edbfcc84-4096-4839-b5eb-5025b70ccaca", "modified": "2026-04-29T14:23:06.249Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--d456de47-a16f-4e46-8980-e67478a12dcb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6971', 0, 91, '09-mitre-attack', 'retrieved', '8CBC7CA128B98A97EFA93FC0B8B0CA747ABB5A8FC8144191DA92024536B9E291', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
