VALUES ('doc-09-mitre-attack-p0-6973', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-15T13:23:23.309Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure proper user permissions are in place to prevent adversaries from disabling or modifying firewall settings.", "id": "relationship--f3870f8f-1925-4a3d-863f-0461e0c11f7f", "modified": "2026-04-29T14:23:06.256Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--291ede6c-1473-454c-b614-5ac5ea63c987", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6973', 0, 45, '09-mitre-attack', 'retrieved', 'A7770BBB9FBA88084820C8FA228BF199079FE76CC04000169CDE629E73BA400B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
