INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-6974', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-22T13:06:57.348Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure user permissions groups and roles for access to cloud storage.(Citation: Microsoft Azure Storage Security, 2019) Implement strict Identity and Access Management (IAM) controls to prevent access to storage solutions except for the applications, users, and services that require access.(Citation: Amazon S3 Security, 2019) Ensure that temporary access tokens are issued rather than permanent credentials, especially when access is being granted to entities outside of the internal security boundary.(Citation: Amazon AWS Temporary Security Credentials)", "external_references": [{"description": "Amazon. (2019, May 17). How can I secure the files in my Amazon S3 bucket?. Retrieved October 4, 2019.", "source_name": "Amazon S3 Security, 2019", "url": "https://aws.amazon.com/premiumsupport/knowledge-center/secure-s3-resources/"}, {"description": "Amazon. (n.d.). Temporary Security Credentials. Retrieved October 18, 2019.", "source_name": "Amazon AWS Temporary Security Credentials", "url": "https://docs.aws.amazon.com/IAM/latest/UserGuide/id_credentials_temp.html"}, {"description": "Amlekar, M., Brooks, C., Claman, L., et. al.. (2019, March 20). Azure Storage security guide. Retrieved October 4, 2019.", "source_name": "Microsoft Azure Storage Security, 2019", "url": "https://docs.microsoft.com/en-us/azure/storage/common/storage-security-guide"}], "id": "relationship--f52e6fb6-754b-4b48-ab5b-eff0e6233d7d", "modified": "2026-04-29T14:23:06.258Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--a19e86f8-1c0a-4fea-8407-23b73d615776", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6974', 0, 177, '09-mitre-attack', 'retrieved', 'EE30A82E1BBEA867165B07002B84B542C7A7404F0DD0F1215D6F488A8D0D9DF0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
