VALUES ('doc-09-mitre-attack-p0-6975', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-20T19:26:05.603Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of Authentication, Authorization, and Accounting (AAA) systems will limit actions users can perform and provide a history of user actions to detect unauthorized use and abuse. Ensure least privilege principles are applied to user accounts and groups so that only authorized users can perform configuration changes. (Citation: Cisco IOS Software Integrity Assurance - AAA)", "external_references": [{"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - AAA. Retrieved October 19, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - AAA", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#38"}], "id": "relationship--f63970b4-a3fd-4fc9-8685-2baf0ff6ffff", "modified": "2026-04-29T14:23:06.260Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--818302b2-d640-477b-bf88-873120ce85c4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6975', 0, 109, '09-mitre-attack', 'retrieved', 'ADD745FF0B2506CD83BB42C6780FC9BB2EDB565ABF1579B18508A5786BA55582', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
