VALUES ('doc-09-mitre-attack-p0-6976', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-07-14T14:03:28.682Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that low-privileged accounts do not have permissions to add permissions to accounts or to update container cluster roles. ", "id": "relationship--f91d058b-e69d-46ab-9ba0-f23c368b6190", "modified": "2026-04-29T14:23:06.263Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--35d30338-5bfa-41b0-a170-ec06dfd75f64", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6976', 0, 49, '09-mitre-attack', 'retrieved', 'B95C782B81D7DD254C5F9C5DA1F2A3191C494DDFC109416EDE1C7A7207E37BDB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
