VALUES ('doc-09-mitre-attack-p0-6977', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-05-27T13:59:53.484Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that low-privileged user accounts do not have permissions to add permissions to accounts or update IAM policies.", "id": "relationship--f9a0a532-21a6-47a2-83f8-4abb61cb3fc7", "modified": "2026-04-29T14:23:06.264Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--93e7968a-9074-4eac-8ae9-9f5200ec3317", "spec_version": "2.1", "target_ref": "attack-pattern--2dbbdcd5-92cf-44c0-aea2-fe24783a6bc3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6977', 0, 47, '09-mitre-attack', 'retrieved', 'C32B44681AA11A21729A99CE6A2D62CFD6A9ED60A2BEDB2026AC81A7A64143E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
