VALUES ('doc-09-mitre-attack-p0-6999', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-13T14:10:43.564Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that proper permissions and directory access control are set to deny users the ability to write files to the top-level directory C: and system directories, such as C:\\Windows\\ , to reduce places where malicious files could be placed for execution. Require that all executables be placed in write-protected directories.", "id": "relationship--5a70a968-618c-489e-8087-eabca740aa3a", "modified": "2026-04-29T14:23:06.049Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--987988f0-cf86-4680-a875-2f6456ab2448", "spec_version": "2.1", "target_ref": "attack-pattern--0c2d00da-7742-49e7-9928-4514e5075d32", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-6999', 0, 79, '09-mitre-attack', 'retrieved', '679FC76DC9AC27CD86C3AE16417035EC5A22830102B54924D7B898AA83F7B70B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
