VALUES ('doc-09-mitre-attack-p0-7002', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-20T05:18:46.761Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Set group policies to restrict file permissions to the ~/launchagents folder.(Citation: piazza launch agent mitigation)", "external_references": [{"description": "Antonio Piazza (4n7m4n). (2021, November 23). Defeating Malicious Launch Persistence. Retrieved April 19, 2022.", "source_name": "piazza launch agent mitigation", "url": "https://antman1p-30185.medium.com/defeating-malicious-launch-persistence-156e2b40fc67"}], "id": "relationship--68146568-bc1f-49b6-9477-c6c06b0fa39c", "modified": "2026-04-29T14:23:06.067Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--987988f0-cf86-4680-a875-2f6456ab2448", "spec_version": "2.1", "target_ref": "attack-pattern--d10cbd34-42e3-45c0-84d2-535a09849584", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7002', 0, 67, '09-mitre-attack', 'retrieved', '3FC98ACFCD141AED4844D84296331FAAD6D55107828D04CF607E0EA8891A18D6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
