VALUES ('doc-09-mitre-attack-p0-7004', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T15:11:02.994Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Making PowerShell profiles immutable and only changeable by certain administrators will limit the ability for adversaries to easily create user level persistence.", "id": "relationship--6b4cb169-cda8-49ef-a8db-188c599f50f1", "modified": "2026-04-29T14:23:06.071Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--987988f0-cf86-4680-a875-2f6456ab2448", "spec_version": "2.1", "target_ref": "attack-pattern--0f2c410d-d740-4ed9-abb1-b8f4a7faf6c3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7004', 0, 51, '09-mitre-attack', 'retrieved', '6DED64B349E188C1AB344438F9696473D913AE3B3CD99462E2C10D025323F87C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
