VALUES ('doc-09-mitre-attack-p0-7005', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-25T14:09:38.748Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Protect generated event files that are stored locally with proper permissions and authentication and limit opportunities for adversaries to increase privileges by preventing Privilege Escalation opportunities.", "id": "relationship--6db4729b-596c-43c1-81f4-d374a2f2e06b", "modified": "2026-04-29T14:23:06.074Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--987988f0-cf86-4680-a875-2f6456ab2448", "spec_version": "2.1", "target_ref": "attack-pattern--799ace7f-e227-4411-baa0-8868704f2a69", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7005', 0, 55, '09-mitre-attack', 'retrieved', '78ED502A444F1C4968DBDDEC99BA1A9DC73D1FE0AE896036528BB055B9149283', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
