VALUES ('doc-09-mitre-attack-p0-7007', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-26T16:17:09.665Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Install software in write-protected locations. Set directory access controls to prevent file writes to the search paths for applications, both in the folders where applications are run from and the standard library folders.", "id": "relationship--7253ab74-8fbb-422b-bf37-258981865b87", "modified": "2026-04-29T14:23:06.081Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--987988f0-cf86-4680-a875-2f6456ab2448", "spec_version": "2.1", "target_ref": "attack-pattern--aedfca76-3b30-4866-b2aa-0f1d7fd1e4b6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7007', 0, 62, '09-mitre-attack', 'retrieved', '37593378AACC0BA322EE5E2EB19789009CB76B748FA37F5DBDF15D42925E4F2B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
