VALUES ('doc-09-mitre-attack-p0-7009', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-10-07T21:33:46.022Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Applying strict permissions to directories where shortcuts are stored, such as the startup folder, can prevent unauthorized modifications.", "id": "relationship--78aa862c-56a1-477b-b2d0-8d48d1969354", "modified": "2026-04-29T14:23:06.090Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--987988f0-cf86-4680-a875-2f6456ab2448", "spec_version": "2.1", "target_ref": "attack-pattern--4ab929c6-ee2d-4fb5-aab4-b14be2ed7179", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7009', 0, 47, '09-mitre-attack', 'retrieved', '3FA671050C5294C6A7C94B9EDF2DB00F4B82B31AD89B34627E81573A0F7FA572', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
