VALUES ('doc-09-mitre-attack-p0-7010', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-04T19:13:24.913Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Applying more restrictive permissions to files and directories could prevent adversaries from modifying their access control lists. Additionally, ensure that user settings regarding local and remote symbolic links are properly set or disabled where unneeded.(Citation: create_sym_links)", "external_references": [{"description": "Microsoft. (2021, October 28). Create symbolic links. Retrieved April 27, 2022.", "source_name": "create_sym_links", "url": "https://docs.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/create-symbolic-links"}], "id": "relationship--79412658-c213-4746-b03d-c828957d6ddb", "modified": "2026-04-29T14:23:06.091Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--987988f0-cf86-4680-a875-2f6456ab2448", "spec_version": "2.1", "target_ref": "attack-pattern--65917ae0-b854-4139-83fe-bf2441cf0196", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7010', 0, 82, '09-mitre-attack', 'retrieved', 'A0AC90241F72C0409870142AB39FB21AE69A3E6785798607F654232BF6702B34', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
