VALUES ('doc-09-mitre-attack-p0-7038', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-21T20:46:36.916Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure proper process and file permissions are in place to prevent adversaries from disabling or interfering with logging or deleting or modifying .evtx logging files. Ensure .evtx files, which are located at C:\\Windows\\system32\\Winevt\\Logs (Citation: win_xml_evt_log), have the proper file permissions for limited, legitimate access and audit policies for detection. ", "external_references": [{"description": "Forensics Wiki. (2021, June 19). Windows XML Event Log (EVTX). Retrieved September 13, 2021.", "source_name": "win_xml_evt_log", "url": "https://forensicswiki.xyz/wiki/index.php?title=Windows_XML_Event_Log_(EVTX)"}], "id": "relationship--ee8e9551-278a-4f96-8179-d9290b95ed99", "modified": "2026-04-29T14:23:06.250Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--987988f0-cf86-4680-a875-2f6456ab2448", "spec_version": "2.1", "target_ref": "attack-pattern--1411e6b8-80a6-4465-9909-54eaa9c67ce0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7038', 0, 99, '09-mitre-attack', 'retrieved', '63CE1BE8A0A1E0A8F8357A235F06826FCBA5643DF389C0B6E0635E1E69CA500A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
