VALUES ('doc-09-mitre-attack-p0-7039', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-04T12:52:13.350Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Restrict file shares to specific directories with access only to necessary users.", "id": "relationship--f4ac7555-2b20-4345-998e-6ffc462cab03", "modified": "2026-04-29T14:23:06.257Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--987988f0-cf86-4680-a875-2f6456ab2448", "spec_version": "2.1", "target_ref": "attack-pattern--837f9164-50af-4ac0-8219-379d8a74cefc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7039', 0, 41, '09-mitre-attack', 'retrieved', 'E35B653DDCD35E67D18E97C2B9537E41B48BDE808E52078B4C389EAF9AF41560', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
