VALUES ('doc-09-mitre-attack-p0-7040', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-21T21:13:51.329Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "When using an MDM, ensure the permissions granted are specific to the requirements of the binary. Full Disk Access should be restricted to only necessary binaries in alignment with policy. ", "id": "relationship--f5b14e1c-a5d6-45fb-b329-793e0a2b7ca4", "modified": "2026-04-29T14:23:06.259Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--987988f0-cf86-4680-a875-2f6456ab2448", "spec_version": "2.1", "target_ref": "attack-pattern--e8a0a025-3601-4755-abfb-8d08283329fb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7040', 0, 60, '09-mitre-attack', 'retrieved', '30BAE938DDA85D58A73DECD975AA3D207057232CCAB1438AA4E6D572593E84D5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
