VALUES ('doc-09-mitre-attack-p0-7041', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-11-27T14:58:00.679Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure the Increase Scheduling Priority option to only allow the Administrators group the rights to schedule a priority process. This can be configured through GPO: Computer Configuration > [Policies] > Windows Settings > Security Settings > Local Policies > User Rights Assignment: Increase scheduling priority. (Citation: TechNet Scheduling Priority)", "external_references": [{"description": "Microsoft. (2013, May 8). Increase scheduling priority. Retrieved December 18, 2017.", "source_name": "TechNet Scheduling Priority", "url": "https://technet.microsoft.com/library/dn221960.aspx"}], "id": "relationship--00b0b6ec-a9eb-4fdd-b7ea-6e6c8a8ab1fc", "modified": "2026-04-29T14:23:05.903Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--005a06c6-14bf-4118-afa0-ebcd8aebb0c9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7041', 0, 97, '09-mitre-attack', 'retrieved', '8DF64F22B3C2FC107EA41B0BE08CB7BBE517137A81F0FAD9FD37702F9A4F8595', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
