VALUES ('doc-09-mitre-attack-p0-7043', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-25T12:41:50.804Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit the number of cloud accounts and services with permission to query the secrets manager to only those required. Ensure that accounts and services with permissions to query the secrets manager only have access to the secrets they require.", "id": "relationship--04724f1d-f6ff-448e-bcac-4bcda34d895b", "modified": "2026-04-29T14:23:05.909Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--cfb525cc-5494-401d-a82b-2539ca46a561", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7043', 0, 68, '09-mitre-attack', 'retrieved', 'D539763F0017EA87A8198F3313317D12FB82864B7C732B9003B1B613C03430D0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
