VALUES ('doc-09-mitre-attack-p0-7044', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-17T18:49:50.110Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Do not allow administrator accounts that have permissions to add IIS components to be used for day-to-day operations that may expose these permissions to potential adversaries and/or other unprivileged systems.", "id": "relationship--05ae3ecc-6920-4828-b708-f0acdf0e2ff3", "modified": "2026-04-29T14:23:05.911Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--b46a801b-fd98-491c-a25a-bca25d6e3001", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7044', 0, 59, '09-mitre-attack', 'retrieved', 'F3610C98F0221F82D0646A67C5F8B91109A7DBDB016A43B4ED406221C2A44A41', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
