VALUES ('doc-09-mitre-attack-p0-7046', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-30T20:18:35.375Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit the number of accounts and services with permission to query information from password stores to only those required. Ensure that accounts and services with permissions to query password stores only have access to the secrets they require.", "id": "relationship--0a4819da-bba0-487b-abff-41d6fba75922", "modified": "2026-04-29T14:23:05.917Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--3fc9b85a-2862-4363-a64d-d692e3ffbee0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7046', 0, 67, '09-mitre-attack', 'retrieved', '6459DE0AE316D55A0E1A6CB450624E9229B3E6AEE1810E5DEF7C1599E3C3A5E5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
