VALUES ('doc-09-mitre-attack-p0-7047', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-10T18:33:36.463Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that permissions disallow services that run at a higher permissions level from being created or interacted with by a user with a lower permission level.", "id": "relationship--10625b4c-7ecc-49a0-b8e3-c9f2d8cba2da", "modified": "2026-04-29T14:23:05.926Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--f1951e8a-500e-4a26-8803-76d95c4554b4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7047', 0, 55, '09-mitre-attack', 'retrieved', '9B095DFEC7769AA7BB69CEA0D2E75C9CC3F36919E6D78B7A4965C3E1869F3BED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
