VALUES ('doc-09-mitre-attack-p0-7048', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-12-30T21:41:03.545Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Do not allow administrator accounts that have permissions to add component software on these services to be used for day-to-day operations that may expose them to potential adversaries on unprivileged systems. ", "id": "relationship--1422f68c-e962-4a13-8074-77f5b99b7718", "modified": "2026-04-29T14:23:05.931Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--35187df2-31ed-43b6-a1f5-2f1d3d58d3f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7048', 0, 61, '09-mitre-attack', 'retrieved', '04908320256FE4AD8BD6B922E2509D3B13440AFE4C9F2E1588EBD6D91A4A2EC8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
