VALUES ('doc-09-mitre-attack-p0-7052', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-04T19:17:42.259Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure critical system files as well as those known to be abused by adversaries have restrictive permissions and are owned by an appropriately privileged account, especially if access is not required by users nor will inhibit system functionality.", "id": "relationship--2a7a152f-79c9-45c9-9f09-0d39f563ad05", "modified": "2026-04-29T14:23:05.962Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--34e793de-0274-4982-9c1a-246ed1c19dee", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7052', 0, 67, '09-mitre-attack', 'retrieved', '0606BF5243421A3EB66B5E83CF13B5BA35DFFDA20A4521CC6275FACC9FEB3601', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
