VALUES ('doc-09-mitre-attack-p0-7053', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-26T04:01:09.879Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit access to the root account and prevent users from modifying PAM components through proper privilege separation (ex SELinux, grsecurity, AppArmor, etc.) and limiting Privilege Escalation opportunities.", "id": "relationship--327a2877-8820-4def-8cd8-787f06cfd987", "modified": "2026-04-29T14:23:05.985Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--06c00069-771a-4d57-8ef5-d3718c1a8771", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7053', 0, 56, '09-mitre-attack', 'retrieved', '0233E292776864A7A716E71DCBAD792749ABF94DD7FF28BEA8140EECE5F6C671', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
