VALUES ('doc-09-mitre-attack-p0-7054', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-12T15:27:00.954Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "If the service is necessary, lock down critical enclaves with separate WinRM accounts and permissions.", "id": "relationship--335d97be-914a-4198-aa06-55095e850ffc", "modified": "2026-04-29T14:23:05.986Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--60d0c01d-e2bf-49dd-a453-f8a9c9fa6f65", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7054', 0, 44, '09-mitre-attack', 'retrieved', '466C08938FB2ADD4E91F3911CF48FDDF4416FB8EB7153EDFF991042F83C8F076', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
