VALUES ('doc-09-mitre-attack-p0-7055', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-10T18:23:06.811Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that permissions disallow services that run at a higher permissions level from being created or interacted with by a user with a lower permission level.", "id": "relationship--3ab372ea-c8be-4fb1-a9d3-4aa542e1f10f", "modified": "2026-04-29T14:23:06.001Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--d157f9d2-d09a-4efa-bb2a-64963f94e253", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7055', 0, 55, '09-mitre-attack', 'retrieved', '49BFE6C21BD5014FDF8071FC06C9CCDAABD31FA08E3974B6BE70A7F724C92346', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
