VALUES ('doc-09-mitre-attack-p0-7056', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T16:08:30.026Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Restrict administrator accounts to as few individuals as possible, following least privilege principles. Prevent credential overlap across systems of administrator and privileged accounts, particularly between network and non-network platforms, such as servers or endpoints.", "id": "relationship--415fc129-cac9-4d8c-8285-8ea563489b03", "modified": "2026-04-29T14:23:06.014Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--b8017880-4b1e-42de-ad10-ae7ac6705166", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7056', 0, 63, '09-mitre-attack', 'retrieved', 'AB985ECC5618EC2567F52D93CC23168111B3FFD8E9E9D83847396DC4F859F785', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
