VALUES ('doc-09-mitre-attack-p0-7057', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-20T19:18:34.090Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Follow best practices in restricting access to privileged accounts to avoid hostile programs from accessing such sensitive information.", "id": "relationship--4274e62f-1dc9-47d0-800a-f812cfe4e071", "modified": "2026-04-29T14:23:06.016Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--d0b4fcdb-d67d-4ed2-99ce-788b12f8c0f4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7057', 0, 47, '09-mitre-attack', 'retrieved', 'FD12172C03C0180E61B48DDD1D507CC69537DF265C9FA689AB3384750B1E1302', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
