VALUES ('doc-09-mitre-attack-p0-7061', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-05T21:50:07.511Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use least privilege and protect administrative access to the Domain Controller and Active Directory Federation Services (AD FS) server. Do not create service accounts with administrative privileges.", "id": "relationship--48357d6a-6d00-42a6-b687-cbd5a9a8ecd6", "modified": "2026-04-29T14:23:06.024Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--ebb42bbe-62d7-47d7-a55f-3b08b61d792d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7061', 0, 56, '09-mitre-attack', 'retrieved', '2F7269BBC147C937A1991342F2554D5D81B585EE8B13F4E59A96D5D28AD0475F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
