VALUES ('doc-09-mitre-attack-p0-7062', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T17:42:23.791Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit access to the root account and prevent users from loading kernel modules and extensions through proper privilege separation and limiting Privilege Escalation opportunities.", "id": "relationship--4907e8fb-e224-49a6-aa94-5a76afa714ba", "modified": "2026-04-29T14:23:06.025Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--a1b52199-c8c5-438a-9ded-656f1d0888c6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7062', 0, 53, '09-mitre-attack', 'retrieved', 'BEEBF9428B53494A21B7E935EDA50C857C719853541B9EB72E743B94A0A5F46C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
