VALUES ('doc-09-mitre-attack-p0-7063', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-18T18:03:37.709Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit permissions so that users and user groups cannot create tokens. This setting should be defined for the local system account only. GPO: Computer Configuration > [Policies] > Windows Settings > Security Settings > Local Policies > User Rights Assignment: Create a token object. (Citation: Microsoft Create Token) Also define who can create a process level token to only the local and network service through GPO: Computer Configuration > [Policies] > Windows Settings > Security Settings > Local Policies > User Rights Assignment: Replace a process level token.(Citation: Microsoft Replace Process Token)\n\nAdministrators should log in as a standard user but run their tools with administrator privileges using the built-in access token manipulation command runas .(Citation: Microsoft runas)", "external_references": [{"description": "Brower, N., Lich, B. (2017, April 19). Create a token object. Retrieved December 19, 2017.", "source_name": "Microsoft Create Token", "url": "https://docs.microsoft.com/windows/device-security/security-policy-settings/create-a-token-object"}, {"description": "Brower, N., Lich, B. (2017, April 19). Replace a process level token. Retrieved December 19, 2017.", "source_name": "Microsoft Replace Process Token", "url": "https://docs.microsoft.com/windows/device-security/security-policy-settings/replace-a-process-level-token"}, {"description": "Microsoft TechNet. (n.d.). Runas. Retrieved April 21, 2017.", "source_name": "Microsoft runas", "url": "https://technet.microsoft.com/en-us/library/bb490994.aspx"}], "id": "relationship--49aeba9e-9ae9-4eb2-873e-b8ab4f8ab347", "modified": "2026-04-29T14:23:06.026Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--8cdeb020-e31e-4f88-a582-f53dcfbda819", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7063', 0, 207, '09-mitre-attack', 'retrieved', '0BF8E452BB47A884B0761CFE469A301A07816ACA77DEB07E71229CDD7B145099', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
