VALUES ('doc-09-mitre-attack-p0-7064', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-12-19T19:43:34.930Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Prevent adversary access to privileged accounts or access necessary to perform this technique.", "id": "relationship--49f4c3d1-25a1-49e1-af9f-80a4c2eb4bf7", "modified": "2026-04-29T14:23:06.026Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--16ab6452-c3c1-497c-a47d-206018ca1ada", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7064', 0, 42, '09-mitre-attack', 'retrieved', '4D9640D623C7A37C0AF799E0452AAD5140FB949A6BC92024FE3E8A67487C403D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
