VALUES ('doc-09-mitre-attack-p0-7072', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-30T17:56:42.438Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use the principal of least privilege and protect administrative access to domain trusts and identity tenants.", "id": "relationship--53b041d2-4250-473e-b7c6-3b05fcdf3d3f", "modified": "2026-04-29T14:23:06.039Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--24769ab5-14bd-4f4e-a752-cfb185da53ee", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7072', 0, 45, '09-mitre-attack', 'retrieved', '8B9CCE9D2EC4A64A48D0E6E11B01C9043CFB51EFC7C6FD1F441369F56EF7F08F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
