VALUES ('doc-09-mitre-attack-p0-7083', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-29T17:17:31.592Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Restrict execution of particularly vulnerable binaries to privileged accounts or groups that need to use it to lessen the opportunities for malicious usage.", "id": "relationship--6dc1f5ca-8881-4d06-b192-7bc502ea94ce", "modified": "2026-04-29T14:23:06.075Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--457c7820-d331-465a-915e-42f85500ccc4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7083', 0, 52, '09-mitre-attack', 'retrieved', 'CF87FB7A51632DFBBE473A5BE72507C739F1D6781B4D2F8A82BA4EA9A8D84724', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
