VALUES ('doc-09-mitre-attack-p0-7084', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T16:18:37.239Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit credential overlap across systems to prevent the damage of credential compromise and reduce the adversary''s ability to perform Lateral Movement between systems.", "id": "relationship--72904b3d-5b24-4698-8094-8919f3bda494", "modified": "2026-04-29T14:23:06.082Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--51a14c76-dd3b-440b-9c20-2bf91d25a814", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7084', 0, 52, '09-mitre-attack', 'retrieved', '31D2F73089040BF22B136DE0F1F4ADAF2A084CDFC7C1549B8D5B5D73288832F8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
