VALUES ('doc-09-mitre-attack-p0-7086', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-01T17:17:37.209Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Manage the creation, modification, use, and permissions associated to privileged accounts, including SYSTEM and root.", "id": "relationship--764f3883-da8b-421d-96ed-e14878bcc72e", "modified": "2026-04-29T14:23:06.087Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--b83e166d-13d7-4b52-8677-dff90c548fd7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7086', 0, 44, '09-mitre-attack', 'retrieved', '567A854F5F1FB982C3534430A6C57388DD8D00EA41653309D3365BBCF9809700', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
