VALUES ('doc-09-mitre-attack-p0-7092', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T16:21:55.301Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Audit domain and local accounts as well as their permission levels routinely to look for situations that could allow an adversary to gain wide access by obtaining credentials of a privileged account. (Citation: TechNet Credential Theft) (Citation: TechNet Least Privilege) These audits should also include if default accounts have been enabled, or if new local accounts are created that have not been authorized. Follow best practices for design and administration of an enterprise network to limit privileged account use across administrative tiers. (Citation: Microsoft Securing Privileged Access)", "external_references": [{"description": "Microsoft. (2016, April 15). Attractive Accounts for Credential Theft. Retrieved June 3, 2016.", "source_name": "TechNet Credential Theft", "url": "https://technet.microsoft.com/en-us/library/dn535501.aspx"}, {"description": "Microsoft. (2016, April 16). Implementing Least-Privilege Administrative Models. Retrieved June 3, 2016.", "source_name": "TechNet Least Privilege", "url": "https://technet.microsoft.com/en-us/library/dn487450.aspx"}, {"description": "Plett, C., Poggemeyer, L. (12, October 26). Securing Privileged Access Reference Material. Retrieved April 25, 2017.", "source_name": "Microsoft Securing Privileged Access", "url": "https://docs.microsoft.com/en-us/windows-server/identity/securing-privileged-access/securing-privileged-access-reference-material#a-nameesaebmaesae-administrative-forest-design-approach"}], "id": "relationship--89887815-acfc-42f9-9172-81437cf9ff69", "modified": "2026-04-29T14:23:06.113Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--b17a1a56-e99c-403c-8948-561df0cffe81", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7092', 0, 180, '09-mitre-attack', 'retrieved', '19D6E3356C68B8A2AACA7F88993FEC2190355172EE15787A0A9E146FCFEAAE3E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
