VALUES ('doc-09-mitre-attack-p0-7094', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-03T15:30:27.826Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit permissions associated with creating and modifying platform images or containers based on the principle of least privilege.", "id": "relationship--8dfdc783-d869-498b-b4e0-1d75b30e2d67", "modified": "2026-04-29T14:23:06.119Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--4fd8a28b-4b3a-4cd6-a8cf-85ba5f824a7f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7094', 0, 47, '09-mitre-attack', 'retrieved', '292B53CC93958590E105CA5A24034A767C6A7D736F8350F6553F0A8BCA175210', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
