VALUES ('doc-09-mitre-attack-p0-7095', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-19T14:30:22.451Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure the Increase Scheduling Priority option to only allow the Administrators group the rights to schedule a priority process. This can be can be configured through GPO: Computer Configuration > [Policies] > Windows Settings > Security Settings > Local Policies > User Rights Assignment: Increase scheduling priority. (Citation: TechNet Scheduling Priority)", "external_references": [{"description": "Microsoft. (2013, May 8). Increase scheduling priority. Retrieved December 18, 2017.", "source_name": "TechNet Scheduling Priority", "url": "https://technet.microsoft.com/library/dn221960.aspx"}], "id": "relationship--8f09085f-c1cf-4321-89c4-17d93e774f6f", "modified": "2026-04-29T14:23:06.120Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--35dd844a-b219-4e2b-a6bb-efa9a75995a9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7095', 0, 99, '09-mitre-attack', 'retrieved', 'DE8A61B39C899C33D2D97863A736B8E0D01AECDD6628C0EE0505B1A2288F6605', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
