VALUES ('doc-09-mitre-attack-p0-7096', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T14:24:35.581Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Remove users from the local administrator group on systems.", "id": "relationship--922037af-61f0-42d8-8b57-310b6b56ea5a", "modified": "2026-04-29T14:23:06.124Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--120d5519-3098-4e1c-9191-2aa61232f073", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7096', 0, 38, '09-mitre-attack', 'retrieved', 'E36ACB938E37E2F6F2087D7DF9F2FB9B4CD22697E5B5375F7BCF3D03E6FAEFDD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
