VALUES ('doc-09-mitre-attack-p0-7097', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-12T14:50:52.639Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Deny remote use of local admin credentials to log into systems. Do not allow domain user accounts to be in the local Administrators group multiple systems.", "id": "relationship--935ca61c-b4ff-4cfc-a4e9-9b8aa9514ea3", "modified": "2026-04-29T14:23:06.126Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--4f9ca633-15c5-463c-9724-bdcd54fde541", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7097', 0, 55, '09-mitre-attack', 'retrieved', '5238B214906CC1A7E3A8B3455D4BE614015B9481EB7025BC6186E4F21D6C144C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
