VALUES ('doc-09-mitre-attack-p0-7098', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-21T21:13:20.433Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Remove unnecessary users from the local administrator group on systems.", "id": "relationship--96c55f98-c988-43ef-8946-e09c72280ae9", "modified": "2026-04-29T14:23:06.131Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--e8a0a025-3601-4755-abfb-8d08283329fb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7098', 0, 39, '09-mitre-attack', 'retrieved', '3C5740FD4BDB01527C74F8202AB01D9BC5D85ACBAB4A33FDCBD21A3B2B97DFEF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
