VALUES ('doc-09-mitre-attack-p0-7099', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-12-19T21:05:38.415Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure proper permissions are in place to help prevent adversary access to privileged accounts necessary to install a bootkit.", "id": "relationship--99662840-c630-4858-8d44-331d0b31fbc1", "modified": "2026-04-29T14:23:06.134Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--1b7b1806-7746-41a1-a35d-e48dae25ddba", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7099', 0, 48, '09-mitre-attack', 'retrieved', '94F06AC644C57892EACB151918ED58DAAA7A5D9F2D304AA0BB12C77A85CA5B25', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
