VALUES ('doc-09-mitre-attack-p0-7100', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-04T19:13:24.905Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure critical system files as well as those known to be abused by adversaries have restrictive permissions and are owned by an appropriately privileged account, especially if access is not required by users nor will inhibit system functionality.", "id": "relationship--9a8788d7-3f27-49b4-bb60-0b0d581fa812", "modified": "2026-04-29T14:23:06.136Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--65917ae0-b854-4139-83fe-bf2441cf0196", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7100', 0, 67, '09-mitre-attack', 'retrieved', '50ACC64FC122EC55A16009E6773ED2322BCC23CDBBDA8926E48F4AA0AFD01320', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
