INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7101', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-29T16:39:26.350Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure containers are not running as root by default. In Kubernetes environments, consider defining Pod Security Standards that prevent pods from running privileged containers and using the `NodeRestriction` admission controller to deny the kublet access to nodes and pods outside of the node it belongs to.(Citation: Kubernetes Hardening Guide) (Citation: Kubernetes Admission Controllers)", "external_references": [{"description": "Kubernetes. (n.d.). Admission Controllers Reference. Retrieved March 8, 2023.", "source_name": "Kubernetes Admission Controllers", "url": "https://kubernetes.io/docs/reference/access-authn-authz/admission-controllers"}, {"description": "National Security Agency, Cybersecurity and Infrastructure Security Agency. (2022, March). Kubernetes Hardening Guide. Retrieved April 1, 2022.", "source_name": "Kubernetes Hardening Guide", "url": "https://media.defense.gov/2022/Aug/29/2003066362/-1/-1/0/CTR_KUBERNETES_HARDENING_GUIDANCE_1.2_20220829.PDF"}], "id": "relationship--9dcf3707-34ff-4a44-b65b-fc1f8f127bf5", "modified": "2026-04-29T14:23:06.140Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--7b50a1d3-4ca7-45d1-989d-a6503f04bfe1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7101', 0, 123, '09-mitre-attack', 'retrieved', 'A61F70E45FC9887B0CBC9C8ED78424F18B0E03885E6EF4891956268885429D83', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
