VALUES ('doc-09-mitre-attack-p0-7104', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-27T17:55:27.467Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit domain admin account permissions to domain controllers and limited servers. Delegate other admin functions to separate accounts.", "id": "relationship--a6e6f751-5c93-4a31-afdc-78513aaea15a", "modified": "2026-04-29T14:23:06.152Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--768dce68-8d0d-477a-b01d-0eea98b963a1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7104', 0, 47, '09-mitre-attack', 'retrieved', '58DA4A0026C8EBFEA46D34360DA28B28844FB9BBD96C6F8588797EF2CE095C51', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
