INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7108', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-09T13:41:14.487Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "When PowerShell is necessary, consider restricting PowerShell execution policy to administrators. Be aware that there are methods of bypassing the PowerShell execution policy, depending on environment configuration.(Citation: Netspi PowerShell Execution Policy Bypass)\n\nPowerShell JEA (Just Enough Administration) may also be used to sandbox administration and limit what commands admins/users can execute through remote PowerShell sessions.(Citation: Microsoft PS JEA)", "external_references": [{"description": "Microsoft. (2022, November 17). Just Enough Administration. Retrieved March 27, 2023.", "source_name": "Microsoft PS JEA", "url": "https://learn.microsoft.com/powershell/scripting/learn/remoting/jea/overview?view=powershell-7.3"}, {"description": "Sutherland, S. (2014, September 9). 15 Ways to Bypass the PowerShell Execution Policy. Retrieved September 12, 2024.", "source_name": "Netspi PowerShell Execution Policy Bypass", "url": "https://www.netspi.com/blog/technical-blog/network-penetration-testing/15-ways-to-bypass-the-powershell-execution-policy/"}], "id": "relationship--ad32e902-6f48-4c8f-bc3d-2fc06f045eed", "modified": "2026-04-29T14:23:06.161Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--7385dfaf-6886-4229-9ecd-6fd678040830", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7108', 0, 131, '09-mitre-attack', 'retrieved', 'D3C90A1DE5F1CFFE1CE456B9A5B83D30791B33738205108B484BF4B6F05AA554', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
