VALUES ('doc-09-mitre-attack-p0-7109', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-24T21:16:16.730Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Do not allow administrator accounts that have permissions to modify the Web content of organization login portals to be used for day-to-day operations that may expose them to potential adversaries on unprivileged systems.", "id": "relationship--adffe817-2460-49c7-be30-44afea58d7f8", "modified": "2026-04-29T14:23:06.162Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--69e5226d-05dc-4f15-95d7-44f5ed78d06e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7109', 0, 62, '09-mitre-attack', 'retrieved', 'FF6FEBD1AA86470A6C9EE5FC05974DD54346E1BA19BD3FF042F27C12489EAD8C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
