VALUES ('doc-09-mitre-attack-p0-7110', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T16:36:51.582Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit credential overlap across systems to prevent the damage of credential compromise and reduce the adversary''s ability to perform Lateral Movement between systems.", "id": "relationship--b06103d8-d410-418e-851a-63ca820cc27e", "modified": "2026-04-29T14:23:06.166Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--e624264c-033a-424d-9fd7-fc9c3bbdb03e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7110', 0, 52, '09-mitre-attack', 'retrieved', '97545212D92EAF3D67A4D6AC7551CA8E74E8327BA3C4E1F63E297B3005D8DCC3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
