VALUES ('doc-09-mitre-attack-p0-7114', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-20T15:39:37.686Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Prevent adversary access to privileged accounts or access necessary to replace system firmware.", "id": "relationship--b4dafcd2-fed8-4266-b83e-f4033ada0d55", "modified": "2026-04-29T14:23:06.172Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--f5bb433e-bdf6-4781-84bc-35e97e43be89", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7114', 0, 42, '09-mitre-attack', 'retrieved', '11E65B73D26E0815E6AFBE4E97BAD3BC79B253A9560FD051366CBCE6FAB7D0E2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
