VALUES ('doc-09-mitre-attack-p0-7115', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-17T15:24:12.401Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Restrict permissions and access to the AD FS server to only originate from privileged access workstations.(Citation: FireEye ADFS)", "external_references": [{"description": "Bierstock, D., Baker, A. (2019, March 21). I am AD FS and So Can You. Retrieved December 17, 2020.", "source_name": "FireEye ADFS", "url": "https://www.troopers.de/troopers19/agenda/fpxwmn/"}], "id": "relationship--b51d04ec-51da-4017-b806-210429592565", "modified": "2026-04-29T14:23:06.173Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--1f9c2bae-b441-4f66-a8af-b65946ee72f2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7115', 0, 73, '09-mitre-attack', 'retrieved', '9028AE29DA79929A1AD0090D4494063FC74CE38D97DD34D618A07B47C0C0980F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
