VALUES ('doc-09-mitre-attack-p0-7116', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-25T19:19:09.956Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider removing the local Administrators group from the list of groups allowed to log in through RDP.", "id": "relationship--b6c10d21-5e91-4dfc-b76e-e94d7142ed32", "modified": "2026-04-29T14:23:06.175Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--e0033c16-a07e-48aa-8204-7c3ca669998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7116', 0, 46, '09-mitre-attack', 'retrieved', '72331FA4590F6A7E0ECFCB0F2BEBE00546BCF580200289126D17272190DF7881', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
