VALUES ('doc-09-mitre-attack-p0-7122', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-21T17:07:54.282Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Follow best practices for design and administration of an enterprise network to limit privileged account use across administrative tiers.(Citation: Tilbury Windows Credentials)", "external_references": [{"description": "Chad Tilbury. (2017, August 8). 1Windows Credentials: Attack, Mitigation, Defense. Retrieved February 21, 2020.", "source_name": "Tilbury Windows Credentials", "url": "https://www.first.org/resources/papers/conf2017/Windows-Credentials-Attacks-and-Mitigation-Techniques.pdf"}], "id": "relationship--bce3518d-52d4-4dc3-9de0-4d801048220d", "modified": "2026-04-29T14:23:06.183Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--1ecfdab8-7d59-4c98-95d4-dc41970f57fc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7122', 0, 73, '09-mitre-attack', 'retrieved', '9D13A4A88A51A74657641C6FF29A45E8EEB061C739836C124450D9C071AFB85B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
