VALUES ('doc-09-mitre-attack-p0-7125', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-12-30T21:43:04.870Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Do not allow administrator accounts that have permissions to add component software on these services to be used for day-to-day operations that may expose them to potential adversaries on unprivileged systems. ", "id": "relationship--c2d97d3f-c597-4070-acb0-6c000eac5d39", "modified": "2026-04-29T14:23:06.192Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--f9e9365a-9ca2-4d9c-8e7c-050d73d1101a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7125', 0, 61, '09-mitre-attack', 'retrieved', 'F200153AEE15AA2BA5B307A112CD5D730BABE388C55FF2CD3A3BBAA92E3D2E2F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
