INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7126', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-21T22:07:25.435Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Utilize Yama (ex: /proc/sys/kernel/yama/ptrace_scope) to mitigate ptrace based process injection by restricting the use of ptrace to privileged users only. Other mitigation controls involve the deployment of security kernel modules that provide advanced access control and process restrictions such as SELinux, grsecurity, and AppArmor. ", "id": "relationship--c7676864-765f-4c08-951e-fb14f35f16c1", "modified": "2026-04-29T14:23:06.198Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--ea016b56-ae0e-47fe-967a-cc0ad51af67f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7126', 0, 74, '09-mitre-attack', 'retrieved', '5A620F28EE7062C7CD1CF9810C094983337C333DBA6ABAFA80C69FCDA04C68FF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
