INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7128', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-20T19:11:15.052Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Follow best practices in restricting access to privileged accounts to avoid hostile programs from accessing sensitive information.", "id": "relationship--d039cf20-a85b-4179-b164-6200decb9bd8", "modified": "2026-04-29T14:23:06.210Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--3120b9fa-23b8-4500-ae73-09494f607b7d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7128', 0, 46, '09-mitre-attack', 'retrieved', 'AC27583787135CFE6A86E0591D816484CDBCD5FEF826EBB684BEA6D7809926A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
