VALUES ('doc-09-mitre-attack-p0-7132', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T19:42:19.915Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Restrict administrator accounts to as few individuals as possible, following least privilege principles. Prevent credential overlap across systems of administrator and privileged accounts, particularly between network and non-network platforms, such as servers or endpoints.", "id": "relationship--de4ce747-488a-4def-8ede-8a3d371c9dd4", "modified": "2026-04-29T14:23:06.228Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--ae7f3575-0a5e-427e-991b-fe03ad44c754", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7132', 0, 63, '09-mitre-attack', 'retrieved', 'DEB03502D9FEF93C331A5265D4D149C69A1A485E3AF743DEA17156E43BCBF734', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
