VALUES ('doc-09-mitre-attack-p0-7133', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-11-27T13:52:46.029Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure the Increase Scheduling Priority option to only allow the Administrators group the rights to schedule a priority process. This can be configured through GPO: Computer Configuration > [Policies] > Windows Settings > Security Settings > Local Policies > User Rights Assignment: Increase scheduling priority. (Citation: TechNet Scheduling Priority)", "external_references": [{"description": "Microsoft. (2013, May 8). Increase scheduling priority. Retrieved December 18, 2017.", "source_name": "TechNet Scheduling Priority", "url": "https://technet.microsoft.com/library/dn221960.aspx"}], "id": "relationship--e23ce4ac-b82c-4af1-9545-2bb237a03ed1", "modified": "2026-04-29T14:23:06.233Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--f3d95a1f-bba2-44ce-9af7-37866cd63fd0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7133', 0, 97, '09-mitre-attack', 'retrieved', 'A565B2E7941A7FA6CFF1389B0CBAFCA31176FC8C49B65561DEE47140CE3AC81D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
