VALUES ('doc-09-mitre-attack-p0-7135', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-25T19:34:15.124Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Do not allow remote access to services as a privileged account unless necessary.", "id": "relationship--e3f593f3-0cea-4795-95a1-7be411c91291", "modified": "2026-04-29T14:23:06.236Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--5b0ad6f8-6a16-4966-a4ef-d09ea6e2a9f5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7135', 0, 42, '09-mitre-attack', 'retrieved', '2CF25CC442D3C6F2D18AD65F6D7620B7EDC5A8B409881945EBD30B1225033BED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
