VALUES ('doc-09-mitre-attack-p0-7138', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-12T14:37:27.489Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider removing the local Administrators group from the list of groups allowed to log in through RDP.", "id": "relationship--e7e4be4c-a6ae-44bc-b3af-9c0c41f9212e", "modified": "2026-04-29T14:23:06.241Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--eb062747-2193-45de-8fa2-e62549c37ddf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7138', 0, 46, '09-mitre-attack', 'retrieved', 'BE1BD8FFE91D99EE271F7533F4684CE5D776773089790944C031032C0CB5EBCC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
