VALUES ('doc-09-mitre-attack-p0-7139', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-12T17:50:31.750Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit access to the root account and prevent users from creating and/or modifying systemd timer unit files. ", "id": "relationship--e8001e2b-a639-458e-98f1-816a58830562", "modified": "2026-04-29T14:23:06.241Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--a542bac9-7bc1-4da7-9a09-96f69e23cc21", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7139', 0, 47, '09-mitre-attack', 'retrieved', 'A7FE68F0B2F6E63A507A2B3AAD42D3DE60C7EDA8535B27D11F517F12C5AAFE38', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
