VALUES ('doc-09-mitre-attack-p0-7140', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-28T14:05:17.983Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Limit the number of accounts with permissions to create other accounts. Do not allow domain administrator accounts to be used for day-to-day operations that may expose them to potential adversaries on unprivileged systems.", "id": "relationship--eb0c4e7c-a412-43ca-b135-e7b78060bda5", "modified": "2026-04-29T14:23:06.245Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--7610cada-1499-41a4-b3dd-46467b68d177", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7140', 0, 62, '09-mitre-attack', 'retrieved', '0BA427755A0D6203C7C2138B3B768D9435654074DBA0C0EF4A3C75B67D1821E8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
