VALUES ('doc-09-mitre-attack-p0-7142', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-20T19:26:05.831Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of Authentication, Authorization, and Accounting (AAA) systems will limit actions administrators can perform and provide a history of user actions to detect unauthorized use and abuse. TACACS+ can keep control over which commands administrators are permitted to use through the configuration of authentication and command authorization(Citation: Cisco IOS Software Integrity Assurance - AAA) (Citation: Cisco IOS Software Integrity Assurance - TACACS)", "external_references": [{"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - AAA. Retrieved October 19, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - AAA", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#38"}, {"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - TACACS. Retrieved October 19, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - TACACS", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#39"}], "id": "relationship--edbdc10d-a3d6-46f8-9354-ba06995dce08", "modified": "2026-04-29T14:23:06.249Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--818302b2-d640-477b-bf88-873120ce85c4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7142', 0, 140, '09-mitre-attack', 'retrieved', '8C9F0060D8E7ECFB96F6A7BFAFC736DFFF3F59E3D911B4FA083E36F0A2F8AE96', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
