VALUES ('doc-09-mitre-attack-p0-7143', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T14:43:54.309Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Restrict execution of Msiexec.exe to privileged accounts or groups that need to use it to lessen the opportunities for malicious usage.", "id": "relationship--f3b4fdd4-24fa-48ed-8ffb-f80ad651c797", "modified": "2026-04-29T14:23:06.256Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--365be77f-fc0e-42ee-bac8-4faf806d9336", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7143', 0, 50, '09-mitre-attack', 'retrieved', '02D6DCE987B9002CE5B7C04848309A18D4963A76D385A3399CFED6C288D0E447', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
