VALUES ('doc-09-mitre-attack-p0-7144', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-15T16:29:18.373Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Do not allow administrator accounts that have permissions to add component software on these services to be used for day-to-day operations that may expose them to potential adversaries on unprivileged systems.", "id": "relationship--f470dae2-81c9-48c4-aeab-27cebe318a09", "modified": "2026-04-29T14:23:06.257Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--9bb9e696-bff8-4ae1-9454-961fc7d91d5f", "spec_version": "2.1", "target_ref": "attack-pattern--d456de47-a16f-4e46-8980-e67478a12dcb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7144', 0, 60, '09-mitre-attack', 'retrieved', '088A0BD076CD102C7854CE69D53669E02AE5786F827AE3C68E6507C593F168F9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
