VALUES ('doc-09-mitre-attack-p0-7196', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-25T16:13:58.088Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Harden access requirements for Wi-Fi networks through using two or more pieces of evidence to authenticate, such as a username and password in addition to a token from a physical smart card or token generator.", "id": "relationship--1f110a49-63e2-4b73-b109-59694b419072", "modified": "2026-04-29T14:23:05.947Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--fde016f6-211a-41c8-a4ab-301f1e419c62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7196', 0, 64, '09-mitre-attack', 'retrieved', '3A4A353F7AF48FBBB011DCD4E643B781FA0631E4D7D18F32473E2A12F3CB00C0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
