VALUES ('doc-09-mitre-attack-p0-7197', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-26T04:01:09.881Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Integrating multi-factor authentication (MFA) as part of organizational policy can greatly reduce the risk of an adversary gaining control of valid credentials that may be used for additional tactics such as initial access, lateral movement, and collecting information.", "id": "relationship--22501b39-e106-4a7f-b915-013c30f47af8", "modified": "2026-04-29T14:23:05.952Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--06c00069-771a-4d57-8ef5-d3718c1a8771", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7197', 0, 67, '09-mitre-attack', 'retrieved', '9E346E0339BBBD6C58BE2EE38FBAD3DDCCE06F61466F43F058C85794E3852B0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
