VALUES ('doc-09-mitre-attack-p0-7198', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-16T14:49:02.709Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Integrating multi-factor authentication (MFA) as part of organizational policy can greatly reduce the risk of an adversary gaining control of valid credentials that may be used for additional tactics such as initial access, lateral movement, and collecting information. MFA can also be used to restrict access to cloud resources and APIs. ", "id": "relationship--2686dfb7-60ab-424c-add2-2f164a98cfa4", "modified": "2026-04-29T14:23:05.957Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--f4c1826f-a322-41cd-9557-562100848c84", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7198', 0, 81, '09-mitre-attack', 'retrieved', '0F78201E6DAA510BCE335208F025CE9B91242A206469487E4DAFA035E0C26709', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
