VALUES ('doc-09-mitre-attack-p0-7199', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-01T16:27:47.305Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use two or more pieces of evidence to authenticate to a system; such as username and password in addition to a token from a physical smart card or token generator.", "id": "relationship--2bd8bb5f-6210-4460-84c4-b7fab86e08a2", "modified": "2026-04-29T14:23:05.964Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--d28ef391-8ed4-45dc-bc4a-2f43abf54416", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7199', 0, 59, '09-mitre-attack', 'retrieved', '16346DE552336373E772B4A5420412DCE6C956ECC5FAF3B2AC97A6E70188EE32', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
