VALUES ('doc-09-mitre-attack-p0-7200', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T16:08:30.018Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use multi-factor authentication for user and privileged accounts. Most embedded network devices support TACACS+ and/or RADIUS. Follow vendor prescribed best practices for hardening access control.(Citation: Cisco IOS Software Integrity Assurance - TACACS)", "external_references": [{"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - TACACS. Retrieved October 19, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - TACACS", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#39"}], "id": "relationship--3541e998-a3ac-42d7-8a66-f66da6f9162a", "modified": "2026-04-29T14:23:05.991Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--b8017880-4b1e-42de-ad10-ae7ac6705166", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7200', 0, 86, '09-mitre-attack', 'retrieved', '7068D2932111C81C448555191B50287995E206F2D99B01B31993E0FA1CDC746B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
