VALUES ('doc-09-mitre-attack-p0-7201', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T13:49:14.598Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of multi-factor authentication for public-facing webmail servers is a recommended best practice to minimize the usefulness of usernames and passwords to adversaries.", "id": "relationship--3709ccc2-2370-4dc9-92ac-792867bbdea4", "modified": "2026-04-29T14:23:05.995Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--1608f3e1-598a-42f4-a01a-2e252e81728f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7201', 0, 52, '09-mitre-attack', 'retrieved', '9919C25365E45053E129E8E4B990CFE24EB61A644182442150F3299AC5937E33', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
