VALUES ('doc-09-mitre-attack-p0-7202', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-01T02:15:49.902Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Implement more secure 2FA/MFA mechanisms in replacement of simple push or one-click 2FA/MFA options. For example, having users enter a one-time code provided by the login screen into the 2FA/MFA application or utilizing other out-of-band 2FA/MFA mechanisms (such as rotating code-based hardware tokens providing rotating codes that need an accompanying user pin) may be more secure. Furthermore, change default configurations and implement limits upon the maximum number of 2FA/MFA request prompts that can be sent to users in period of time.(Citation: MFA Fatigue Attacks - PortSwigger)", "external_references": [{"description": "Jessica Haworth. (2022, February 16). MFA fatigue attacks: Users tricked into allowing device access due to overload of push notifications. Retrieved March 31, 2022.", "source_name": "MFA Fatigue Attacks - PortSwigger", "url": "https://portswigger.net/daily-swig/mfa-fatigue-attacks-users-tricked-into-allowing-device-access-due-to-overload-of-push-notifications"}], "id": "relationship--3a907723-bc0a-4a35-a9fc-dd45ad7752a8", "modified": "2026-04-29T14:23:06.001Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--954a1639-f2d6-407d-aef3-4917622ca493", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7202', 0, 149, '09-mitre-attack', 'retrieved', 'F7CFE5EAD0CE90E4A197091A95CD2AF7A6BFE52B053641C175FFDAFBF29E0698', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
