INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7203', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-10-07T21:42:57.989Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Implement multi-factor authentication (MFA) for default accounts whenever possible to prevent unauthorized access, even if credentials for these accounts are compromised. MFA adds an additional layer of security that requires more than just a username and password, making it significantly harder for adversaries to exploit these accounts for initial access or lateral movement.", "id": "relationship--3e2212a9-9347-46ac-ae96-04e558973779", "modified": "2026-04-29T14:23:06.010Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--6151cbea-819b-455a-9fa6-99a1cc58797d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7203', 0, 82, '09-mitre-attack', 'retrieved', '35BC35AD0A7E65B21562122FB940762F5A62CE16AFB0B3ADB0D25C6DC289BCB7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
