VALUES ('doc-09-mitre-attack-p0-7210', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-20T17:21:04.881Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use multi-factor authentication. Where possible, also enable multi-factor authentication on externally facing services.", "id": "relationship--64201f56-d678-4ed2-b759-c78bf9e4d82a", "modified": "2026-04-29T14:23:06.061Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--692074ae-bb62-4a5e-a735-02cb6bde458c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7210', 0, 42, '09-mitre-attack', 'retrieved', '9C2EDBDC12CBE1FAE8BE42192FC297DAEF8D6F683BFBD9B8817A322A93BEB21D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
