VALUES ('doc-09-mitre-attack-p0-7211', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-04T13:26:34.212Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use multi-factor authentication for cloud accounts, especially privileged accounts. This can be implemented in a variety of forms (e.g. hardware, virtual, SMS), and can also be audited using administrative reporting features.(Citation: AWS - IAM Console Best Practices)", "external_references": [{"description": "Moncur, Rob. (2020, July 5). New Information in the AWS IAM Console Helps You Follow IAM Best Practices. Retrieved August 4, 2020.", "source_name": "AWS - IAM Console Best Practices", "url": "https://aws.amazon.com/blogs/security/newly-updated-features-in-the-aws-iam-console-help-you-adhere-to-iam-best-practices/"}], "id": "relationship--68ad793a-2678-4537-8480-8086fd4d757e", "modified": "2026-04-29T14:23:06.067Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--f232fa7a-025c-4d43-abc7-318e81a73d65", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7211', 0, 99, '09-mitre-attack', 'retrieved', '714475B1A850FB91BC01611C60DCCC4FC3B855E38ED3463DF9156B4D1F891B17', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
