VALUES ('doc-09-mitre-attack-p0-7215', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-12T15:05:04.394Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Require multi-factor authentication for SSH connections wherever possible, such as password protected SSH keys.", "id": "relationship--77c5bb7d-9584-4d57-850b-6349984181a8", "modified": "2026-04-29T14:23:06.089Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--2db31dcd-54da-405d-acef-b9129b816ed6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7215', 0, 43, '09-mitre-attack', 'retrieved', 'B461E77287975F069FB0AB2BBF39BCB5500EA89FC0043D2EE706FC9C5150859F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
