VALUES ('doc-09-mitre-attack-p0-7217', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T16:48:08.513Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use multi-factor authentication for user and privileged accounts. Most embedded network devices support TACACS+ and/or RADIUS. Follow vendor prescribed best practices for hardening access control. (Citation: Cisco IOS Software Integrity Assurance - TACACS)", "external_references": [{"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - TACACS. Retrieved October 19, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - TACACS", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#39"}], "id": "relationship--7b6a48c0-9bcc-47d2-976a-e7dbaa00f4bc", "modified": "2026-04-29T14:23:06.094Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--4ffc1794-ec3b-45be-9e52-42dbcb2af2de", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7217', 0, 87, '09-mitre-attack', 'retrieved', '617C7F1A9AB0BF429E3E6A0B8A066D39E5F5A192121715A7E1E1AB7326126148', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
