VALUES ('doc-09-mitre-attack-p0-7219', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-20T16:58:50.670Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use multi-factor authentication. Where possible, also enable multi-factor authentication on externally facing services.", "id": "relationship--7fad18cd-28b4-47b4-8b38-f8beaf1120ad", "modified": "2026-04-29T14:23:06.100Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--09c4c11e-4fa1-4f8c-8dad-3cf8e69ad119", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7219', 0, 42, '09-mitre-attack', 'retrieved', '24767DA258AC16155253CD1D820B2587854AC2FA80731F6020BB4840C60A4824', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
