VALUES ('doc-09-mitre-attack-p0-7220', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-19T18:52:25.295Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of multi-factor authentication for public-facing webmail servers is a recommended best practice to minimize the usefulness of usernames and passwords to adversaries.", "id": "relationship--854e11fd-f29e-4b7e-a3c2-f4c8c9ee302f", "modified": "2026-04-29T14:23:06.107Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--b4694861-542c-48ea-9eb1-10d356e7140a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7220', 0, 52, '09-mitre-attack', 'retrieved', '3A170E7E10143A4E9099710634F5F7C2FA35DB1E0351154440829CFE28E05A27', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
