VALUES ('doc-09-mitre-attack-p0-7222', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-12T14:37:27.517Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use multi-factor authentication for remote logins.(Citation: Berkley Secure)", "external_references": [{"description": "Berkeley Security, University of California. (n.d.). Securing Remote Desktop for System Administrators. Retrieved November 4, 2014.", "source_name": "Berkley Secure", "url": "https://security.berkeley.edu/node/94"}], "id": "relationship--96014091-aba9-4b8f-ac6a-6cdeb593cf30", "modified": "2026-04-29T14:23:06.130Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--eb062747-2193-45de-8fa2-e62549c37ddf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7222', 0, 60, '09-mitre-attack', 'retrieved', '379CB686CC27D5BB2169BF495F8D9E985FE49BC355B299F2A8581DB0B9B9D12B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
