VALUES ('doc-09-mitre-attack-p0-7224', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-14T17:17:07.003Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use multi-factor authentication for user and privileged accounts.", "id": "relationship--a3012b2b-b19c-46fc-944c-d04d9c4b897b", "modified": "2026-04-29T14:23:06.147Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--e01be9c5-e763-4caf-aeb7-000b416aef67", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7224', 0, 37, '09-mitre-attack', 'retrieved', 'B11F3498E8F8ED4EEA3A60401FE5F630FE6E22F2DBF994FDFDB6642B4ACF3DF9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
