INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7225', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-16T14:56:19.332Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Integrating multi-factor authentication (MFA) as part of organizational policy can greatly reduce the risk of an adversary gaining control of valid credentials that may be used for additional tactics such as initial access, lateral movement, and collecting information. MFA can also be used to restrict access to cloud resources and APIs. ", "id": "relationship--acd4512e-3ef7-4c33-9fc1-c3829efebe60", "modified": "2026-04-29T14:23:06.160Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--d4b96d2c-1032-4b22-9235-2b5b649d0605", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7225', 0, 81, '09-mitre-attack', 'retrieved', '655A20E84A08F53352D2001D886936F776DE5076475D630D4DCA61ED6E4FB43E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
