VALUES ('doc-09-mitre-attack-p0-7234', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-17T21:15:43.002Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use strong two-factor or multi-factor authentication for remote service accounts to mitigate an adversary''s ability to leverage stolen credentials, but be aware of [Multi-Factor Authentication Interception](https://attack.mitre.org/techniques/T1111) techniques for some two-factor authentication implementations.", "id": "relationship--e23d57b4-5bc4-4d06-9084-9c99464c4af8", "modified": "2026-04-29T14:23:06.233Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--10d51417-ee35-4589-b1ff-b6df1c334e8d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7234', 0, 61, '09-mitre-attack', 'retrieved', '0E8EA0060B7147110F49A903EAF0093C3865E6CFBCC801F1DE65790D473AE4F1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
