VALUES ('doc-09-mitre-attack-p0-7236', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-05-31T19:35:22.519Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that MFA and MFA policies and requirements are properly implemented for existing and deactivated or dormant accounts and devices. If possible, consider configuring MFA solutions to \"fail closed\" rather than grant access in case of serious errors.", "id": "relationship--eb985609-6a5f-4e44-9bae-bfbc1e93d978", "modified": "2026-04-29T14:23:06.246Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--b4409cd8-0da9-46e1-a401-a241afd4d1cc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7236', 0, 67, '09-mitre-attack', 'retrieved', '8ABAF8775B28DF38E09BEA5DF96C689EAD726840CAE9204104E1CD582CA81347', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
