VALUES ('doc-09-mitre-attack-p0-7239', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-08T15:36:57.305Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use multi-factor authentication for logons to code repositories.", "id": "relationship--f8878fab-91a9-49d2-b985-fefa10e22ade", "modified": "2026-04-29T14:23:06.263Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--cff94884-3b1c-4987-a70b-6d5643c621c3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7239', 0, 37, '09-mitre-attack', 'retrieved', '53B6DBC173BE9518806D8F8ED5E8F935CBEE12721F1DCE4D9EE6B23224F9AB0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
