INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7240', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T17:58:04.228Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use multi-factor authentication for user and privileged accounts. Most embedded network devices support TACACS+ and/or RADIUS. Follow vendor prescribed best practices for hardening access control. (Citation: Cisco IOS Software Integrity Assurance - TACACS)", "external_references": [{"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - TACACS. Retrieved October 19, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - TACACS", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#39"}], "id": "relationship--fa8d6c79-557f-44e1-a27b-55f87b2c8084", "modified": "2026-04-29T14:23:06.265Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b045d015-6bed-4490-bd38-56b41ece59a0", "spec_version": "2.1", "target_ref": "attack-pattern--fa44a152-ac48-441e-a524-dd7b04b8adcd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7240', 0, 87, '09-mitre-attack', 'retrieved', '4AFEB8EFFA5E8DC8759E86B63ECA5806DAA7B0310B7C886BB6805C26E1745C1B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
