VALUES ('doc-09-mitre-attack-p0-7242', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-25T12:51:12.413Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that endpoint defenses run in safe mode.(Citation: CyberArk Labs Safe Mode 2016)", "external_references": [{"description": "Naim, D.. (2016, September 15). CyberArk Labs: From Safe Mode to Domain Compromise. Retrieved June 23, 2021.", "source_name": "CyberArk Labs Safe Mode 2016", "url": "https://www.cyberark.com/resources/blog/cyberark-labs-from-safe-mode-to-domain-compromise"}], "id": "relationship--07969240-a4ee-44e7-a9ee-b3386c6222cd", "modified": "2026-04-29T14:23:05.914Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b5dbb4c5-b0b1-40b1-80b6-e9e84ab90067", "spec_version": "2.1", "target_ref": "attack-pattern--c7660f19-f8c5-4ae3-a5e5-24381c270376", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7242', 0, 69, '09-mitre-attack', 'retrieved', 'FA74953B9E36EE1C94155EA4EA7DB653B7C515EC31077BB167884B9FA0BFDC34', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
