VALUES ('doc-09-mitre-attack-p0-7243', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T17:48:49.736Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure browsers or tasks to regularly delete persistent cookies.", "id": "relationship--10017b2e-7234-4368-81d7-a4c8b98c26a0", "modified": "2026-04-29T14:23:05.925Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b5dbb4c5-b0b1-40b1-80b6-e9e84ab90067", "spec_version": "2.1", "target_ref": "attack-pattern--c3c8c916-2f3c-4e71-94b2-240bdfc996f0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7243', 0, 38, '09-mitre-attack', 'retrieved', 'B6408953CAC379F929C45E8C65E7EA2F23E2AA4BC9F06A29FA5669B6FB818E8F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
