VALUES ('doc-09-mitre-attack-p0-7244', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T23:54:29.923Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Allowlist MIB objects and implement SNMP views.(Citation: Cisco Securing SNMP)", "external_references": [{"description": "Cisco. (2006, May 10). Securing Simple Network Management Protocol. Retrieved October 19, 2020.", "source_name": "Cisco Securing SNMP", "url": "https://www.cisco.com/c/en/us/support/docs/ip/simple-network-management-protocol-snmp/20370-snmpsecurity-20370.html"}], "id": "relationship--1cd3a9af-420f-45b6-a8b1-246332b1c49d", "modified": "2026-04-29T14:23:05.944Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b5dbb4c5-b0b1-40b1-80b6-e9e84ab90067", "spec_version": "2.1", "target_ref": "attack-pattern--ee7ff928-801c-4f34-8a99-3df965e581a5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7244', 0, 60, '09-mitre-attack', 'retrieved', '59875512FE58246D86E74401A770674C96ADF98858CB3A83A86FD2C8804EBA76', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
