INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7246', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-21T21:05:33.148Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "HTTP Public Key Pinning (HPKP) is one method to mitigate potential [Adversary-in-the-Middle](https://attack.mitre.org/techniques/T1557) situations where and adversary uses a mis-issued or fraudulent certificate to intercept encrypted communications by enforcing use of an expected certificate. (Citation: Wikipedia HPKP)", "external_references": [{"description": "Wikipedia. (2017, February 28). HTTP Public Key Pinning. Retrieved March 31, 2017.", "source_name": "Wikipedia HPKP", "url": "https://en.wikipedia.org/wiki/HTTP_Public_Key_Pinning"}], "id": "relationship--2981e224-edec-454e-91da-5dcad30572c1", "modified": "2026-04-29T14:23:05.961Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b5dbb4c5-b0b1-40b1-80b6-e9e84ab90067", "spec_version": "2.1", "target_ref": "attack-pattern--c615231b-f253-4f58-9d47-d5b4cbdb6839", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7246', 0, 84, '09-mitre-attack', 'retrieved', '9BB1B30F6A73F8F7CAAB10534BB3057961EE88005FC9126CCA70351C246D97D7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
