VALUES ('doc-09-mitre-attack-p0-7249', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-25T14:19:35.257Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "In Azure environments, consider setting a policy to block subscription transfers.(Citation: Azure Subscription Policies) In AWS environments, consider using Service Control Policies to prevent the use of the `LeaveOrganization` API call.(Citation: AWS RE:Inforce Threat Detection 2024)", "external_references": [{"description": "Ben Fletcher and Steve de Vera. (2024, June). New tactics and techniques for proactive threat detection. Retrieved September 25, 2024.", "source_name": "AWS RE:Inforce Threat Detection 2024", "url": "https://reinforce.awsevents.com/content/dam/reinforce/2024/slides/TDR432_New-tactics-and-techniques-for-proactive-threat-detection.pdf"}, {"description": "Microsoft Azure. (2024, March 21). Manage Azure subscription policies. Retrieved September 25, 2024.", "source_name": "Azure Subscription Policies", "url": "https://learn.microsoft.com/en-us/azure/cost-management-billing/manage/manage-azure-subscription-policy"}], "id": "relationship--3dd8c9cd-e9ad-4f3e-a4a6-0d4ff0904980", "modified": "2026-04-29T14:23:06.009Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b5dbb4c5-b0b1-40b1-80b6-e9e84ab90067", "spec_version": "2.1", "target_ref": "attack-pattern--0ce73446-8722-4086-9d43-514f1d0f669e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7249', 0, 115, '09-mitre-attack', 'retrieved', 'D91E360277ACCDCA16F1ED61CAA9D8B341C57AB30EBB760BB87EC0BBDDDC3228', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DA