VALUES ('doc-09-mitre-attack-p0-7254', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-03T21:55:40.603Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use anti-spoofing and email authentication mechanisms to filter messages based on validity checks of the sender domain (using SPF) and integrity of messages (using DKIM). Enabling these mechanisms within an organization (through policies such as DMARC) may enable recipients (intra-org and cross domain) to perform similar message filtering and validation.(Citation: Microsoft Anti Spoofing)(Citation: ACSC Email Spoofing)", "external_references": [{"description": "Australian Cyber Security Centre. (2012, December). Mitigating Spoofed Emails Using Sender Policy Framework. Retrieved November 17, 2024.", "source_name": "ACSC Email Spoofing", "url": "https://web.archive.org/web/20210708014107/https://www.cyber.gov.au/sites/default/files/2019-03/spoof_email_sender_policy_framework.pdf"}, {"description": "Microsoft. (2020, October 13). Anti-spoofing protection in EOP. Retrieved October 19, 2020.", "source_name": "Microsoft Anti Spoofing", "url": "https://docs.microsoft.com/en-us/microsoft-365/security/office-365-security/anti-spoofing-protection?view=o365-worldwide"}], "id": "relationship--727520dd-a7ee-4665-a610-201f0d5e2f0e", "modified": "2026-04-29T14:23:06.082Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b5dbb4c5-b0b1-40b1-80b6-e9e84ab90067", "spec_version": "2.1", "target_ref": "attack-pattern--cca0ccb6-a068-4574-a722-b1556f86833a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7254', 0, 129, '09-mitre-attack', 'retrieved', '0B0C15C82CA37C612E628EFE0822FF2F6DB03CBEFD3C773ABB79C18FC1D07700',