VALUES ('doc-09-mitre-attack-p0-7256', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-04T21:14:19.449Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure appropriate data sharing restrictions in cloud services. For example, external sharing in Microsoft SharePoint and Google Drive can be turned off altogether, blocked for certain domains, or restricted to certain users.(Citation: Google Workspace External Sharing) (Citation: Microsoft 365 External Sharing)", "external_references": [{"description": "Google. (n.d.). Manage external sharing for your organization. Retrieved March 4, 2024.", "source_name": "Google Workspace External Sharing", "url": "https://support.google.com/a/answer/60781"}, {"description": "Microsoft. (2023, October 11). Manage sharing settings for SharePoint and OneDrive in Microsoft 365. Retrieved March 4, 2024.", "source_name": "Microsoft 365 External Sharing", "url": "https://learn.microsoft.com/en-us/sharepoint/turn-external-sharing-on-or-off"}], "id": "relationship--8389c9f5-ace5-4240-a694-7008313fc168", "modified": "2026-04-29T14:23:06.105Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b5dbb4c5-b0b1-40b1-80b6-e9e84ab90067", "spec_version": "2.1", "target_ref": "attack-pattern--d4bdbdea-eaec-4071-b4f9-5105e12ea4b6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7256', 0, 117, '09-mitre-attack', 'retrieved', '15E917581E27D2AC3992962A49339D29DEE35736360B5124E4C1BFC3CC333CF0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
