VALUES ('doc-09-mitre-attack-p0-7257', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-05-22T20:02:07.140Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Where possible, avoid allowing pipelines to run unreviewed code. Where this is necessary, ensure that these pipelines are executed on isolated nodes without access to secrets. In GitHub, avoid using the `pull_request_target` trigger if possible, do not treat user-controlled inputs (such as branch names) as trusted, and do not use self-hosted runners on public repositories. ", "id": "relationship--851a8d0f-dabb-4e78-93bd-6f8aa6893c5d", "modified": "2026-04-29T14:23:06.107Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b5dbb4c5-b0b1-40b1-80b6-e9e84ab90067", "spec_version": "2.1", "target_ref": "attack-pattern--7655ac3b-dfde-49c5-a967-242856174434", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7257', 0, 85, '09-mitre-attack', 'retrieved', '0503D0CF4173B10FFA4ED7AF28D1FDFFFAC4D8624739B2B684D810448234B64A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
