VALUES ('doc-09-mitre-attack-p0-7261', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-05-24T16:54:02.415Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider implementing policies on internal web servers, such HTTP Strict Transport Security, that enforce the use of HTTPS/network traffic encryption to prevent insecure connections.(Citation: Chromium HSTS)", "external_references": [{"description": "Chromium. (n.d.). HTTP Strict Transport Security. Retrieved May 24, 2023.", "source_name": "Chromium HSTS", "url": "https://www.chromium.org/hsts/"}], "id": "relationship--8940b29f-23b8-4b13-b529-5bc56b1f7552", "modified": "2026-04-29T14:23:06.112Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b5dbb4c5-b0b1-40b1-80b6-e9e84ab90067", "spec_version": "2.1", "target_ref": "attack-pattern--30904c16-39f9-41c6-b01a-500eb8878442", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7261', 0, 72, '09-mitre-attack', 'retrieved', '06D307E33ABFB7EFB10919F606B63A019442FD08A404F1F61A3F08B8222E889E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
