VALUES ('doc-09-mitre-attack-p0-7264', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-09T13:17:39.397Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider disabling embedded files in Office programs, such as OneNote, that do not work with Protected View.(Citation: Enigma Reviving DDE Jan 2018)(Citation: GitHub Disable DDEAUTO Oct 2017)", "external_references": [{"description": "Nelson, M. (2018, January 29). Reviving DDE: Using OneNote and Excel for Code Execution. Retrieved February 3, 2018.", "source_name": "Enigma Reviving DDE Jan 2018", "url": "https://posts.specterops.io/reviving-dde-using-onenote-and-excel-for-code-execution-d7226864caee"}, {"description": "Dormann, W. (2017, October 20). Disable DDEAUTO for Outlook, Word, OneNote, and Excel versions 2010, 2013, 2016. Retrieved February 3, 2018.", "source_name": "GitHub Disable DDEAUTO Oct 2017", "url": "https://gist.github.com/wdormann/732bb88d9b5dd5a66c9f1e1498f31a1b"}], "id": "relationship--9912d67b-153f-428e-9751-e6c09c8de945", "modified": "2026-04-29T14:23:06.134Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b5dbb4c5-b0b1-40b1-80b6-e9e84ab90067", "spec_version": "2.1", "target_ref": "attack-pattern--232a7e42-cd6e-4902-8fe9-2960f529dd4d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7264', 0, 114, '09-mitre-attack', 'retrieved', 'D1C22BA518E324625B49E2F84182AEFD953D29EB8ADA19692243EDB0C06D4EE9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
