VALUES ('doc-09-mitre-attack-p0-7270', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-17T02:27:05.197Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Configure browsers/applications to regularly delete persistent web credentials (such as cookies).", "id": "relationship--ce647878-e4d9-4472-9777-b731edbd3d9a", "modified": "2026-04-29T14:23:06.207Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b5dbb4c5-b0b1-40b1-80b6-e9e84ab90067", "spec_version": "2.1", "target_ref": "attack-pattern--94cb00a4-b295-4d06-aa2b-5653b9c1be9c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7270', 0, 40, '09-mitre-attack', 'retrieved', 'FD35B1E56044AF2D3E96D5F07B2D64E560B3665793DEEF7589CDB87D3510331E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
