VALUES ('doc-09-mitre-attack-p0-7271', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-27T13:32:37.823Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "HTTP Public Key Pinning (HPKP) is one method to mitigate potential [Adversary-in-the-Middle](https://attack.mitre.org/techniques/T1557) situations where and adversary uses a mis-issued or fraudulent certificate to intercept encrypted communications by enforcing use of an expected certificate. (Citation: Wikipedia HPKP)", "external_references": [{"description": "Wikipedia. (2017, February 28). HTTP Public Key Pinning. Retrieved March 31, 2017.", "source_name": "Wikipedia HPKP", "url": "https://en.wikipedia.org/wiki/HTTP_Public_Key_Pinning"}], "id": "relationship--d9c08e10-909d-46d0-aa15-b99d1487be62", "modified": "2026-04-29T14:23:06.222Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b5dbb4c5-b0b1-40b1-80b6-e9e84ab90067", "spec_version": "2.1", "target_ref": "attack-pattern--b83e166d-13d7-4b52-8677-dff90c548fd7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7271', 0, 84, '09-mitre-attack', 'retrieved', 'FD94D34658E6EF94CC4AA2B057A15B972D960EDCCA300EEE6193E8C663A8EF62', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
