VALUES ('doc-09-mitre-attack-p0-7277', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-24T13:44:34.840Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Application isolation will limit what other processes and system features the exploited target can access.", "id": "relationship--0c8fdb59-a28f-4f8f-a788-9e3e8928c6d5", "modified": "2026-04-29T14:23:05.920Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b9f0c069-abbe-4a07-a245-2481219a1463", "spec_version": "2.1", "target_ref": "attack-pattern--3f886f2a-874f-4333-b794-aa6075009b1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7277', 0, 44, '09-mitre-attack', 'retrieved', 'F2F2BA2AFB28EDFCF7744EF11C4E1036CE5D2C296D364326F5C4842B8416F8A6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7278', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-07-14T14:01:41.417Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use Browser Extensions or Built-in Security Tools that:\n\n- Monitor JavaScript API calls such as `Blob`, `URL.createObjectURL,` and `msSaveOrOpenBlob`\n- Intercept and analyze HTML5 `download` attributes for suspicious payload generation\n- Alert or block behaviors that match known HTML smuggling patterns (e.g., blob-to-disk payload construction)\n\nApply Content Security Policy (CSP) headers to:\n\n- Restrict inline JavaScript and dynamic script generation\n- Disallow downloads from unauthorized sources or blob URIs\n- Prevent cross-origin resource sharing (CORS) abuse commonly used in smuggling chains\n\nEnable or enforce enterprise browser security controls, such as:\n\n- Endpoint''s Network Protection and Attack Surface Reduction (ASR) rules, which can block Office and browser processes from creating child processes or writing to disk in suspicious ways\n- Google Chrome Enterprise Policies, which can control file download behavior, restrict extensions, and isolate risky browsing environments\n\nDeploy browser sandboxing solutions that can isolate JavaScript execution environments and enforce behavioral policy restrictions", "id": "relationship--15e815c2-ab92-4490-b0ba-f94dddfe8b01", "modified": "2026-04-29T14:23:05.934Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b9f0c069-abbe-4a07-a245-2481219a1463", "spec_version": "2.1", "target_ref": "attack-pattern--d4dc46e3-5ba5-45b9-8204-010867cacfcb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7278', 0, 169, '09-mitre-attack', 'retrieved', '7B073E738917C9ED2E3B2676A403637B52C77FDE28F54191155E4CF3767043D4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7279', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-31T12:29:26.807Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider utilizing seccomp, seccomp-bpf, or a similar solution that restricts certain system calls such as mount. In Kubernetes environments, consider defining Pod Security Standards that limit container access to host process namespaces, the host network, and the host file system.(Citation: Kubernetes Hardening Guide)", "external_references": [{"description": "National Security Agency, Cybersecurity and Infrastructure Security Agency. (2022, March). Kubernetes Hardening Guide. Retrieved April 1, 2022.", "source_name": "Kubernetes Hardening Guide", "url": "https://media.defense.gov/2022/Aug/29/2003066362/-1/-1/0/CTR_KUBERNETES_HARDENING_GUIDANCE_1.2_20220829.PDF"}], "id": "relationship--3d5d727d-fa37-4de4-9d31-d8e497c910de", "modified": "2026-04-29T14:23:06.008Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--b9f0c069-abbe-4a07-a245-2481219a1463", "spec_version": "2.1", "target_ref": "attack-pattern--4a5b7ade-8bb5-4853-84ed-23f262002665", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7279', 0, 97, '09-mitre-attack', 'retrieved', '74EFDEFF082B36BC2E8A1F9C4EDEBC43FF6AB44CC815FA3C896B6D27D9DFD5A4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
