VALUES ('doc-09-mitre-attack-p0-7303', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-28T21:51:00.010Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identify and correct GPO permissions abuse opportunities (ex: GPO modification privileges) using auditing tools such as [BloodHound](https://attack.mitre.org/software/S0521) (version 1.5.1 and later).(Citation: GitHub Bloodhound)", "external_references": [{"description": "Robbins, A., Vazarkar, R., and Schroeder, W. (2016, April 17). Bloodhound: Six Degrees of Domain Admin. Retrieved March 5, 2019.", "source_name": "GitHub Bloodhound", "url": "https://github.com/BloodHoundAD/BloodHound"}], "id": "relationship--19e387c4-0dd8-4c00-9195-73ed25ad061e", "modified": "2026-04-29T14:23:05.940Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--5d2be8b9-d24c-4e98-83bf-2f5f79477163", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7303', 0, 79, '09-mitre-attack', 'retrieved', '508A0A419A343E0AEB7164F4DAFCFEC9873906DD7D60EBDA6F6E86F98142B65B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
