VALUES ('doc-09-mitre-attack-p0-7305', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-12-30T21:43:04.886Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Regularly check component software on critical services that adversaries may target for persistence to verify the integrity of the systems and identify if unexpected changes have been made. ", "id": "relationship--1c97ecdd-5195-4242-9007-380cc46ef384", "modified": "2026-04-29T14:23:05.944Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--f9e9365a-9ca2-4d9c-8e7c-050d73d1101a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7305', 0, 58, '09-mitre-attack', 'retrieved', 'BBD106BF886B589F366CF05BA0ACA13EE336A6443FED5B6203BE8282349E0524', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
