VALUES ('doc-09-mitre-attack-p0-7307', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-01-30T15:17:10.472Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Routinely check account role permissions to ensure only expected users and roles have permission to modify system firewalls.", "id": "relationship--2496b1fe-0a73-4918-82e6-7f2a07c44353", "modified": "2026-04-29T14:23:05.955Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--eec096b8-c207-43df-b6c1-11523861e452", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7307', 0, 47, '09-mitre-attack', 'retrieved', 'ED8605128063A7C5898C52FDF375BBEC1B9D42D0D4B712D6E363BA35A8005F07', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
