VALUES ('doc-09-mitre-attack-p0-7310', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-04T16:09:13.564Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider periodic review of auditpol settings for Administrator accounts and perform dynamic baselining on SIEM(s) to investigate potential malicious activity. Also ensure that the EventLog service and its threads are properly running.", "id": "relationship--31ca8630-4b0a-4e5f-a3eb-45c8ee8841ad", "modified": "2026-04-29T14:23:05.982Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--1411e6b8-80a6-4465-9909-54eaa9c67ce0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7310', 0, 61, '09-mitre-attack', 'retrieved', '2A90A3FFC4809CA7CB8508E71833C0AEF737367BC6DA21DC80118542BEC29A0F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
