VALUES ('doc-09-mitre-attack-p0-7312', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T14:24:35.600Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Check for common UAC bypass weaknesses on Windows systems to be aware of the risk posture and address issues where appropriate.(Citation: Github UACMe)", "external_references": [{"description": "UACME Project. (2016, June 16). UACMe. Retrieved July 26, 2016.", "source_name": "Github UACMe", "url": "https://github.com/hfiref0x/UACME"}], "id": "relationship--3bc57dac-c8b3-4d6d-8f4c-3e7d515cdf87", "modified": "2026-04-29T14:23:06.004Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--120d5519-3098-4e1c-9191-2aa61232f073", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7312', 0, 69, '09-mitre-attack', 'retrieved', '296AD7FE3505B3FC76666F22D85BB1744235D81952519BF2F4184E4284F64C52', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
