VALUES ('doc-09-mitre-attack-p0-7313', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-24T13:43:00.174Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Kerberos preauthentication is enabled by default. Older protocols might not support preauthentication therefore it is possible to have this setting disabled. Make sure that all accounts have preauthentication whenever possible and audit changes to setting. Windows tools such as PowerShell may be used to easily find which accounts have preauthentication disabled. (Citation: Microsoft Preauthentication Jul 2012)(Citation: Stealthbits Cracking AS-REP Roasting Jun 2019)", "external_references": [{"description": "Microsoft. (2012, July 18). Preauthentication. Retrieved August 24, 2020.", "source_name": "Microsoft Preauthentication Jul 2012", "url": "https://docs.microsoft.com/en-us/previous-versions/windows/it-pro/windows-2000-server/cc961961(v=technet.10)?redirectedfrom=MSDN"}, {"description": "Jeff Warren. (2019, June 27). Cracking Active Directory Passwords with AS-REP Roasting. Retrieved August 24, 2020.", "source_name": "Stealthbits Cracking AS-REP Roasting Jun 2019", "url": "https://blog.stealthbits.com/cracking-active-directory-passwords-with-as-rep-roasting/"}], "id": "relationship--3de2faf5-8019-4aad-a317-fb66554cd2c0", "modified": "2026-04-29T14:23:06.009Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--3986e7fd-a8e9-4ecb-bfc6-55920855912b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7313', 0, 135, '09-mitre-attack', 'retrieved', '2C83F881F6667A38E5539A838466FE95263762FF2BBB495C160F50C2CC9D8865', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
