VALUES ('doc-09-mitre-attack-p0-7314', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-24T17:45:16.440Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider periodic review of common fileless storage locations (such as the Registry or WMI repository) to potentially identify abnormal and malicious data.", "id": "relationship--3de96229-d45b-47b2-9515-4eadd0023115", "modified": "2026-04-29T14:23:06.009Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--02c5abff-30bf-4703-ab92-1f6072fae939", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7314', 0, 51, '09-mitre-attack', 'retrieved', '0F35E6B96EE5C0B616212D393E59FDCFCF102DE4CF6E43EF1A747175FFC166C6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
