VALUES ('doc-09-mitre-attack-p0-7316', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-17T19:19:05.361Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use auditing tools capable of detecting privilege and service abuse opportunities on systems within an enterprise and correct them. ", "id": "relationship--40f51fdc-cd3c-4e93-9593-e1ee7cf2211e", "modified": "2026-04-29T14:23:06.013Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--2959d63f-73fd-46a1-abd2-109d7dcede32", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7316', 0, 49, '09-mitre-attack', 'retrieved', 'BA71CD79C622D8DC6B8C1A0CE262D98839218075905484912920FBBE358DEF17', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
