VALUES ('doc-09-mitre-attack-p0-7317', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-20T22:23:43.711Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Periodically review SaaS integrations for unapproved or potentially malicious applications. ", "id": "relationship--4797263a-01a0-4053-ae5c-54cf53217e97", "modified": "2026-04-29T14:23:06.023Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--c31aebd6-c9b5-420f-ba2a-5853bbf897fa", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7317', 0, 40, '09-mitre-attack', 'retrieved', 'A1A4BEBBC44E0524D2DE2A66C36A4E9FF47659D89B397C4E07F6752B262AA8EF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
