VALUES ('doc-09-mitre-attack-p0-7318', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-01T17:19:42.596Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Perform audits or scans of systems, permissions, insecure software, insecure configurations, etc. to identify potential weaknesses.", "id": "relationship--4aa81ed2-b2d8-490f-a0b4-e0d2e5772acc", "modified": "2026-04-29T14:23:06.027Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--51a14c76-dd3b-440b-9c20-2bf91d25a814", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7318', 0, 45, '09-mitre-attack', 'retrieved', 'E5ABA9A340676507F9F4F26D065E827E7820713FDC41D4D77726997EF89ED8C0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
