VALUES ('doc-09-mitre-attack-p0-7319', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-17T21:26:44.446Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Search SYSVOL for any existing GGPs that may contain credentials and remove them.(Citation: ADSecurity Finding Passwords in SYSVOL)", "external_references": [{"description": "Sean Metcalf. (2015, December 28). Finding Passwords in SYSVOL & Exploiting Group Policy Preferences. Retrieved February 17, 2020.", "source_name": "ADSecurity Finding Passwords in SYSVOL", "url": "https://adsecurity.org/?p=2288"}], "id": "relationship--4abb5175-7caf-41c8-83a6-1ce459cf72df", "modified": "2026-04-29T14:23:06.027Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--8d7bd4f5-3a89-4453-9c82-2c8894d5655e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7319', 0, 75, '09-mitre-attack', 'retrieved', 'E55C826D81BB83BA42DA2BF4337D8A4CCC2AD17254475F14522D536DB163899C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
