VALUES ('doc-09-mitre-attack-p0-7323', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-17T02:28:43.309Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Administrators should perform an audit of all access lists and the permissions they have been granted to access web applications and services. This should be done extensively on all resources in order to establish a baseline, followed up on with periodic audits of new or updated resources. Suspicious accounts/credentials should be investigated and removed.", "id": "relationship--5208729f-fc13-477a-984b-1035c581ad02", "modified": "2026-04-29T14:23:06.037Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--861b8fd2-57f3-4ee1-ab5d-c19c3b8c7a4a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7323', 0, 83, '09-mitre-attack', 'retrieved', '07B0AFEBD2799852CF3A25B7F8A5D399F5E34A943577EFB8E4F92C94A1168F4A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
