VALUES ('doc-09-mitre-attack-p0-7331', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-31T14:50:47.611Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Periodically review for new and unknown network provider DLLs within the Registry (`HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Services\\ \\NetworkProvider\\ProviderPath`).\n\nEnsure only valid network provider DLLs are registered. The name of these can be found in the Registry key at `HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Control\\NetworkProvider\\Order`, and have corresponding service subkey pointing to a DLL at `HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentC ontrolSet\\Services\\ \\NetworkProvider`.", "id": "relationship--6b8bbbca-a50e-49fa-a851-f43a8c21f635", "modified": "2026-04-29T14:23:06.071Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--90c4a591-d02d-490b-92aa-619d9701ac04", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7331', 0, 76, '09-mitre-attack', 'retrieved', '22A6D9E180935C94A4D5B2532142C5C23DE3BFDADAD5D443E4A9A965BAE31CAC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
