VALUES ('doc-09-mitre-attack-p0-7337', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-17T15:02:16.319Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Preemptively search through communication services to find shared unsecured credentials. Searching for common patterns like \" password is \", “ password= ” and take actions to reduce exposure when found. ", "id": "relationship--7494c5ff-db1c-4bba-8ec0-8a6678b28900", "modified": "2026-04-29T14:23:06.085Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--9664ad0e-789e-40ac-82e2-d7b17fbe8fb3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7337', 0, 60, '09-mitre-attack', 'retrieved', '7733E4EF322E413610B25D2FC3097D5BD3FE5D7E538A75BF67BB758D00C8D76B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
