VALUES ('doc-09-mitre-attack-p0-7343', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-12-17T15:24:12.407Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enable advanced auditing on AD FS. Check the success and failure audit options in the AD FS Management snap-in. Enable Audit Application Generated events on the AD FS farm via Group Policy Object.(Citation: FireEye ADFS)", "external_references": [{"description": "Bierstock, D., Baker, A. (2019, March 21). I am AD FS and So Can You. Retrieved December 17, 2020.", "source_name": "FireEye ADFS", "url": "https://www.troopers.de/troopers19/agenda/fpxwmn/"}], "id": "relationship--8a716922-181e-409c-b112-851e7f172d7c", "modified": "2026-04-29T14:23:06.114Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--1f9c2bae-b441-4f66-a8af-b65946ee72f2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7343', 0, 90, '09-mitre-attack', 'retrieved', '8426D3A4AE16F07BC09F6399E05C5AEECAD50B4E15424BCB00B08AD21DD662E5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
