VALUES ('doc-09-mitre-attack-p0-7344', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-31T13:19:08.157Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Periodically investigate ESXi hosts for open VMCI ports. Running the `lsof -A` command and inspecting results with a type of `SOCKET_VMCI` will reveal processes that have open VMCI ports.(Citation: Google Cloud Threat Intelligence ESXi Hardening 2023)", "external_references": [{"description": "Alex Marvi, Greg Blaum, and Ron Craft. (2023, June 28). Detection, Containment, and Hardening Opportunities for Privileged Guest Operations, Anomalous Behavior, and VMCI Backdoors on Compromised VMware Hosts. Retrieved March 26, 2025.", "source_name": "Google Cloud Threat Intelligence ESXi Hardening 2023", "url": "https://cloud.google.com/blog/topics/threat-intelligence/vmware-detection-containment-hardening"}], "id": "relationship--8ad2d1c5-aa94-4c32-94c8-8ffb9d11f54a", "modified": "2026-04-29T14:23:06.114Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--c21d5a77-d422-4a69-acd7-2c53c1faa34b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7344', 0, 109, '09-mitre-attack', 'retrieved', '2E62DF50ABB8F6FBCF27F0817E69E2D251FCA67FE732AFF445DD93EA32539D8A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
