VALUES ('doc-09-mitre-attack-p0-7345', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-11T13:13:12.320Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Routinely check user permissions to ensure only the expected users have the ability to list IAM identities or otherwise discover cloud accounts.", "id": "relationship--8b9e5b99-2df6-47b4-9c97-9bf8dd01821d", "modified": "2026-04-29T14:23:06.116Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--8f104855-e5b7-4077-b1f5-bc3103b41abe", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7345', 0, 51, '09-mitre-attack', 'retrieved', '55146D5DF1D1CFE4F05BEF3692D9B1FEF623964729625DB34DE5B91DB445420E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
