VALUES ('doc-09-mitre-attack-p0-7346', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-05-31T19:34:41.217Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Review MFA actions alongside authentication logs to ensure that MFA-based logins are functioning as intended. Review user accounts to ensure that all accounts have MFA enabled.(Citation: Mandiant Cloudy Logs 2023)", "external_references": [{"description": "Pany, D. & Hanley, C. (2023, May 3). Cloudy with a Chance of Bad Logs: Cloud Platform Log Configurations to Consider in Investigations. Retrieved October 16, 2023.", "source_name": "Mandiant Cloudy Logs 2023", "url": "https://www.mandiant.com/resources/blog/cloud-bad-log-configurations"}], "id": "relationship--90d0d818-4a80-459c-9d57-ca9221eae57b", "modified": "2026-04-29T14:23:06.122Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--b4409cd8-0da9-46e1-a401-a241afd4d1cc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7346', 0, 95, '09-mitre-attack', 'retrieved', 'DA9DE82C3767AE8C1E62A7AA30E3FAE25FA4812523426F70B1A91C6364F1D482', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
