VALUES ('doc-09-mitre-attack-p0-7350', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-22T20:23:25.260Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Review and limit the fingerprinting surface to only necessary information on each browser to make the browser less unique. For example, the available fonts may be limited to a standard font list. (Citation: W3C)", "external_references": [{"description": "W3C. (2025, September 12). Mitigating Browser Fingerprinting in Web Specifications. Retrieved September 22, 2025.", "source_name": "W3C", "url": "https://www.w3.org/TR/fingerprinting-guidance/"}], "id": "relationship--964b451b-103a-4bef-9a1f-a2078cd81cf9", "modified": "2026-04-29T14:23:06.130Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--afac5dbc-4383-4fb6-9ba6-45b25d49e530", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7350', 0, 83, '09-mitre-attack', 'retrieved', '5AC971101C13043D4DCEFFDC9871081FDF0300E573D53A48F883265865262227', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
