VALUES ('doc-09-mitre-attack-p0-7351', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-05-11T18:51:16.441Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider periodic reviews of accounts and privileges for critical and sensitive code repositories. Scan code repositories for exposed credentials or other sensitive information.", "id": "relationship--99e7e929-1e72-4d9a-8997-15f977f36218", "modified": "2026-04-29T14:23:06.135Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--cff94884-3b1c-4987-a70b-6d5643c621c3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7351', 0, 52, '09-mitre-attack', 'retrieved', 'EDD527AE0C4D44DC16740E69AEA51D48AE2477123A44FA19B450B0693EA11E48', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
