VALUES ('doc-09-mitre-attack-p0-7352', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-30T03:17:36.492Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Routinely check account role permissions to ensure only expected users and roles have permission to modify logging settings.\n\nTo ensure Audit rules can not be modified at runtime, add the `auditctl -e 2` as the last command in the audit.rules files. Once started, any attempt to change the configuration in this mode will be audited and denied. The configuration can only be changed by rebooting the machine.", "id": "relationship--9a063196-5031-426a-a75a-ec7a2b479951", "modified": "2026-04-29T14:23:06.135Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--23d69d00-80c4-42ff-9dac-dbd0459dad75", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7352', 0, 95, '09-mitre-attack', 'retrieved', 'A6AB1FA066954CC1C931A606E03CE1901C46D91C23BAA80537CE45A458CE01A8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
