VALUES ('doc-09-mitre-attack-p0-7353', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-05T14:20:22.008Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Routinely monitor user permissions to ensure only the expected users have the capability to request quota adjustments or modify tenant-level compute settings.", "id": "relationship--9a99712e-ea3c-47f7-a2f6-6109b9d0d4c3", "modified": "2026-04-29T14:23:06.136Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--ca00366b-83a1-4c7b-a0ce-8ff950a7c87f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7353', 0, 51, '09-mitre-attack', 'retrieved', '25CACD0D7CFA608314E6F46F6F9B4022F7ADD1B33E30CE416F5AF0148004A973', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
