VALUES ('doc-09-mitre-attack-p0-7354', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-10-07T22:01:12.484Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Implement auditing and logging for interactions with third-party messaging services or collaboration platforms. Monitor user activity and review logs for signs of suspicious links, downloads, or file exchanges that could indicate spearphishing attempts. Effective auditing allows for the quick identification of malicious activity originating from compromised service accounts.", "id": "relationship--9b91755d-2b83-438c-bd25-0e71c540310a", "modified": "2026-04-29T14:23:06.137Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--f6ad61ee-65f3-4bd0-a3f5-2f0accb36317", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7354', 0, 77, '09-mitre-attack', 'retrieved', '2A09AD69C29FEB823579F32CD3AFE550FF98CDE18167F0CA47B6F0EA54C14E62', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
