VALUES ('doc-09-mitre-attack-p0-7355', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-04T12:58:40.980Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Proactively search for credentials within the Registry and attempt to remediate the risk.", "id": "relationship--9c4bd197-08a2-4ded-baba-bd70b6b4afd0", "modified": "2026-04-29T14:23:06.138Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--341e222a-a6e3-4f6f-b69c-831d792b1580", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7355', 0, 42, '09-mitre-attack', 'retrieved', '41046E13F031153B17350F33538435C881FA4D9A3863E2DD2818E146640F4FAC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
