VALUES ('doc-09-mitre-attack-p0-7360', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-17T18:49:50.127Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Regularly check installed IIS components to verify the integrity of the web server and identify if unexpected changes have been made.", "id": "relationship--9f93da44-6aa1-4f59-95c7-89c849423da9", "modified": "2026-04-29T14:23:06.142Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--b46a801b-fd98-491c-a25a-bca25d6e3001", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7360', 0, 50, '09-mitre-attack', 'retrieved', 'A4F05B7B25DCD6FA56CAA1A4047EFE7ACA53AC3983F4E7746A942208FF5DA8D8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
