VALUES ('doc-09-mitre-attack-p0-7361', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-30T22:38:01.883Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure extensions that are installed are the intended ones, as many malicious extensions may masquerade as legitimate ones. ", "id": "relationship--a22dffc4-ff73-4845-895a-ecd21e8549b2", "modified": "2026-04-29T14:23:06.146Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--389735f1-f21c-4208-b8f0-f8031e7169b8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7361', 0, 48, '09-mitre-attack', 'retrieved', '42A379C0433DD536DA7F5D26E1DEE0FFE8BCE3AFF7FE2BC315F5458A2D455FBE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
