VALUES ('doc-09-mitre-attack-p0-7362', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-01T20:06:37.867Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider periodic review of accounts and privileges for critical and sensitive CRM data.", "id": "relationship--a50651b9-581a-4c77-b383-679a9c42e2b5", "modified": "2026-04-29T14:23:06.149Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--bbfbb096-6561-4d7d-aa2c-a5ee8e44c696", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7362', 0, 42, '09-mitre-attack', 'retrieved', '0203E3C7648834535CBCBB6A8C77CB93224487486F69933D553D81C7334B5107', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
