VALUES ('doc-09-mitre-attack-p0-7364', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-04T13:42:40.685Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Preemptively search for files containing passwords or other credentials and take actions to reduce the exposure risk when found.", "id": "relationship--abe43d10-714a-4f29-b164-d7cadd83cb61", "modified": "2026-04-29T14:23:06.159Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--435dfb86-2697-4867-85b5-2fef496c0517", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7364', 0, 48, '09-mitre-attack', 'retrieved', '2BE2AD72E8112EC69BC59390D83D03A9DB7853E2A05C5A2FD70A6C9BC2B182FC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
