VALUES ('doc-09-mitre-attack-p0-7365', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-12T12:24:14.131Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Routinely check user permissions to ensure only the expected users have the capability to create new instances.", "id": "relationship--ac440832-cb04-409e-87fa-558097a898b6", "modified": "2026-04-29T14:23:06.159Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--cf1c2504-433f-4c4e-a1f8-91de45a0318c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7365', 0, 46, '09-mitre-attack', 'retrieved', 'B25CB0283C5C58A867ADC464735608AA2F76EE27EF94D70A837664DEE14F6ACB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
