INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7366', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-13T17:48:59.223Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Find and eliminate path interception weaknesses in program configuration files, scripts, the PATH environment variable, services, and in shortcuts by surrounding PATH variables with quotation marks when functions allow for them. Be aware of the search order Windows uses for executing or loading binaries and use fully qualified paths wherever appropriate.\n\nClean up old Windows Registry keys when software is uninstalled to avoid keys with no associated legitimate binaries. Periodically search for and correct or report path interception weaknesses on systems that may have been introduced using custom or available tools that report software using insecure path configurations.(Citation: Microsoft CreateProcess)(Citation: Microsoft Dynamic-Link Library Security)(Citation: Vulnerability and Exploit Detector)", "external_references": [{"description": "Kanthak, S.. (2016, July 20). Vulnerability and Exploit Detector. Retrieved February 3, 2017.", "source_name": "Vulnerability and Exploit Detector", "url": "https://skanthak.homepage.t-online.de/sentinel.html"}, {"description": "Microsoft. (n.d.). CreateProcess function. Retrieved September 12, 2024.", "source_name": "Microsoft CreateProcess", "url": "https://learn.microsoft.com/en-us/windows/win32/api/processthreadsapi/nf-processthreadsapi-createprocessa"}, {"description": "Microsoft. (n.d.). Dynamic-Link Library Security. Retrieved July 25, 2016.", "source_name": "Microsoft Dynamic-Link Library Security", "url": "https://docs.microsoft.com/en-us/windows/win32/dlls/dynamic-link-library-security?redirectedfrom=MSDN"}], "id": "relationship--ae13555e-3275-43c5-b388-59478160d01b", "modified": "2026-04-29T14:23:06.162Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--58af3705-8740-4c68-9329-ec015a7013c2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7366', 0, 189, '09-mitre-attack', 'retrieved', '4566F1524FD2D1A889FDF41871FB7CC6FC5A9F4C76587FBD5020D6263747CFB6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
