VALUES ('doc-09-mitre-attack-p0-7369', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-13T18:11:08.510Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use auditing tools capable of detecting DLL search order hijacking opportunities on systems within an enterprise and correct them. Toolkits like the PowerSploit framework contain PowerUp modules that can be used to explore systems for DLL hijacking weaknesses.(Citation: Powersploit)\n\nUse the program `sxstrace.exe` that is included with Windows, along with manual inspection, to check manifest files for side-by-side problems in software.(Citation: Microsoft Sxstrace)", "external_references": [{"description": "Gerend, J. et al.. (2017, October 16). sxstrace. Retrieved April 26, 2021.", "source_name": "Microsoft Sxstrace", "url": "https://docs.microsoft.com/windows-server/administration/windows-commands/sxstrace"}, {"description": "PowerSploit. (n.d.). Retrieved December 4, 2014.", "source_name": "Powersploit", "url": "https://github.com/mattifestation/PowerSploit"}], "id": "relationship--b673ba9b-3eb4-42fd-976d-62fc8d121cc3", "modified": "2026-04-29T14:23:06.174Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7369', 0, 121, '09-mitre-attack', 'retrieved', 'EB72BC6440B5635E174A5314084923198C14E3526BDA3D78B21440E208B31A11', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
