VALUES ('doc-09-mitre-attack-p0-7375', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-06-05T17:06:40.656Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Periodically inspect systems for abnormal and unexpected power settings that may indicate malicious activty.", "id": "relationship--c9ca3f00-925f-4bce-9aeb-df41fb9b5eb0", "modified": "2026-04-29T14:23:06.201Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--ea071aa0-8f17-416f-ab0d-2bab7e79003d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7375', 0, 43, '09-mitre-attack', 'retrieved', 'A0F03D98D2E71BAAB60748CA8BE77AA70F8EE3F9FEA920819E7EDA47A3904BC8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
