VALUES ('doc-09-mitre-attack-p0-7382', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-04T12:52:13.346Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Preemptively search for files containing passwords and take actions to reduce the exposure risk when found.", "id": "relationship--dac6c0a0-9eba-41b5-95c1-2f340d12b175", "modified": "2026-04-29T14:23:06.224Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--837f9164-50af-4ac0-8219-379d8a74cefc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7382', 0, 45, '09-mitre-attack', 'retrieved', '9503A24921FC046250BF93B12D23BD9EA056C6C25982F6174E0EA11434B9BCA2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
