VALUES ('doc-09-mitre-attack-p0-7383', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-21T21:23:26.792Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Routinely check applications using Automation under Security & Privacy System Preferences. To reset permissions, user''s can utilize the `tccutil reset` command. When using Mobile Device Management (MDM), review the list of enabled or disabled applications in the `MDMOverrides.plist` which overrides the TCC database.(Citation: TCC macOS bypass)", "external_references": [{"description": "Phil Stokes. (2021, July 1). Bypassing macOS TCC User Privacy Protections By Accident and Design. Retrieved March 21, 2024.", "source_name": "TCC macOS bypass", "url": "https://www.sentinelone.com/labs/bypassing-macos-tcc-user-privacy-protections-by-accident-and-design/"}], "id": "relationship--df3c6782-1a01-4627-9715-f2a10cf2c0d9", "modified": "2026-04-29T14:23:06.230Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--e8a0a025-3601-4755-abfb-8d08283329fb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7383', 0, 102, '09-mitre-attack', 'retrieved', '0B1F1F9361CC831929B22F5A94D2EE45EB3C66CC550D88895DF36FBD7FF97CB6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
