VALUES ('doc-09-mitre-attack-p0-7384', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-05T02:15:30.005Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Frequently check permissions on cloud storage to ensure proper permissions are set to deny open or unprivileged access to resources.(Citation: Amazon S3 Security, 2019)", "external_references": [{"description": "Amazon. (2019, May 17). How can I secure the files in my Amazon S3 bucket?. Retrieved October 4, 2019.", "source_name": "Amazon S3 Security, 2019", "url": "https://aws.amazon.com/premiumsupport/knowledge-center/secure-s3-resources/"}], "id": "relationship--e3e50d39-fa69-4fca-9353-259247dbd439", "modified": "2026-04-29T14:23:06.235Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--3298ce88-1628-43b1-87d9-0b5336b193d7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7384', 0, 81, '09-mitre-attack', 'retrieved', 'A20BDD143760A9E26CD93CAA10462DA4F3875D5629269052F81CF133750E8B89', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
