VALUES ('doc-09-mitre-attack-p0-7386', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-10-18T22:49:22.139Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Scan public code repositories for exposed credentials or other sensitive information before making commits. Ensure that any leaked credentials are removed from the commit history, not just the current latest version of the code.", "id": "relationship--e8ba13f3-b51a-4e7b-9534-7f9f8d362b0c", "modified": "2026-04-29T14:23:06.242Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--a0e6614a-7740-4b24-bd65-f1bde09fc365", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7386', 0, 63, '09-mitre-attack', 'retrieved', '253DF4C3425F48CFA5AC4251A6197DF12A9D7518EA790077E57EFC31D9C255EF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
