VALUES ('doc-09-mitre-attack-p0-7388', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-04T13:06:49.706Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure only authorized keys are allowed access to critical resources and audit access lists regularly.", "id": "relationship--ed609ca1-8646-4827-9d1a-aad365de95f6", "modified": "2026-04-29T14:23:06.248Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--60b508a1-6a5e-46b1-821a-9f7b78752abf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7388', 0, 44, '09-mitre-attack', 'retrieved', '8614A85465A997D4CE501285D519B397F3C574D309FA6FB81716E285735A5FB3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
