VALUES ('doc-09-mitre-attack-p0-7389', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-20T17:59:21.292Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Periodically check the integrity of the running configuration and system image to ensure they have not been modified. (Citation: Cisco IOS Software Integrity Assurance - Image File Verification) (Citation: Cisco IOS Software Integrity Assurance - Image File Integrity) (Citation: Cisco IOS Software Integrity Assurance - Change Control) ", "external_references": [{"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - Cisco IOS Image File Verification. Retrieved October 19, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - Image File Verification", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#7"}, {"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - Image File Integrity. Retrieved October 21, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - Image File Integrity", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#30"}, {"description": "Cisco. (n.d.). Cisco IOS Software Integrity Assurance - Change Control. Retrieved October 21, 2020.", "source_name": "Cisco IOS Software Integrity Assurance - Change Control", "url": "https://tools.cisco.com/security/center/resources/integrity_assurance.html#31"}], "id": "relationship--f0488c32-f937-4eb9-8068-092795872582", "modified": "2026-04-29T14:23:06.252Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--28abec6c-4443-4b03-8206-07f2e264a6b4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7389', 0, 162, '09-mitre-attack', 'retrieved', '8438AA66FA20413EFF1C8ABD542E90BEDD98C146447A263D057A0685B7BC6F50', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
