VALUES ('doc-09-mitre-attack-p0-7391', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-15T13:22:13.778Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Routinely check account role permissions to ensure only expected users and roles have permission to modify system firewalls.", "id": "relationship--f4f4909b-bf81-47d2-b57c-0a2187f5f4b7", "modified": "2026-04-29T14:23:06.258Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--291ede6c-1473-454c-b614-5ac5ea63c987", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7391', 0, 47, '09-mitre-attack', 'retrieved', '8340949873609292ED794AD6EC921D1799E2D04E82E01C05910073CA85E2B7DF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
