VALUES ('doc-09-mitre-attack-p0-7392', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-03T12:30:34.246Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Periodically check the integrity of images and containers used in cloud deployments to ensure they have not been modified to include malicious software.", "id": "relationship--f7a8b397-ecf3-456e-a395-568a41048609", "modified": "2026-04-29T14:23:06.262Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--4fd8a28b-4b3a-4cd6-a8cf-85ba5f824a7f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7392', 0, 52, '09-mitre-attack', 'retrieved', 'B7426E318D35FAD7B9A80E956E3F58F2503C315ACB8C5E16C83D47FD66CDF2DF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
