VALUES ('doc-09-mitre-attack-p0-7393', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-05-22T19:03:13.064Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider periodic review of accounts and privileges for critical and sensitive databases. ", "id": "relationship--f7b16a14-f75d-48ae-bd3d-a64983e67581", "modified": "2026-04-29T14:23:06.262Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--248d3fe1-7fe1-4d71-91c7-8bb7ef35cad3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7393', 0, 42, '09-mitre-attack', 'retrieved', 'E1F10D9417DABBF985D543D944C4E02289EC160ABE4BD1EF0E57138F089F577D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
