VALUES ('doc-09-mitre-attack-p0-7395', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-09T13:02:23.854Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Scan public code repositories for exposed credentials or other sensitive information before making commits. Ensure that any leaked credentials are removed from the commit history, not just the current latest version of the code.", "id": "relationship--fea72867-7ceb-4545-b138-1cef9cac24ba", "modified": "2026-04-29T14:23:06.271Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--70910fbd-58dc-4c1c-8c48-814d11fcd022", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7395', 0, 63, '09-mitre-attack', 'retrieved', 'C9191A4008BF8D16795040821750B51679866FDF2F819FBE6BEF1E3D1F57A230', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
