INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7396', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-10T14:20:55.541Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enterprise email solutions may have monitoring mechanisms that may include the ability to audit inbox rules on a regular basis. \n\nIn an Exchange environment, Administrators can use `Get-InboxRule` / `Remove-InboxRule` and `Get-TransportRule` / `Remove-TransportRule` to discover and remove potentially malicious inbox and transport rules.(Citation: Microsoft Get-InboxRule)(Citation: Microsoft Manage Mail Flow Rules 2023)", "external_references": [{"description": "Microsoft. (2023, February 22). Manage mail flow rules in Exchange Online. Retrieved March 13, 2023.", "source_name": "Microsoft Manage Mail Flow Rules 2023", "url": "https://learn.microsoft.com/en-us/exchange/security-and-compliance/mail-flow-rules/manage-mail-flow-rules"}, {"description": "Microsoft. (n.d.). Get-InboxRule. Retrieved June 10, 2021.", "source_name": "Microsoft Get-InboxRule", "url": "https://docs.microsoft.com/en-us/powershell/module/exchange/get-inboxrule?view=exchange-ps"}], "id": "relationship--3b2ca38e-351d-4595-8ddb-17b648f196ef", "modified": "2026-08-04T20:30:53.844Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--0cf55441-b176-4332-89e7-2c4c7799d0ff", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7396', 0, 120, '09-mitre-attack', 'retrieved', '245A421C23362233DE6DC6DC376E236B098234CA6843A6E5F04ACBFD1D2E7647', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7397', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-03T03:26:54.611Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Check and remediate unneeded existing authentication certificates as well as common abusable misconfigurations of CA settings and permissions, such as AD CS certificate enrollment permissions and published overly permissive certificate templates (which define available settings for created certificates). For example, available AD CS certificate templates can be checked via the Certificate Authority MMC snap-in (`certsrv.msc`). `certutil.exe` can also be used to examine various information within an AD CS CA database.(Citation: SpecterOps Certified Pre Owned)(Citation: GitHub PSPKIAudit)(Citation: GitHub Certify)", "external_references": [{"description": "HarmJ0y et al. (2021, June 16). PSPKIAudit. Retrieved August 2, 2022.", "source_name": "GitHub PSPKIAudit", "url": "https://github.com/GhostPack/PSPKIAudit"}, {"description": "HarmJ0y et al. (2021, June 9). Certify. Retrieved August 4, 2022.", "source_name": "GitHub Certify", "url": "https://github.com/GhostPack/Certify/"}, {"description": "Schroeder, W. & Christensen, L. (2021, June 22). Certified Pre-Owned - Abusing Active Directory Certificate Services. Retrieved August 2, 2022.", "source_name": "SpecterOps Certified Pre Owned", "url": "https://web.archive.org/web/20220818094600/https://specterops.io/assets/resources/Certified_Pre-Owned.pdf"}], "id": "relationship--d3a4a83f-fac1-4e28-b1e8-183aabffaa34", "modified": "2026-08-04T20:30:55.381Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--cc2399fd-3cd3-4319-8d0a-fbd6420cdaf8", "spec_version": "2.1", "target_ref": "attack-pattern--7de1f7ac-5d0c-4c9c-8873-627202205331", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7397', 0, 170, '09-mitre-attack', 'retrieved', 'F09867C4F0BC858824204463A859A5F6A3A52C870750C562B03B396FFF1953F3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
