VALUES ('doc-09-mitre-attack-p0-7400', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-24T13:38:13.121Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Security applications that look for behavior used during exploitation such as Windows Defender Exploit Guard (WDEG) and the Enhanced Mitigation Experience Toolkit (EMET) can be used to mitigate some exploitation behavior.(Citation: TechNet Moving Beyond EMET) Control flow integrity checking is another way to potentially identify and stop a software exploit from occurring.(Citation: Wikipedia Control Flow Integrity) Many of these protections depend on the architecture and target application binary for compatibility.", "external_references": [{"description": "Nunez, N. (2017, August 9). Moving Beyond EMET II – Windows Defender Exploit Guard. Retrieved March 12, 2018.", "source_name": "TechNet Moving Beyond EMET", "url": "https://blogs.technet.microsoft.com/srd/2017/08/09/moving-beyond-emet-ii-windows-defender-exploit-guard/"}, {"description": "Wikipedia. (2018, January 11). Control-flow integrity. Retrieved March 12, 2018.", "source_name": "Wikipedia Control Flow Integrity", "url": "https://en.wikipedia.org/wiki/Control-flow_integrity"}], "id": "relationship--1e6c88fb-11fc-481d-990a-81d74a69e02f", "modified": "2026-04-29T14:23:05.946Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--d2a24649-9694-4c97-9c62-ce7b270bf6a3", "spec_version": "2.1", "target_ref": "attack-pattern--d742a578-d70e-4d0e-96a6-02a9c30204e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7400', 0, 144, '09-mitre-attack', 'retrieved', 'EFEA3BB33240CAEAEA84629856493901A388914999E5C569D8EE8D1BB0340938', 'v1', '{"source_id": "0