VALUES ('doc-09-mitre-attack-p0-7401', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-29T17:17:31.571Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Microsoft''s Enhanced Mitigation Experience Toolkit (EMET) Attack Surface Reduction (ASR) feature can be used to block methods of using using trusted binaries to bypass application control.", "id": "relationship--1f1de0ea-581b-4b41-953f-1b8f552f84e7", "modified": "2026-04-29T14:23:05.947Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--d2a24649-9694-4c97-9c62-ce7b270bf6a3", "spec_version": "2.1", "target_ref": "attack-pattern--457c7820-d331-465a-915e-42f85500ccc4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7401', 0, 55, '09-mitre-attack', 'retrieved', 'A3BA76236F2F727F64E90322188C391159DB6B0A43340C925F67408079481AD1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
