VALUES ('doc-09-mitre-attack-p0-7405', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-17T20:50:44.740Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Web Application Firewalls may be used to limit exposure of applications to prevent exploit traffic from reaching the application.", "id": "relationship--53a95297-1cce-401c-99a3-34079e878fac", "modified": "2026-04-29T14:23:06.039Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--d2a24649-9694-4c97-9c62-ce7b270bf6a3", "spec_version": "2.1", "target_ref": "attack-pattern--3f886f2a-874f-4333-b794-aa6075009b1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7405', 0, 48, '09-mitre-attack', 'retrieved', 'EC581784B6DAC8FB5B655A781C46EF674AF3C401B159E9867B93968FC25035D3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
