VALUES ('doc-09-mitre-attack-p0-7408', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T17:38:45.809Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use utilities that detect or mitigate common features used in exploitation, such as the Microsoft Enhanced Mitigation Experience Toolkit (EMET).", "id": "relationship--f66af3ae-266c-4aa1-a6b4-f1ff87aff601", "modified": "2026-04-29T14:23:06.260Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--d2a24649-9694-4c97-9c62-ce7b270bf6a3", "spec_version": "2.1", "target_ref": "attack-pattern--246fd3c7-f5e3-466d-8787-4c13d9e3b61c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7408', 0, 49, '09-mitre-attack', 'retrieved', '0DD378D482B0B534CA5C274086AA08924D1666E9814AC56507BB6C96D6A428EF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
