VALUES ('doc-09-mitre-attack-p0-7412', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-04T13:42:40.694Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Remove vulnerable Group Policy Preferences.(Citation: Microsoft MS14-025)", "external_references": [{"description": "Microsoft. (2014, May 13). MS14-025: Vulnerability in Group Policy Preferences could allow elevation of privilege. Retrieved January 28, 2015.", "source_name": "Microsoft MS14-025", "url": "http://support.microsoft.com/kb/2962486"}], "id": "relationship--2b36db33-4f97-4228-bcca-4f453d1bd533", "modified": "2026-04-29T14:23:05.963Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e3388c78-2a8d-47c2-8422-c1398b324462", "spec_version": "2.1", "target_ref": "attack-pattern--435dfb86-2697-4867-85b5-2fef496c0517", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7412', 0, 62, '09-mitre-attack', 'retrieved', '11818EB288F79531C6969F5751CEBEE7A5257F5246D5F7EDAB908B5FD3C2859F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
