VALUES ('doc-09-mitre-attack-p0-7414', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-22T20:09:08.229Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For containing the impact of a previously forged SAML token, rotate the token-signing AD FS certificate in rapid succession twice, which will invalidate any tokens generated using the previous certificate.(Citation: Mandiant Defend UNC2452 White Paper)", "external_references": [{"description": "Mandiant. (2021, January 19). Remediation and Hardening Strategies for Microsoft 365 to Defend Against UNC2452. Retrieved January 22, 2021.", "source_name": "Mandiant Defend UNC2452 White Paper", "url": "https://www.mandiant.com/resources/blog/remediation-and-hardening-strategies-for-microsoft-365-to-defend-against-unc2452"}], "id": "relationship--3278a7a8-bf61-45bc-9553-872f222f699d", "modified": "2026-04-29T14:23:05.985Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e3388c78-2a8d-47c2-8422-c1398b324462", "spec_version": "2.1", "target_ref": "attack-pattern--1f9c2bae-b441-4f66-a8af-b65946ee72f2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7414', 0, 93, '09-mitre-attack', 'retrieved', '5F4142180A17F14ACBC9503ABBA51DBB913E9A6F0151FEF8DD44A8D2EB2AAE9C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
