VALUES ('doc-09-mitre-attack-p0-7415', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-29T16:34:40.452Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider adding users to the \"Protected Users\" Active Directory security group. This can help limit the caching of users'' plaintext credentials.(Citation: Microsoft Protected Users Security Group)", "external_references": [{"description": "Microsoft. (2016, October 12). Protected Users Security Group. Retrieved May 29, 2020.", "source_name": "Microsoft Protected Users Security Group", "url": "https://docs.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group"}], "id": "relationship--6c1da818-6e35-4fa8-ad40-e45c2c90e016", "modified": "2026-04-29T14:23:06.072Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e3388c78-2a8d-47c2-8422-c1398b324462", "spec_version": "2.1", "target_ref": "attack-pattern--6add2ab5-2711-4e9d-87c8-7a0be8531530", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7415', 0, 77, '09-mitre-attack', 'retrieved', 'D7A8756A447A7DBBFD8E703AE0DECD0918FF27FA6FC821C0404A7B39C5986B87', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
