VALUES ('doc-09-mitre-attack-p0-7419', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T17:03:43.477Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "To contain the impact of a previously generated golden ticket, reset the built-in KRBTGT account password twice, which will invalidate any existing golden tickets that have been created with the KRBTGT hash and other Kerberos tickets derived from it.(Citation: ADSecurity Kerberos and KRBTGT) For each domain, change the KRBTGT account password once, force replication, and then change the password a second time. Consider rotating the KRBTGT account password every 180 days.(Citation: STIG krbtgt reset)", "external_references": [{"description": "Sean Metcalf. (2014, November 10). Kerberos & KRBTGT: Active Directory’s Domain Kerberos Service Account. Retrieved January 30, 2020.", "source_name": "ADSecurity Kerberos and KRBTGT", "url": "https://adsecurity.org/?p=483"}, {"description": "UCF. (n.d.). The password for the krbtgt account on a domain must be reset at least every 180 days. Retrieved November 5, 2020.", "source_name": "STIG krbtgt reset", "url": "https://web.archive.org/web/20240428080127/https://www.stigviewer.com/stig/windows_server_2016/2019-12-12/finding/V-91779"}], "id": "relationship--918a7d67-faea-4a41-9ed3-e3558fca73db", "modified": "2026-06-13T16:30:19.686Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e3388c78-2a8d-47c2-8422-c1398b324462", "spec_version": "2.1", "target_ref": "attack-pattern--7b211ac6-c815-4189-93a9-ab415deca926", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7419', 0, 160, '09-mitre-attack', 'retrieved', '4B5D3F2B4F7DD92AD028B1273C64EF1AA18020A8F65AA600029304516670599E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
