INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7420', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-27T17:55:27.440Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For containing the impact of a previously generated golden ticket, reset the built-in KRBTGT account password twice, which will invalidate any existing golden tickets that have been created with the KRBTGT hash and other Kerberos tickets derived from it. For each domain, change the KRBTGT account password once, force replication, and then change the password a second time. Consider rotating the KRBTGT account password every 180 days.(Citation: STIG krbtgt reset)", "external_references": [{"description": "UCF. (n.d.). The password for the krbtgt account on a domain must be reset at least every 180 days. Retrieved November 5, 2020.", "source_name": "STIG krbtgt reset", "url": "https://web.archive.org/web/20240428080127/https://www.stigviewer.com/stig/windows_server_2016/2019-12-12/finding/V-91779"}], "id": "relationship--f6d6f916-ca2a-4c25-841f-02d71b31308c", "modified": "2026-06-13T16:30:19.686Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e3388c78-2a8d-47c2-8422-c1398b324462", "spec_version": "2.1", "target_ref": "attack-pattern--768dce68-8d0d-477a-b01d-0eea98b963a1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7420', 0, 130, '09-mitre-attack', 'retrieved', 'D762ACD8791529F82E6DB7E0D1C9C7CDFBC029FC810881393D7A14813A0858AC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
