INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7421', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-03T03:28:35.977Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure certificate authorities (CA) are properly secured, including treating CA servers (and other resources hosting CA certificates) as tier 0 assets. Harden abusable CA settings and attributes.\n\nFor example, consider disabling the usage of AD CS certificate SANs within relevant authentication protocol settings to enforce strict user mappings and prevent certificates from authenticating as other identifies.(Citation: SpecterOps Certified Pre Owned) Also consider enforcing CA Certificate Manager approval for the templates that include SAN as an issuance requirement.", "external_references": [{"description": "Schroeder, W. & Christensen, L. (2021, June 22). Certified Pre-Owned - Abusing Active Directory Certificate Services. Retrieved August 2, 2022.", "source_name": "SpecterOps Certified Pre Owned", "url": "https://www.specterops.io/assets/resources/Certified_Pre-Owned.pdf"}], "id": "relationship--35228466-b834-474f-8657-a3492a3579b6", "modified": "2026-08-04T20:30:55.297Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e3388c78-2a8d-47c2-8422-c1398b324462", "spec_version": "2.1", "target_ref": "attack-pattern--7de1f7ac-5d0c-4c9c-8873-627202205331", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7421', 0, 134, '09-mitre-attack', 'retrieved', '7DCFF40B76D9C66766E129098D66ECAADF84B28D4FE27F19FC8E89767A2A649D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
