VALUES ('doc-09-mitre-attack-p0-7422', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T16:36:51.580Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Apply patch KB2871997 to Windows 7 and higher systems to limit the default access of accounts in the local administrator group.(Citation: NSA Spotting) ", "external_references": [{"description": "National Security Agency/Central Security Service Information Assurance Directorate. (2015, August 7). Spotting the Adversary with Windows Event Log Monitoring. Retrieved September 6, 2018.", "source_name": "NSA Spotting", "url": "https://massarobi.wordpress.com/wp-content/uploads/2017/03/spotting-the-adversary-with-windows-event-log-monitoring.pdf"}], "id": "relationship--0c0cd7a2-496b-458d-b041-e05816450502", "modified": "2026-04-29T14:23:05.920Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e5d930e9-775a-40ad-9bdb-b941d8dfe86b", "spec_version": "2.1", "target_ref": "attack-pattern--e624264c-033a-424d-9fd7-fc9c3bbdb03e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7422', 0, 83, '09-mitre-attack', 'retrieved', '78B8A46551EB6DB10407D183ACA61A80D3BF774D66F94BD277FA9B48F59AF008', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
