VALUES ('doc-09-mitre-attack-p0-7423', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-22T18:39:56.500Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure the network firewall is up to date with security patches.", "id": "relationship--126e0d75-d772-4af2-a47f-e92ccd8140b4", "modified": "2026-04-29T14:23:05.929Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e5d930e9-775a-40ad-9bdb-b941d8dfe86b", "spec_version": "2.1", "target_ref": "attack-pattern--a29aa77c-a88d-4f19-bab9-7751941b2e2d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7423', 0, 40, '09-mitre-attack', 'retrieved', '933EA9903DD0721A33FAEEBA5E8F5717773F82BBFCF619F5AD881C1046734E3F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
