VALUES ('doc-09-mitre-attack-p0-7425', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-30T22:25:58.519Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure operating systems and IDEs are using the most current version. ", "id": "relationship--19913bf1-7180-4105-8d31-c645ed901d35", "modified": "2026-04-29T14:23:05.939Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e5d930e9-775a-40ad-9bdb-b941d8dfe86b", "spec_version": "2.1", "target_ref": "attack-pattern--66b34be7-6915-4b83-8d5a-b0f0592b5e41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7425', 0, 41, '09-mitre-attack', 'retrieved', 'EEDA22F1A3402EC7256109F2314F6044828E55C7030DFDD966916DCF7530C4B5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
