VALUES ('doc-09-mitre-attack-p0-7426', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-25T19:57:54.836Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider updating Windows to the latest version and patch level to utilize the latest protective measures against UAC bypass.(Citation: Github UACMe)", "external_references": [{"description": "UACME Project. (2016, June 16). UACMe. Retrieved July 26, 2016.", "source_name": "Github UACMe", "url": "https://github.com/hfiref0x/UACME"}], "id": "relationship--1b7972b8-9373-4f60-a0e5-7c1aca2c15a6", "modified": "2026-04-29T14:23:05.942Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e5d930e9-775a-40ad-9bdb-b941d8dfe86b", "spec_version": "2.1", "target_ref": "attack-pattern--120d5519-3098-4e1c-9191-2aa61232f073", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7426', 0, 67, '09-mitre-attack', 'retrieved', '92A1A61246DE0D7B6556AE12FACC8BF48B0C54169A4F65502B78A66EADCACE55', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
