VALUES ('doc-09-mitre-attack-p0-7427', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-19T23:54:29.932Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Keep system images and software updated and migrate to SNMPv3.(Citation: Cisco Blog Legacy Device Attacks)", "external_references": [{"description": "Omar Santos. (2020, October 19). Attackers Continue to Target Legacy Devices. Retrieved October 20, 2020.", "source_name": "Cisco Blog Legacy Device Attacks", "url": "https://community.cisco.com/t5/security-blogs/attackers-continue-to-target-legacy-devices/ba-p/4169954"}], "id": "relationship--21907ead-e794-49fd-aa4b-df2c51cdc599", "modified": "2026-04-29T14:23:05.951Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e5d930e9-775a-40ad-9bdb-b941d8dfe86b", "spec_version": "2.1", "target_ref": "attack-pattern--ee7ff928-801c-4f34-8a99-3df965e581a5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7427', 0, 69, '09-mitre-attack', 'retrieved', 'A2F30A3CFE30276801B440F68E7755C5C0543E52F5CFB11B7FEA2A5DB6049FC5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
