VALUES ('doc-09-mitre-attack-p0-7428', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-24T13:52:51.861Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Update software regularly by employing patch management for internal enterprise endpoints and servers.", "id": "relationship--22d11711-5794-42aa-a9c5-02895fe3420d", "modified": "2026-04-29T14:23:05.952Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e5d930e9-775a-40ad-9bdb-b941d8dfe86b", "spec_version": "2.1", "target_ref": "attack-pattern--b21c3b2d-02e6-45b1-980b-e69051040839", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7428', 0, 42, '09-mitre-attack', 'retrieved', '3E64253885705AE2EC26C9AA4544A61A56F6373BA519ED5E86D93118D9337DE0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
