VALUES ('doc-09-mitre-attack-p0-7429', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-14T14:10:02.579Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Regularly update web browsers, password managers, and all related software to the latest versions. Keeping software up-to-date reduces the risk of vulnerabilities being exploited by attackers to extract stored credentials or session cookies.", "id": "relationship--2488fee3-78ad-4ea6-b111-2d0c372b36d2", "modified": "2026-04-29T14:23:05.955Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e5d930e9-775a-40ad-9bdb-b941d8dfe86b", "spec_version": "2.1", "target_ref": "attack-pattern--315f51f0-6b03-4c1e-bfb2-84740afb8e21", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7429', 0, 62, '09-mitre-attack', 'retrieved', '6D684D9D8BB23FDCC39E71A9339287C20C838ECAADC05D4B35002B2A8DD0283C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
