VALUES ('doc-09-mitre-attack-p0-7434', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T17:26:42.105Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Patch deployment systems regularly to prevent potential remote access through [Exploitation for Privilege Escalation](https://attack.mitre.org/techniques/T1068).", "id": "relationship--33a54656-6370-4c22-af67-4ff528ba1568", "modified": "2026-04-29T14:23:05.987Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e5d930e9-775a-40ad-9bdb-b941d8dfe86b", "spec_version": "2.1", "target_ref": "attack-pattern--92a78814-b191-47ca-909c-1ccfe3777414", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7434', 0, 43, '09-mitre-attack', 'retrieved', '5266C716161EFFEAC41F3CA1CD607450973F5A6AC8EAB22C0254DDF3D71C9885', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
